const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n  refreshTokens     RefreshToken[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)\n  loyaltyEnabled    Boolean     @default(false)\n  themeSettings     Json?  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  bundles              Bundle[]\n  groupBuys            GroupBuy[]\n  milestones           Milestone[]\n  whatsappBroadcasts   WhatsappBroadcast[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  isActive        Boolean       @default(true)\n  sourceUrl       String?\n  stockQuantity   Int?\n  metadata        Json?\n  currency        String?\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n  groupBuys       GroupBuy[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  country         String?\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  fulfillmentStatus String      @default(\"UNFULFILLED\")\n  carrier         String?\n  shippedAt       DateTime?\n  paymentStatus   String      @default(\"PENDING\")\n  tax               Float       @default(0)\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  discountType  String?   // alias for type\n  discountValue Float     @default(0)\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usageLimit    Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  storeId   String?\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  metadata       Json?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n\n\n\n\n\n\n\n\n\n\nmodel RefreshToken {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token       String    @unique\n  expiresAt   DateTime\n  revokedAt   DateTime?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime  @default(now())\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel KaiMemory {\n  id         String   @id @default(uuid())\n  userId     String?\n  storeId    String?\n  key        String\n  value      String\n  category              String   @default(\"general\")\n  confidence            Float    @default(1.0)\n  sourceConversationId  String?\n  lastUsed   DateTime @default(now())\n  ttl        DateTime?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  @@unique([userId, key])\n  @@unique([storeId, key], name: \"storeId_key\")\n  @@map(\"kai_memories\")\n}\n\nmodel KaiGoal {\n  id           String   @id @default(uuid())\n  userId       String\n  storeId      String\n  title        String\n  description  String?\n  target       Float?\n  targetValue  Float?\n  current      Float    @default(0)\n  currentValue Float    @default(0)\n  unit         String   @default(\"NGN\")\n  status       String   @default(\"active\")\n  deadline     DateTime?\n  achieved     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  @@map(\"kai_goals\")\n}\n\nmodel KaiMarketCache {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  data        Json\n  category    String   @default(\"general\")\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_market_cache\")\n}\n\nmodel KaiPulseAlert {\n  id        String   @id @default(uuid())\n  storeId         String\n  userId          String?\n  type            String\n  title           String\n  message         String\n  data            Json?\n  read            Boolean  @default(false)\n  priority        String   @default(\"normal\")\n  severity        String   @default(\"info\")\n  actionable      Boolean  @default(false)\n  suggestedPrompt String?\n  createdAt  DateTime @default(now())\n  @@index([storeId])\n  @@index([userId])\n  @@map(\"kai_pulse_alerts\")\n}\n\nmodel KaiMorningBrief {\n  id                String   @id @default(uuid())\n  userId            String\n  storeId           String\n  content           String\n  date              DateTime @default(now())\n  delivered         Boolean  @default(false)\n  topOpportunity    String?\n  revenueLastNight  Float    @default(0)\n  ordersLastNight   Int      @default(0)\n  urgentAction      String?\n  @@unique([storeId, date], name: \"storeId_date\")\n  @@map(\"kai_morning_briefs\")\n}\n\nmodel KaiBrandVoice {\n  id         String   @id @default(uuid())\n  storeId    String   @unique\n  tone       String   @default(\"friendly\")\n  style      String   @default(\"conversational\")\n  keywords   String[] @default([])\n  avoidWords  String[] @default([])\n  examples    String[] @default([])\n  usesEmojis     Boolean  @default(true)\n  language       String   @default(\"en\")\n  sentenceLength String   @default(\"medium\")\n  sampleContent  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_brand_voices\")\n}\n\nmodel KaiSkill {\n  id          String   @id @default(uuid())\n  userId      String\n  storeId     String?\n  name        String\n  description String?\n  prompt      String\n  useCount    Int      @default(0)\n  usageCount  Int      @default(0)\n  active      Boolean  @default(true)\n  isGlobal    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([userId])\n  @@map(\"kai_skills\")\n}\n\nmodel LoyaltyAccount {\n  id           String   @id @default(uuid())\n  storeId      String\n  customerId   String\n  points       Int      @default(0)\n  totalEarned  Int      @default(0)\n  totalSpent     Int      @default(0)\n  totalRedeemed  Int      @default(0)\n  tier           String   @default(\"bronze\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  transactions   LoyaltyTransaction[]\n  @@unique([storeId, customerId])\n  @@map(\"loyalty_accounts\")\n}\n\nmodel ReviewRequest {\n  id         String   @id @default(uuid())\n  orderId    String   @unique\n  storeId    String\n  customerId String?\n  email      String   @default(\"\")\n  sentAt     DateTime?\n  responded  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  @@map(\"review_requests\")\n}\n\nmodel ProfitProtectionRule {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  minMargin   Float    @default(20)\n  action      String   @default(\"alert\")\n  active      Boolean  @default(true)\n  isActive    Boolean  @default(true)\n  trigger     String   @default(\"margin_drop\")\n  threshold   Float    @default(20)\n  actionValue Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([storeId])\n  @@map(\"profit_protection_rules\")\n}\n\nmodel LoyaltyTransaction {\n  id          String   @id @default(uuid())\n  accountId   String\n  account     LoyaltyAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  type        String   // earn | redeem\n  points      Int\n  orderId     String?\n  description String?\n  createdAt   DateTime @default(now())\n  @@index([accountId])\n  @@map(\"loyalty_transactions\")\n}\n\nmodel WhatsappBroadcast {\n  id             String    @id @default(uuid())\n  storeId        String\n  message        String\n  recipients     Int       @default(0)\n  recipientCount Int       @default(0)\n  sent           Int       @default(0)\n  sentCount      Int       @default(0)\n  failed         Int       @default(0)\n  status         String    @default(\"pending\")\n  scheduledAt    DateTime?\n  sentAt         DateTime?\n  store          Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  @@index([storeId])\n  @@map(\"whatsapp_broadcasts\")\n}\n","backend/src/middleware/auth.ts":"// ============================================================\n// Auth Middleware — Bulletproof\n// Path: backend/src/middleware/auth.ts\n// REPLACES existing auth middleware\n// ============================================================\nimport { Request, Response, NextFunction } from \"express\";\nexport type AuthRequest = Request & { user?: any; params: any; body: any; query: any; };\nimport { verifyAccessToken }               from \"../services/session.service\";\nimport prisma                              from \"../lib/prisma\";\n\nexport async function authenticate(req: Request, res: Response, next: NextFunction) {\n  try {\n    const header = req.headers.authorization;\n    const token  = header?.startsWith(\"Bearer \") ? header.slice(7) : null;\n\n    if (!token) {\n      return res.status(401).json({\n        success: false,\n        code:    \"NO_TOKEN\",\n        message: \"Authentication required\",\n      });\n    }\n\n    const decoded = verifyAccessToken(token);\n    if (!decoded) {\n      return res.status(401).json({\n        success: false,\n        code:    \"TOKEN_EXPIRED\",\n        message: \"Session expired — please refresh\",\n      });\n    }\n\n    // Get user from DB (with caching to avoid hitting DB on every request)\n    const cacheKey = `user_${decoded.userId}`;\n    let user = (req as any)._userCache?.[cacheKey];\n\n    if (!user) {\n      user = await prisma.user.findUnique({\n        where:   { id: decoded.userId },\n        select: {\n          id:            true,\n          name:          true,\n          email:         true,\n          role:          true,\n          status:        true,\n          avatar:        true,\n          emailVerified: true,\n          subscription:  { select: { plan: true, status: true, currentPeriodEnd: true } },\n          stores:        { select: { id: true, name: true, slug: true, status: true } },\n        },\n      });\n    }\n\n    if (!user) {\n      return res.status(401).json({\n        success: false,\n        code:    \"USER_NOT_FOUND\",\n        message: \"Account not found\",\n      });\n    }\n\n    if (user.status === \"BANNED\") {\n      return res.status(403).json({\n        success: false,\n        code:    \"ACCOUNT_BANNED\",\n        message: \"Your account has been suspended. Contact support@droposHQ.com\",\n      });\n    }\n\n    if (user.status === \"SUSPENDED\") {\n      return res.status(403).json({\n        success: false,\n        code:    \"ACCOUNT_SUSPENDED\",\n        message: \"Account suspended. Please check your email for details.\",\n      });\n    }\n\n    (req as any).user = user;\n    next();\n  } catch (err) {\n    console.error(\"[Auth]\", err);\n    return res.status(500).json({\n      success: false,\n      code:    \"AUTH_ERROR\",\n      message: \"Authentication failed — please try again\",\n    });\n  }\n}\n\n// ── Optional auth — doesn't block if no token ────────────────\n// Used for public KAI widget (works with or without login)\nexport async function optionalAuth(req: Request, res: Response, next: NextFunction) {\n  const header = req.headers.authorization;\n  const token  = header?.startsWith(\"Bearer \") ? header.slice(7) : null;\n\n  if (!token) {\n    (req as any).user = null;\n    return next();\n  }\n\n  const decoded = verifyAccessToken(token);\n  if (!decoded) {\n    (req as any).user = null;\n    return next();\n  }\n\n  try {\n    const user = await prisma.user.findUnique({\n      where:  { id: decoded.userId },\n      select: {\n        id: true, name: true, email: true, role: true, status: true,\n        stores: { select: { id: true, name: true, slug: true } },\n        subscription: { select: { plan: true } },\n      },\n    });\n    (req as any).user = user?.status === \"ACTIVE\" ? user : null;\n  } catch {\n    (req as any).user = null;\n  }\n\n  next();\n}\n\n// ── Admin only ────────────────────────────────────────────────\nexport function adminOnly(req: Request, res: Response, next: NextFunction) {\n  const user = (req as any).user;\n  if (!user || user.role !== \"SUPER_ADMIN\") {\n    return res.status(403).json({\n      success: false,\n      code:    \"FORBIDDEN\",\n      message: \"Admin access required\",\n    });\n  }\n  next();\n}\n","backend/src/middleware/customerAuth.ts":"// src/middleware/customerAuth.ts\nimport { Request, Response, NextFunction } from \"express\";\nimport jwt from \"jsonwebtoken\";\nimport { AppError } from \"../utils/AppError\";\n\nexport type CustomerAuthRequest = Request & {\n  customer?: { accountId: string; storeId: string; email: string };\n  headers: any; params: any; body: any; query: any;\n};\n\nexport const authenticateCustomer = (req: CustomerAuthRequest, _res: Response, next: NextFunction) => {\n  const header = req.headers.authorization;\n  if (!header?.startsWith(\"Bearer \")) throw new AppError(\"No customer token provided\", 401);\n\n  const token = header.split(\" \")[1];\n  try {\n    const payload = jwt.verify(token, process.env.JWT_SECRET || \"secret\") as any;\n    if (payload.type !== \"customer\") throw new AppError(\"Invalid token type\", 401);\n    req.customer = { accountId: payload.id, storeId: payload.storeId, email: payload.email };\n    next();\n  } catch (err: any) {\n    if (err.name === \"TokenExpiredError\") throw new AppError(\"Token expired\", 401);\n    throw new AppError(\"Invalid token\", 401);\n  }\n};\n","backend/src/middleware/kai.limits.ts":"// ============================================================\n// KAI — Plan Limits Middleware\n// Path: backend/src/middleware/kai.limits.ts\n// Free plan: 5 KAI messages per month\n// Growth: 200 per month\n// Pro: unlimited\n// ============================================================\nimport { Request, Response, NextFunction } from \"express\";\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\nconst PLAN_LIMITS: Record<string, number> = {\n  FREE:   5,\n  GROWTH: 200,\n  PRO:    Infinity,\n};\n\nexport async function kaiPlanLimit(req: Request, res: Response, next: NextFunction) {\n  try {\n    const user = (req as any).user;\n    if (!user?.id) return res.status(401).json({ success: false, message: \"Unauthorized\" });\n\n    // Get user's plan\n    const subscription = await prisma.subscription.findFirst({\n      where: { userId: user.id, status: \"ACTIVE\" },\n      select: { plan: true },\n    });\n\n    const plan  = subscription?.plan || \"FREE\";\n    const limit = PLAN_LIMITS[plan] ?? 5;\n\n    // Unlimited — skip check\n    if (limit === Infinity) return next();\n\n    // Count KAI messages this month\n    const monthStart = new Date();\n    monthStart.setDate(1);\n    monthStart.setHours(0, 0, 0, 0);\n\n    const storeId = req.body?.storeId;\n    if (!storeId) return next();\n\n    const messageCount = await prisma.kaiMessage.count({\n      where: {\n        role: \"user\",\n        createdAt: { gte: monthStart },\n        conversation: { storeId },\n      },\n    });\n\n    if (messageCount >= limit) {\n      return res.status(403).json({\n        success: false,\n        code: \"KAI_LIMIT_REACHED\",\n        message: plan === \"FREE\"\n          ? `You've used all ${limit} KAI messages on the Free plan this month. Upgrade to Growth for 200 messages/month.`\n          : `You've reached your ${limit} KAI message limit this month.`,\n        currentPlan: plan,\n        limit,\n        used: messageCount,\n        upgradeUrl: \"/dashboard/billing\",\n      });\n    }\n\n    // Add header so frontend can show remaining count\n    res.setHeader(\"X-KAI-Messages-Used\", messageCount.toString());\n    res.setHeader(\"X-KAI-Messages-Limit\", limit.toString());\n    res.setHeader(\"X-KAI-Messages-Remaining\", (limit - messageCount).toString());\n\n    next();\n  } catch (err) {\n    // Don't block on limit check errors\n    console.error(\"[KAI Limit]\", err);\n    next();\n  }\n}\n","backend/src/services/kai.autopilot.service.ts":"// ============================================================\n// KAI Supplier Autopilot\n// Path: backend/src/services/kai.autopilot.service.ts\n//\n// THE FULL AUTOMATION LOOP:\n//\n// 1. Order placed → CJ/Supplier notified automatically\n// 2. Supplier ships → tracking flows back automatically\n// 3. Customer gets tracking via WhatsApp + Email\n// 4. Supplier stock drops → store updates + seller alerted\n// 5. Supplier raises price → margin protected automatically\n// 6. Stock hits zero → product hidden automatically\n// 7. Morning brief includes all overnight activity\n//\n// Seller just focuses on marketing.\n// Everything else: autopilot.\n// ============================================================\nimport prisma           from \"../lib/prisma\";\nimport { getLocale }    from \"../utils/kai.locale\";\nimport { sendWhatsApp } from \"./whatsapp.service\";\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 1 — ORDER PLACED → NOTIFY SUPPLIER AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function onOrderPaid(orderId: string): Promise<void> {\n  const order = await prisma.order.findUnique({\n    where:   { id: orderId },\n    include: {\n      store:    { include: { integrations: true } },\n      customer: true,\n      items:    { include: { product: true } },\n    },\n  });\n\n  if (!order || order.status !== \"COMPLETED\") return;\n\n  const cjIntegration = order.store.integrations?.find(i => i.provider === \"cjdropshipping\" && i.isActive);\n  const locale        = getLocale(order.store.country || \"NG\");\n\n  // Categorise items by supplier\n  const cjItems = order.items.filter(i =>\n    i.product.sourceUrl?.includes(\"cjdropshipping\") ||\n    (i.product.metadata as any)?.supplier === \"cj\"\n  );\n\n  const manualItems = order.items.filter(i => !cjItems.includes(i));\n\n  // ── Auto-fulfill CJ items ───────────────────────────────────\n  if (cjItems.length > 0 && cjIntegration) {\n    await fulfillViaCJ({\n      order,\n      items:   cjItems,\n      locale,\n      apiKey:  cjIntegration.accessToken,\n      email:   cjIntegration.email!,\n      password: cjIntegration.password!,\n    });\n  }\n\n  // ── Alert seller about manual items ────────────────────────\n  if (manualItems.length > 0) {\n    const sym = locale.currencySymbol;\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId:    order.storeId,\n        type:       \"new_order_manual\",\n        severity:   \"info\",\n        title:      `New order needs your attention`,\n        message:    `Order #${orderId.slice(-8).toUpperCase()} — ${sym}${Number(order.total).toLocaleString()} — ${manualItems.length} item(s) need manual fulfillment:\\n${manualItems.map(i => `• ${i.product.name} × ${i.quantity}`).join(\"\\n\")}`,\n        actionable: true,\n        suggestedPrompt: `Help me fulfill order #${orderId.slice(-8).toUpperCase()}`,\n        data:       { orderId, manualItems: manualItems.map(i => ({ name: i.product.name, qty: i.quantity, sourceUrl: i.product.sourceUrl })) } as any,\n      },\n    }).catch(() => {});\n  }\n\n  // ── Send order confirmation to customer ─────────────────────\n  await sendOrderConfirmationToCustomer(order, locale);\n}\n\n// ── Actually place the CJ order ──────────────────────────────\nasync function fulfillViaCJ(params: {\n  order:    any;\n  items:    any[];\n  locale:   any;\n  apiKey:   string;\n  email:    string;\n  password: string;\n}): Promise<void> {\n  const { order, items, locale } = params;\n\n  try {\n    // Get CJ token\n    const authRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/authentication/getAccessToken\", {\n      method:  \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify({ email: params.email, password: params.password }),\n    });\n\n    const authData: any = await authRes.json();\n    if (!authData.data?.accessToken) throw new Error(\"CJ auth failed\");\n    const token = authData.data.accessToken;\n\n    // Place the order\n    const customer = order.customer;\n    const orderPayload = {\n      orderNumber:           order.id,\n      shippingCountryCode:   customer.country || \"NG\",\n      shippingCountry:       customer.country || \"Nigeria\",\n      shippingProvince:      customer.state   || \"\",\n      shippingCity:          customer.city    || \"\",\n      shippingAddress:       customer.address || \"\",\n      shippingCustomerName:  customer.name    || \"\",\n      shippingPhone:         customer.phone   || \"\",\n      shippingZip:           customer.zip     || \"100001\",\n      remark:                `DropOS Order — Store: ${order.store.name}`,\n      products: items.map(item => ({\n        vid:          (item.product.metadata as any)?.cjVariantId || extractCJId(item.product.sourceUrl),\n        quantity:     item.quantity,\n        shippingName: \"CJPacket Ordinary\",\n      })),\n    };\n\n    const orderRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/shopping/order/createOrderV2\", {\n      method:  \"POST\",\n      headers: { \"CJ-Access-Token\": token, \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify(orderPayload),\n    });\n\n    const orderData: any = await orderRes.json();\n\n    if (orderData.code === 200 && orderData.data?.orderId) {\n      // Update DropOS order\n      await prisma.order.update({\n        where: { id: order.id },\n        data: {\n          fulfillmentStatus: \"FULFILLED\",\n          status:            \"PROCESSING\",\n          cjOrderId:         orderData.data.orderId,\n          fulfilledAt:       new Date(),\n        } as any,\n      });\n\n      // Alert seller silently — no action needed\n      await prisma.kaiPulseAlert.create({\n        data: {\n          storeId:    order.storeId,\n          type:       \"auto_fulfilled\",\n          severity:   \"success\",\n          title:      `Order auto-fulfilled ✅`,\n          message:    `Order #${order.id.slice(-8).toUpperCase()} (${locale.currencySymbol}${Number(order.total).toLocaleString()}) was automatically sent to CJDropshipping. Tracking will arrive in 24–48 hours.`,\n          actionable: false,\n          data:       { orderId: order.id, cjOrderId: orderData.data.orderId } as any,\n        },\n      }).catch(() => {});\n\n    } else {\n      // Auto-fulfill failed — alert seller to do it manually\n      await prisma.kaiPulseAlert.create({\n        data: {\n          storeId:    order.storeId,\n          type:       \"fulfillment_failed\",\n          severity:   \"critical\",\n          title:      `⚠️ Order needs manual fulfillment`,\n          message:    `Auto-fulfillment failed for order #${order.id.slice(-8).toUpperCase()}. Reason: ${orderData.message || \"CJ error\"}. Please fulfill this order manually.`,\n          actionable: true,\n          suggestedPrompt: `Help me manually fulfill order #${order.id.slice(-8).toUpperCase()}`,\n          data:       { orderId: order.id, error: orderData.message } as any,\n        },\n      }).catch(() => {});\n    }\n  } catch (err: any) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId:    order.storeId,\n        type:       \"fulfillment_error\",\n        severity:   \"critical\",\n        title:      `⚠️ Auto-fulfillment error`,\n        message:    `Could not auto-fulfill order #${order.id.slice(-8).toUpperCase()}. Error: ${err.message}. Please check your CJ connection and fulfill manually.`,\n        actionable: true,\n        data:       { orderId: order.id } as any,\n      },\n    }).catch(() => {});\n  }\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 2 — ORDER SHIPPED → TRACKING TO CUSTOMER AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function syncAndNotifyTracking(storeId: string): Promise<number> {\n  const store = await prisma.store.findUnique({\n    where:   { id: storeId },\n    include: { integrations: true, owner: { select: { phone: true } } },\n  });\n\n  const cjIntegration = store?.integrations?.find(i => i.provider === \"cjdropshipping\" && i.isActive);\n  if (!cjIntegration) return 0;\n\n  // Get CJ token\n  const authRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/authentication/getAccessToken\", {\n    method:  \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body:    JSON.stringify({ email: cjIntegration.email, password: cjIntegration.password }),\n  });\n  const authData: any = await authRes.json();\n  if (!authData.data?.accessToken) return 0;\n  const token = authData.data.accessToken;\n\n  // Find orders that are fulfilled but no tracking yet\n  const orders = await prisma.order.findMany({\n    where: {\n      storeId,\n      fulfillmentStatus: \"FULFILLED\",\n      trackingNumber: null,\n      cjOrderId:      { not: null },\n    } as any,\n    include: { customer: { select: { name: true, email: true, phone: true } } },\n    take: 30,\n  });\n\n  let notified = 0;\n  const locale = getLocale(store?.country || \"NG\");\n\n  for (const order of orders) {\n    try {\n      const cjOrderId = (order as any).cjOrderId;\n      const res = await fetch(`https://developers.cjdropshipping.com/api2.0/v1/shopping/order/getOrderDetail?orderId=${cjOrderId}`, {\n        headers: { \"CJ-Access-Token\": token },\n      });\n\n      const data: any = await res.json();\n      const cjOrder   = data.data;\n\n      if (!cjOrder?.trackNumber) continue; // Not shipped yet\n\n      const trackingNumber = cjOrder.trackNumber;\n      const carrier        = cjOrder.logisticName || \"CJPacket\";\n      const trackingUrl    = `https://t.17track.net/en#nums=${trackingNumber}`;\n\n      // Update order\n      await prisma.order.update({\n        where: { id: order.id },\n        data: {\n          trackingNumber,\n          carrier,\n          status:    \"SHIPPED\",\n          shippedAt: new Date(),\n        } as any,\n      });\n\n      // Notify customer via WhatsApp\n      if (order.customer?.phone) {\n        const firstName = order.customer.name?.split(\" \")[0] || \"there\";\n        await sendWhatsApp({\n          to:      order.customer.phone,\n          message: `Hi ${firstName}! 📦 Your order from ${store?.name} has shipped!\\n\\nTracking: ${trackingNumber}\\nCarrier: ${carrier}\\nTrack here: ${trackingUrl}\\n\\nEstimated delivery: 7–14 days.\\n\\nThank you for shopping with us! 🙏`,\n        }).catch(() => {});\n      }\n\n      // Notify customer via email\n      await sendTrackingEmail({\n        to:           order.customer?.email || \"\",\n        customerName: order.customer?.name || \"Customer\",\n        storeName:    store?.name || \"Store\",\n        orderId:      order.id,\n        trackingNumber,\n        carrier,\n        trackingUrl,\n      }).catch(() => {});\n\n      notified++;\n      await new Promise(r => setTimeout(r, 300));\n    } catch {}\n  }\n\n  if (notified > 0) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId,\n        type:       \"tracking_synced\",\n        severity:   \"success\",\n        title:      `${notified} tracking numbers synced`,\n        message:    `${notified} customers received their tracking numbers automatically via WhatsApp and email.`,\n        actionable: false,\n        data:       { notified } as any,\n      },\n    }).catch(() => {});\n  }\n\n  return notified;\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 3 — SUPPLIER STOCK CHANGES → STORE UPDATES AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function syncSupplierStock(storeId: string): Promise<{\n  updated: number; hidden: number; alerts: string[];\n}> {\n  const store = await prisma.store.findUnique({\n    where:   { id: storeId },\n    include: { integrations: true },\n    select: { country: true, name: true, integrations: true } as any,\n  });\n\n  const locale  = getLocale((store as any)?.country || \"NG\");\n  const apiKey  = process.env.ANTHROPIC_API_KEY || \"\";\n  const updated = 0;\n  let hidden    = 0;\n  const alerts: string[] = [];\n\n  if (!apiKey) return { updated, hidden, alerts };\n\n  // Get products with CJ source URLs\n  const products = await prisma.product.findMany({\n    where: {\n      storeId, isActive: true,\n      sourceUrl: { contains: \"cjdropshipping\" },\n    },\n    select: { id: true, name: true, price: true, costPrice: true, stockQuantity: true, sourceUrl: true },\n    take: 20,\n  });\n\n  for (const product of products) {\n    if (!product.sourceUrl) continue;\n\n    try {\n      // Use KAI to check CJ product status\n      const res = await fetch(\"https://api.anthropic.com/v1/messages\", {\n        method: \"POST\",\n        headers: { \"x-api-key\": apiKey, \"anthropic-version\": \"2023-06-01\", \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          model: \"claude-haiku-4-5-20251001\",\n          max_tokens: 150,\n          tools: [{ type: \"web_search_20250305\", name: \"web_search\" }],\n          messages: [{\n            role: \"user\",\n            content: `Check if this CJDropshipping product is in stock and get current price: ${product.sourceUrl}\nReturn ONLY JSON: {\"inStock\": true, \"stockLevel\": \"high\", \"currentPriceUSD\": 5.99, \"found\": true}\nIf cannot verify: {\"inStock\": null, \"found\": false}`,\n          }],\n        }),\n      });\n\n      if (!res.ok) continue;\n      const data: any = await res.json();\n      const text = data.content?.find((b: any) => b.type === \"text\")?.text || \"{}\";\n\n      let info: any;\n      try { info = JSON.parse(text.replace(/```json|```/g, \"\").trim()); } catch { continue; }\n      if (!info.found) continue;\n\n      const newCostLocal = info.currentPriceUSD ? Math.round(info.currentPriceUSD * locale.exchangeRateToUSD) : null;\n      const oldCost      = Number(product.costPrice || 0);\n\n      // Handle out of stock\n      if (info.inStock === false) {\n        await prisma.product.update({ where: { id: product.id }, data: { isActive: false, stockQuantity: 0 } });\n        hidden++;\n        alerts.push(`\"${product.name}\" went out of stock at supplier — hidden from your store automatically`);\n      }\n\n      // Handle price increase >10%\n      if (newCostLocal && oldCost > 0 && newCostLocal > oldCost * 1.1) {\n        const changePct = Math.round(((newCostLocal - oldCost) / oldCost) * 100);\n        const newPrice  = Math.round(Number(product.price) * (1 + changePct / 100));\n\n        await prisma.product.update({\n          where: { id: product.id },\n          data:  { costPrice: newCostLocal, price: newPrice },\n        });\n\n        alerts.push(`\"${product.name}\" supplier cost increased ${changePct}% — your selling price auto-adjusted to protect margin`);\n      }\n\n      // Handle price drop >10%\n      if (newCostLocal && oldCost > 0 && newCostLocal < oldCost * 0.9) {\n        const savingPerUnit = oldCost - newCostLocal;\n        await prisma.product.update({ where: { id: product.id }, data: { costPrice: newCostLocal } });\n        alerts.push(`\"${product.name}\" supplier price dropped — you're now making ${locale.currencySymbol}${savingPerUnit.toLocaleString()} extra per sale`);\n      }\n\n      await new Promise(r => setTimeout(r, 1500));\n    } catch {}\n  }\n\n  // Create one consolidated alert instead of spamming\n  if (alerts.length > 0) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId,\n        type:       \"supplier_sync\",\n        severity:   hidden > 0 ? \"warning\" : \"info\",\n        title:      `Supplier sync: ${alerts.length} update${alerts.length > 1 ? \"s\" : \"\"}`,\n        message:    alerts.join(\"\\n\"),\n        actionable: hidden > 0,\n        data:       { alerts, hidden } as any,\n      },\n    }).catch(() => {});\n  }\n\n  return { updated: products.length, hidden, alerts };\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 4 — ORDER DELIVERED → REQUEST REVIEW AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function onOrderDelivered(orderId: string): Promise<void> {\n  // Schedule review request for 5 days later\n  // The review job in kai.reviews.service.ts picks this up\n  await prisma.order.update({\n    where: { id: orderId },\n    data:  { deliveredAt: new Date() } as any,\n  }).catch(() => {});\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 5 — ORDER CONFIRMATION TO CUSTOMER\n// ═══════════════════════════════════════════════════════════════\nasync function sendOrderConfirmationToCustomer(order: any, locale: any): Promise<void> {\n  const firstName = order.customer?.name?.split(\" \")[0] || \"there\";\n  const sym       = locale.currencySymbol;\n  const itemList  = order.items.map((i: any) => `• ${i.product.name} × ${i.quantity}`).join(\"\\n\");\n\n  // WhatsApp confirmation\n  if (order.customer?.phone) {\n    await sendWhatsApp({\n      to:      order.customer.phone,\n      message: `Hi ${firstName}! ✅ Your order from ${order.store.name} is confirmed!\\n\\nOrder: #${order.id.slice(-8).toUpperCase()}\\n${itemList}\\nTotal: ${sym}${Number(order.total).toLocaleString()}\\n\\nWe'll send your tracking number as soon as it ships. 📦`,\n    }).catch(() => {});\n  }\n\n  // Email confirmation\n  const resendKey = process.env.RESEND_API_KEY;\n  if (resendKey && order.customer?.email) {\n    await fetch(\"https://api.resend.com/emails\", {\n      method:  \"POST\",\n      headers: { Authorization: `Bearer ${resendKey}`, \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify({\n        from:    `${order.store.name} <noreply@droposHQ.com>`,\n        to:      [order.customer.email],\n        subject: `Order confirmed — #${order.id.slice(-8).toUpperCase()}`,\n        html:    `\n          <div style=\"font-family:sans-serif;max-width:500px;margin:0 auto;padding:24px\">\n            <h2>Order Confirmed ✅</h2>\n            <p>Hi ${firstName},</p>\n            <p>Your order from <strong>${order.store.name}</strong> is confirmed!</p>\n            <div style=\"background:#f9f9f9;padding:16px;border-radius:8px;margin:16px 0\">\n              <p><strong>Order:</strong> #${order.id.slice(-8).toUpperCase()}</p>\n              <p><strong>Items:</strong><br>${itemList.replace(/\\n/g, \"<br>\")}</p>\n              <p><strong>Total:</strong> ${sym}${Number(order.total).toLocaleString()}</p>\n            </div>\n            <p>We'll email and WhatsApp you your tracking number as soon as it ships.</p>\n            <p>Thank you for shopping with us! 🙏</p>\n          </div>\n        `,\n      }),\n    }).catch(() => {});\n  }\n}\n\nasync function sendTrackingEmail(params: {\n  to: string; customerName: string; storeName: string;\n  orderId: string; trackingNumber: string; carrier: string; trackingUrl: string;\n}): Promise<void> {\n  const resendKey = process.env.RESEND_API_KEY;\n  if (!resendKey || !params.to) return;\n\n  await fetch(\"https://api.resend.com/emails\", {\n    method:  \"POST\",\n    headers: { Authorization: `Bearer ${resendKey}`, \"Content-Type\": \"application/json\" },\n    body:    JSON.stringify({\n      from:    `${params.storeName} <noreply@droposHQ.com>`,\n      to:      [params.to],\n      subject: `Your order has shipped! 📦 Track it here`,\n      html:    `\n        <div style=\"font-family:sans-serif;max-width:500px;margin:0 auto;padding:24px\">\n          <h2>Your order has shipped! 📦</h2>\n          <p>Hi ${params.customerName.split(\" \")[0]},</p>\n          <p>Great news — your order from <strong>${params.storeName}</strong> is on its way!</p>\n          <div style=\"background:#f9f9f9;padding:16px;border-radius:8px;margin:16px 0\">\n            <p><strong>Tracking Number:</strong> ${params.trackingNumber}</p>\n            <p><strong>Carrier:</strong> ${params.carrier}</p>\n          </div>\n          <a href=\"${params.trackingUrl}\" style=\"display:inline-block;padding:12px 24px;background:#7c3aed;color:white;border-radius:8px;text-decoration:none;font-weight:600\">\n            📍 Track My Order\n          </a>\n          <p style=\"margin-top:16px;color:#888;font-size:13px\">Estimated delivery: 7–14 days from ship date.</p>\n        </div>\n      `,\n    }),\n  }).catch(() => {});\n}\n\nfunction extractCJId(url: string): string {\n  const match = url?.match(/vid=([^&]+)/) || url?.match(/\\/p\\/([a-zA-Z0-9-]+)/);\n  return match?.[1] || \"\";\n}\n","backend/src/services/kai.memory.service.ts":"// ============================================================\n// KAI — Memory Service\n// Path: backend/src/services/kai.memory.service.ts\n// KAI remembers everything across ALL sessions forever\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\n// ── Save a memory ─────────────────────────────────────────────\nexport async function saveMemory(\n  storeId: string,\n  category: string,\n  key: string,\n  value: string,\n  confidence = 1.0,\n  conversationId?: string\n): Promise<void> {\n  await prisma.kaiMemory.upsert({\n    where: { storeId_key: { storeId, key } },\n    create: {\n      storeId, category, key, value, confidence,\n      sourceConversationId: conversationId,\n    },\n    update: {\n      value, confidence,\n      lastUsed: new Date(),\n      sourceConversationId: conversationId,\n    },\n  });\n}\n\n// ── Get all memories for a store ──────────────────────────────\nexport async function getMemories(storeId: string, category?: string) {\n  return prisma.kaiMemory.findMany({\n    where: { storeId, ...(category && { category }) },\n    orderBy: { lastUsed: \"desc\" },\n    take: 50,\n  });\n}\n\n// ── Get memories as context string for prompt ─────────────────\nexport async function getMemoryContext(storeId: string): Promise<string> {\n  const memories = await prisma.kaiMemory.findMany({\n    where: { storeId },\n    orderBy: [{ confidence: \"desc\" }, { lastUsed: \"desc\" }],\n    take: 30,\n  });\n\n  if (memories.length === 0) return \"\";\n\n  const grouped: Record<string, typeof memories> = {};\n  for (const m of memories) {\n    if (!grouped[m.category]) grouped[m.category] = [];\n    grouped[m.category].push(m);\n  }\n\n  const lines: string[] = [\"PERSISTENT MEMORY (KAI knows this about this store):\"];\n  for (const [cat, mems] of Object.entries(grouped)) {\n    lines.push(`[${cat.replace(/_/g, \" \").toUpperCase()}]`);\n    for (const m of mems) {\n      lines.push(`  - ${m.value}`);\n    }\n  }\n\n  return lines.join(\"\\n\");\n}\n\n// ── Extract and save memories from conversation ───────────────\nexport async function extractMemoriesFromConversation(\n  storeId: string,\n  userMessage: string,\n  kaiResponse: string,\n  conversationId: string,\n  apiKey: string\n): Promise<void> {\n  // Use Claude Haiku (cheap) to extract memories\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 500,\n      messages: [{\n        role: \"user\",\n        content: `Extract business facts worth remembering from this conversation.\nReturn ONLY a JSON array. Empty array if nothing worth remembering.\n\nUser said: \"${userMessage.slice(0, 500)}\"\nKAI responded: \"${kaiResponse.slice(0, 300)}\"\n\nExtract memories like:\n- Business facts (what they sell, where they are, target market)\n- Owner preferences (what they like/dislike, how they communicate)\n- Goals they mentioned\n- Patterns they revealed (best selling day, typical customer etc)\n- Supplier notes\n- What didn't work for them\n\nFormat: [{\"category\":\"business_fact\",\"key\":\"unique_key\",\"value\":\"what to remember\",\"confidence\":0.9}]\nCategories: business_fact, owner_preference, goal, seasonal_pattern, supplier_note, customer_insight, brand_voice, failure, success\n\nReturn [] if nothing important to remember. Return raw JSON only.`,\n      }],\n    }),\n  });\n\n  if (!response.ok) return;\n\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"[]\";\n\n  try {\n    const memories = JSON.parse(text.replace(/```json|```/g, \"\").trim());\n    if (!Array.isArray(memories)) return;\n\n    for (const m of memories) {\n      if (m.category && m.key && m.value) {\n        await saveMemory(storeId, m.category, m.key, m.value, m.confidence || 0.8, conversationId);\n      }\n    }\n  } catch {}\n}\n\n// ── Mark memory as used ───────────────────────────────────────\nexport async function touchMemory(storeId: string, key: string): Promise<void> {\n  await prisma.kaiMemory.updateMany({\n    where: { storeId, key },\n    data: { lastUsed: new Date() },\n  });\n}\n\n// ── Delete a memory ───────────────────────────────────────────\nexport async function deleteMemory(storeId: string, key: string): Promise<void> {\n  await prisma.kaiMemory.deleteMany({ where: { storeId, key } });\n}\n\n// ── Get goals for context ─────────────────────────────────────\nexport async function getActiveGoals(storeId: string) {\n  return prisma.kaiGoal.findMany({\n    where: { storeId, status: \"active\" },\n    orderBy: { deadline: \"asc\" },\n    take: 3,\n  });\n}\n\n// ── Update goal progress ──────────────────────────────────────\nexport async function updateGoalProgress(goalId: string, currentValue: number): Promise<void> {\n  const goal = await prisma.kaiGoal.findUnique({\n    where: { id: goalId },\n  });\n  if (!goal) return;\n\n  const newStatus = currentValue >= goal.targetValue ? \"achieved\"\n    : new Date() > goal.deadline ? \"behind\"\n    : \"active\";\n\n  await prisma.kaiGoal.update({\n    where: { id: goalId },\n    data: { currentValue, status: newStatus, updatedAt: new Date() },\n  });\n\n  // Mark milestones achieved\n  for (const milestone of []) {\n    if (!milestone.achieved && currentValue >= milestone.targetValue) {\n      await prisma.milestone.update({\n        where: { id: milestone.id },\n        data: { achieved: true, achievedAt: new Date() },\n      });\n    }\n  }\n}\n\n// ── Get brand voice ───────────────────────────────────────────\nexport async function getBrandVoice(storeId: string) {\n  return prisma.kaiBrandVoice.findUnique({ where: { storeId } });\n}\n\n// ── Analyze and save brand voice ──────────────────────────────\nexport async function analyzeBrandVoice(\n  storeId: string,\n  sampleContent: string,\n  apiKey: string\n): Promise<void> {\n  if (!sampleContent || sampleContent.length < 50) return;\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 300,\n      messages: [{\n        role: \"user\",\n        content: `Analyze this business owner's writing style and return ONLY JSON:\n\n\"${sampleContent.slice(0, 1000)}\"\n\nReturn: {\"tone\":\"formal|casual|energetic|warm|professional\",\"usesEmojis\":true|false,\"language\":\"english|pidgin|yoruba|igbo|hausa\",\"sentenceLength\":\"short|medium|long\",\"keywords\":[\"word1\",\"word2\"],\"avoidWords\":[]}\n\nRaw JSON only.`,\n      }],\n    }),\n  });\n\n  if (!response.ok) return;\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"{}\";\n\n  try {\n    const voice = JSON.parse(text.replace(/```json|```/g, \"\").trim());\n    await prisma.kaiBrandVoice.upsert({\n      where: { storeId },\n      create: {\n        storeId,\n        tone: voice.tone || \"casual\",\n        usesEmojis: voice.usesEmojis ?? true,\n        language: voice.language || \"english\",\n        sentenceLength: voice.sentenceLength || \"medium\",\n        keywords: voice.keywords || [],\n        avoidWords: voice.avoidWords || [],\n        sampleContent: sampleContent.slice(0, 500),\n      },\n      update: {\n        tone: voice.tone || \"casual\",\n        usesEmojis: voice.usesEmojis ?? true,\n        language: voice.language || \"english\",\n        sentenceLength: voice.sentenceLength || \"medium\",\n        keywords: voice.keywords || [],\n        avoidWords: voice.avoidWords || [],\n        sampleContent: sampleContent.slice(0, 500),\n        updatedAt: new Date(),\n      },\n    });\n  } catch {}\n}\n","backend/src/services/kai.agent.service.ts":"// ============================================================\n// KAI Agent Service — Dashboard In Chat\n// Path: backend/src/services/kai.agent.service.ts\n//\n// EVERY dashboard action available through chat.\n// KAI detects intent, asks for confirmation, executes.\n// Multi-store aware — always asks which store when ambiguous.\n// ============================================================\nimport prisma from \"../lib/prisma\";\n\n// ── All actions KAI can perform ───────────────────────────────\nexport type AgentAction =\n  // Store management\n  | \"select_store\"\n  | \"get_store_info\"\n  | \"update_store_settings\"\n  | \"change_store_template\"\n  | \"toggle_store_status\"           // open/close store\n  // Products\n  | \"add_product\"\n  | \"edit_product\"\n  | \"delete_product\"\n  | \"update_product_price\"\n  | \"bulk_update_prices\"\n  | \"update_product_stock\"\n  | \"toggle_product_active\"\n  | \"duplicate_product\"\n  | \"list_products\"\n  | \"search_products\"\n  // Images\n  | \"add_product_image\"\n  | \"remove_product_image\"\n  | \"reorder_product_images\"\n  // Orders\n  | \"list_orders\"\n  | \"get_order_detail\"\n  | \"update_order_status\"\n  | \"add_order_note\"\n  | \"process_refund\"\n  | \"create_manual_order\"\n  // Inventory\n  | \"check_inventory\"\n  | \"restock_product\"\n  | \"low_stock_report\"\n  // Customers\n  | \"list_customers\"\n  | \"get_customer\"\n  | \"add_customer_note\"\n  // Coupons & Marketing\n  | \"create_coupon\"\n  | \"list_coupons\"\n  | \"delete_coupon\"\n  | \"create_flash_sale\"\n  | \"end_flash_sale\"\n  // Analytics\n  | \"get_analytics\"\n  | \"get_sales_summary\"\n  | \"get_top_products\"\n  // Shipping\n  | \"list_shipping_zones\"\n  | \"update_shipping_rate\"\n  // Settings\n  | \"update_store_name\"\n  | \"update_store_logo\"\n  | \"update_payment_settings\"\n  | \"unknown\";\n\n// ── Intent detection — maps user message to action ───────────\nexport function detectAgentAction(message: string): {\n  action: AgentAction;\n  confidence: number;\n  extractedData: Record<string, any>;\n} {\n  const m = message.toLowerCase().trim();\n\n  // ── STORE SELECTION ──────────────────────────────────────────\n  if (/which store|switch store|change store|my stores/.test(m))\n    return { action: \"select_store\", confidence: 0.95, extractedData: {} };\n\n  // ── ADD PRODUCT ───────────────────────────────────────────────\n  if (/add (a )?product|create (a )?product|new product|list (a )?product/.test(m)) {\n    const name   = extractQuoted(message) || extractAfter(message, [\"called\", \"named\", \"product\"]);\n    const price  = extractPrice(message);\n    const stock  = extractNumber(message, [\"stock\", \"units\", \"pieces\", \"qty\"]);\n    return { action: \"add_product\", confidence: 0.9, extractedData: { name, price, stock } };\n  }\n\n  // ── UPDATE PRICE ──────────────────────────────────────────────\n  if (/change (the )?price|update (the )?price|set price|price to|price of/.test(m)) {\n    const name  = extractQuoted(message);\n    const price = extractPrice(message);\n    return { action: \"update_product_price\", confidence: 0.9, extractedData: { name, price } };\n  }\n\n  // ── BULK PRICE UPDATE ─────────────────────────────────────────\n  if (/increase (all |every )?price|decrease (all |every )?price|reduce (all |every )?price|all products? (by|price)/.test(m)) {\n    const percent = extractPercent(message);\n    const amount  = extractPrice(message);\n    const direction = /increase|raise|up/.test(m) ? \"increase\" : \"decrease\";\n    return { action: \"bulk_update_prices\", confidence: 0.85, extractedData: { percent, amount, direction } };\n  }\n\n  // ── UPDATE STOCK ──────────────────────────────────────────────\n  if (/restock|update stock|set stock|stock (of|for)|add stock|units/.test(m)) {\n    const name  = extractQuoted(message);\n    const stock = extractNumber(message, [\"to\", \"stock\", \"units\", \"pieces\"]);\n    return { action: \"update_product_stock\", confidence: 0.85, extractedData: { name, stock } };\n  }\n\n  // ── DELETE PRODUCT ────────────────────────────────────────────\n  if (/delete|remove (the )?product|take down/.test(m)) {\n    const name = extractQuoted(message) || extractAfter(message, [\"delete\", \"remove\"]);\n    return { action: \"delete_product\", confidence: 0.85, extractedData: { name } };\n  }\n\n  // ── LIST PRODUCTS ─────────────────────────────────────────────\n  if (/show (my |all |)products|list (my |all |)products|what (products|items) (do i|do you)|my products/.test(m))\n    return { action: \"list_products\", confidence: 0.9, extractedData: {} };\n\n  // ── INVENTORY ─────────────────────────────────────────────────\n  if (/inventory|low stock|out of stock|stock levels|check stock/.test(m))\n    return { action: \"check_inventory\", confidence: 0.9, extractedData: {} };\n\n  // ── ORDERS ────────────────────────────────────────────────────\n  if (/show (my |all |)orders|list orders|pending orders|recent orders/.test(m))\n    return { action: \"list_orders\", confidence: 0.9, extractedData: {} };\n\n  if (/mark (as |)shipped|ship order|update order|order status|mark delivered|mark paid/.test(m)) {\n    const orderId = extractOrderId(message);\n    const status  = extractOrderStatus(message);\n    return { action: \"update_order_status\", confidence: 0.85, extractedData: { orderId, status } };\n  }\n\n  if (/refund|cancel order/.test(m)) {\n    const orderId = extractOrderId(message);\n    return { action: \"process_refund\", confidence: 0.8, extractedData: { orderId } };\n  }\n\n  // ── COUPONS ───────────────────────────────────────────────────\n  if (/create (a )?coupon|make (a )?coupon|add (a )?discount code/.test(m)) {\n    const code     = extractCode(message);\n    const discount = extractPercent(message) || extractPrice(message);\n    const type     = /percent|%/.test(m) ? \"PERCENTAGE\" : \"FIXED\";\n    return { action: \"create_coupon\", confidence: 0.9, extractedData: { code, discount, type } };\n  }\n\n  if (/show coupons|list coupons|my coupons/.test(m))\n    return { action: \"list_coupons\", confidence: 0.9, extractedData: {} };\n\n  // ── FLASH SALE ────────────────────────────────────────────────\n  if (/flash sale|run (a )?sale|start (a )?sale/.test(m)) {\n    const discount = extractPercent(message) || extractPrice(message);\n    return { action: \"create_flash_sale\", confidence: 0.85, extractedData: { discount } };\n  }\n\n  // ── ANALYTICS ─────────────────────────────────────────────────\n  if (/analytics|sales summary|how (am i|are we) doing|revenue|how much (have i|did i) make/.test(m))\n    return { action: \"get_sales_summary\", confidence: 0.9, extractedData: {} };\n\n  if (/top (selling|products)|best seller|what's selling/.test(m))\n    return { action: \"get_top_products\", confidence: 0.9, extractedData: {} };\n\n  // ── CUSTOMERS ─────────────────────────────────────────────────\n  if (/show customers|list customers|my customers|how many customers/.test(m))\n    return { action: \"list_customers\", confidence: 0.9, extractedData: {} };\n\n  // ── STORE SETTINGS ────────────────────────────────────────────\n  if (/change (my |the |store )?name|rename (my |the )?store/.test(m)) {\n    const name = extractQuoted(message) || extractAfter(message, [\"to\", \"name\"]);\n    return { action: \"update_store_name\", confidence: 0.85, extractedData: { name } };\n  }\n\n  if (/change template|switch template|use (the )?.*template|change (my |the )?theme/.test(m)) {\n    const template = extractTemplateName(message);\n    return { action: \"change_store_template\", confidence: 0.8, extractedData: { template } };\n  }\n\n  if (/close (my |the )?store|open (my |the )?store|pause (my |the )?store/.test(m)) {\n    const status = /close|pause/.test(m) ? \"INACTIVE\" : \"ACTIVE\";\n    return { action: \"toggle_store_status\", confidence: 0.9, extractedData: { status } };\n  }\n\n  if (/shipping (rate|price|zone)|change (the )?delivery/.test(m))\n    return { action: \"update_shipping_rate\", confidence: 0.8, extractedData: {} };\n\n  return { action: \"unknown\", confidence: 0, extractedData: {} };\n}\n\n// ── Execute an action against the database ────────────────────\nexport async function executeAgentAction(\n  action: AgentAction,\n  data: Record<string, any>,\n  storeId: string\n): Promise<{ success: boolean; result: any; message: string }> {\n\n  switch (action) {\n\n    case \"list_products\": {\n      const products = await prisma.product.findMany({\n        where:   { storeId },\n        select:  { id: true, name: true, price: true, stockQuantity: true, isActive: true },\n        orderBy: { createdAt: \"desc\" },\n        take:    20,\n      });\n      return {\n        success: true,\n        result:  products,\n        message: `Found ${products.length} products`,\n      };\n    }\n\n    case \"add_product\": {\n      const product = await (prisma.product as any).create({\n        data: { // @ts-ignore\n\n          storeId,\n          name:          data.name || \"New Product\",\n          price:         data.price || 0,\n          stockQuantity: data.stock || 0,\n          description:   data.description || \"\",\n          isActive:      data.publish !== false,\n          images:        data.images || [],\n          category:      data.category || \"General\",\n        },\n      });\n      return { success: true, result: product, message: `Product \"${product.name}\" created` };\n    }\n\n    case \"update_product_price\": {\n      if (!data.productId && !data.name) throw new Error(\"NEED_PRODUCT\");\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { price: data.price },\n      });\n      return { success: true, result: updated, message: `Price updated to ₦${data.price.toLocaleString()}` };\n    }\n\n    case \"bulk_update_prices\": {\n      const products = await prisma.product.findMany({ where: { storeId }, select: { id: true, price: true } });\n      if (data.percent) {\n        const multiplier = data.direction === \"increase\" ? 1 + data.percent / 100 : 1 - data.percent / 100;\n        await Promise.all(products.map(p =>\n          prisma.product.update({ where: { id: p.id }, data: { price: Math.round(Number(p.price) * multiplier) } })\n        ));\n      }\n      return { success: true, result: { count: products.length }, message: `Updated prices for ${products.length} products` };\n    }\n\n    case \"update_product_stock\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { stockQuantity: data.stock },\n      });\n      return { success: true, result: updated, message: `Stock updated to ${data.stock} units` };\n    }\n\n    case \"delete_product\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      await prisma.product.delete({ where: { id: product.id } });\n      return { success: true, result: null, message: `\"${product.name}\" deleted` };\n    }\n\n    case \"toggle_product_active\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { isActive: data.active },\n      });\n      return { success: true, result: updated, message: `\"${product.name}\" ${data.active ? \"activated\" : \"hidden\"}` };\n    }\n\n    case \"check_inventory\": {\n      const [outOfStock, lowStock, totalActive] = await Promise.all([\n        prisma.product.count({ where: { storeId, stockQuantity: 0, isActive: true } }),\n        prisma.product.findMany({ where: { storeId, stockQuantity: { gt: 0, lte: 5 }, isActive: true }, select: { name: true, stockQuantity: true }, orderBy: { stockQuantity: \"asc\" } }),\n        prisma.product.count({ where: { storeId, isActive: true } }),\n      ]);\n      return { success: true, result: { outOfStock, lowStock, totalActive }, message: \"Inventory checked\" };\n    }\n\n    case \"list_orders\": {\n      const filter: any = { storeId };\n      if (data.status) filter.status = data.status;\n      const orders = await prisma.order.findMany({\n        where:   filter,\n        include: { customer: { select: { name: true } }, items: { take: 1, include: { product: { select: { name: true } } } } },\n        orderBy: { createdAt: \"desc\" },\n        take:    10,\n      });\n      return { success: true, result: orders, message: `Found ${orders.length} orders` };\n    }\n\n    case \"update_order_status\": {\n      if (!data.orderId) throw new Error(\"NEED_ORDER_ID\");\n      const order = await prisma.order.update({\n        where: { id: data.orderId },\n        data:  { status: data.status },\n        include: { customer: { select: { name: true } } },\n      });\n      return { success: true, result: order, message: `Order marked as ${data.status}` };\n    }\n\n    case \"create_coupon\": {\n      const code = data.code || generateCouponCode();\n      const coupon = await prisma.coupon.create({\n        data: {\n          storeId,\n          code:          code.toUpperCase(),\n          discountType:  data.type || \"PERCENTAGE\",\n          value: data.discount || 10,\n          isActive:      true,\n          usageLimit:    data.limit || null,\n          expiresAt:     data.expiresAt ? new Date(data.expiresAt) : null,\n        },\n      });\n      return { success: true, result: coupon, message: `Coupon ${coupon.code} created` };\n    }\n\n    case \"list_coupons\": {\n      const coupons = await prisma.coupon.findMany({\n        where:   { storeId, isActive: true },\n        orderBy: { createdAt: \"desc\" },\n        take:    10,\n      });\n      return { success: true, result: coupons, message: `Found ${coupons.length} active coupons` };\n    }\n\n    case \"get_sales_summary\": {\n      const now         = new Date();\n      const todayStart  = new Date(now.getFullYear(), now.getMonth(), now.getDate());\n      const monthStart  = new Date(now.getFullYear(), now.getMonth(), 1);\n      const [todayOrders, monthOrders, allOrders] = await Promise.all([\n        prisma.order.findMany({ where: { storeId, createdAt: { gte: todayStart }, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, select: { total: true } }),\n        prisma.order.findMany({ where: { storeId, createdAt: { gte: monthStart }, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, select: { total: true } }),\n        prisma.order.aggregate({ where: { storeId, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, _count: true, _sum: { total: true } }),\n      ]);\n      return {\n        success: true,\n        result: {\n          revenueToday:     todayOrders.reduce((s, o) => s + Number(o.total), 0),\n          revenueThisMonth: monthOrders.reduce((s, o) => s + Number(o.total), 0),\n          totalRevenue:     Number(allOrders._sum.total || 0),\n          totalOrders:      allOrders._count,\n          ordersToday:      todayOrders.length,\n        },\n        message: \"Sales summary fetched\",\n      };\n    }\n\n    case \"get_top_products\": {\n      const topItems = await prisma.orderItem.groupBy({\n        by: [\"productId\"],\n        where: { order: { storeId, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } } },\n        _sum: { quantity: true },\n        orderBy: { _sum: { quantity: \"desc\" } },\n        take: 5,\n      });\n      const products = await Promise.all(topItems.map(async t => {\n        const p = await prisma.product.findUnique({ where: { id: t.productId }, select: { name: true, price: true } });\n        return { name: p?.name, price: p?.price, unitsSold: t._sum.quantity };\n      }));\n      return { success: true, result: products, message: \"Top products fetched\" };\n    }\n\n    case \"list_customers\": {\n      const customers = await prisma.storeCustomer.findMany({\n        where: { storeId },\n        include: { orders: { select: { total: true }, where: { status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } } } },\n        orderBy: { createdAt: \"desc\" },\n        take: 10,\n      });\n      return {\n        success: true,\n        result: customers.map(c => ({\n          id:         c.id,\n          name:       c.name,\n          email:      c.email,\n          phone:      c.phone,\n          orderCount: c.orders.length,\n          totalSpent: c.orders.reduce((s, o) => s + Number(o.total), 0),\n        })),\n        message: `Found ${customers.length} customers`,\n      };\n    }\n\n    case \"update_store_name\": {\n      const store = await prisma.store.update({\n        where: { id: storeId },\n        data:  { name: data.name },\n      });\n      return { success: true, result: store, message: `Store renamed to \"${data.name}\"` };\n    }\n\n    case \"toggle_store_status\": {\n      const store = await prisma.store.update({\n        where: { id: storeId },\n        data:  { status: data.status },\n      });\n      return { success: true, result: store, message: `Store is now ${data.status === \"ACTIVE\" ? \"open\" : \"closed\"}` };\n    }\n\n    case \"change_store_template\": {\n      await prisma.store.update({\n        where: { id: storeId },\n        data:  { themeSettings: { template: data.template } as any },\n      });\n      return { success: true, result: null, message: `Template changed to ${data.template}` };\n    }\n\n    default:\n      return { success: false, result: null, message: \"Action not recognised\" };\n  }\n}\n\n// ── Get all stores for a user ─────────────────────────────────\nexport async function getUserStores(userId: string) {\n  return prisma.store.findMany({\n    where:  { ownerId: userId },\n    select: {\n      id:     true,\n      name:   true,\n      slug:   true,\n      status: true,\n      _count: { select: { products: true, orders: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n}\n\n// ── Helpers ───────────────────────────────────────────────────\nasync function findProductByNameOrId(storeId: string, id?: string, name?: string) {\n  if (id) return prisma.product.findFirst({ where: { id, storeId } });\n  if (name) return prisma.product.findFirst({\n    where: { storeId, name: { contains: name, mode: \"insensitive\" } },\n  });\n  return null;\n}\n\nfunction extractQuoted(text: string): string | undefined {\n  const match = text.match(/[\"']([^\"']+)[\"']/) || text.match(/called\\s+([^\\s,]+)/i);\n  return match?.[1];\n}\n\nfunction extractAfter(text: string, keywords: string[]): string | undefined {\n  for (const kw of keywords) {\n    const match = text.match(new RegExp(`${kw}\\\\s+([\\\\w\\\\s]+?)(?:\\\\s+(?:at|for|to)|$)`, \"i\"));\n    if (match) return match[1].trim();\n  }\n}\n\nfunction extractPrice(text: string): number | undefined {\n  const match = text.match(/[₦$£]?\\s*(\\d[\\d,]*)/);\n  return match ? parseInt(match[1].replace(/,/g, \"\")) : undefined;\n}\n\nfunction extractNumber(text: string, after: string[]): number | undefined {\n  for (const kw of after) {\n    const match = text.match(new RegExp(`${kw}\\\\s+(\\\\d+)`, \"i\"));\n    if (match) return parseInt(match[1]);\n  }\n  const match = text.match(/\\b(\\d+)\\s*(?:units|pieces|pcs|qty)?\\b/);\n  return match ? parseInt(match[1]) : undefined;\n}\n\nfunction extractPercent(text: string): number | undefined {\n  const match = text.match(/(\\d+)\\s*%/);\n  return match ? parseInt(match[1]) : undefined;\n}\n\nfunction extractOrderId(text: string): string | undefined {\n  const match = text.match(/#?([a-z0-9]{8,})/i);\n  return match?.[1];\n}\n\nfunction extractOrderStatus(text: string): string {\n  if (/ship|shipped/.test(text))    return \"SHIPPED\";\n  if (/deliver|delivered/.test(text)) return \"DELIVERED\";\n  if (/paid|pay/.test(text))        return \"COMPLETED\";\n  if (/cancel/.test(text))          return \"CANCELLED\";\n  if (/process/.test(text))         return \"PROCESSING\";\n  return \"SHIPPED\";\n}\n\nfunction extractCode(text: string): string | undefined {\n  const match = text.match(/code\\s+([A-Z0-9]+)/i) || text.match(/\\b([A-Z]{3,}[0-9]*)\\b/);\n  return match?.[1];\n}\n\nfunction extractTemplateName(text: string): string {\n  const templates = [\"Lagos Noir\", \"Bold\", \"Classic\", \"Glow\", \"Circuit\", \"Runway\", \"Boutique\", \"Cozy\", \"Suya\", \"Feast\"];\n  for (const t of templates) {\n    if (text.toLowerCase().includes(t.toLowerCase())) return t;\n  }\n  return \"Bold\";\n}\n\nfunction generateCouponCode(): string {\n  return Math.random().toString(36).slice(2, 8).toUpperCase();\n}\n","backend/src/routes/email.routes.ts":"// src/routes/email.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\n\nconst router = Router();\n\n// POST /api/email/test — send test email to current user\nrouter.post(\"/test\", authenticate, async (req: AuthRequest, res: Response) => {\n  const user = await prisma.user.findUnique({\n    where: { id: req.user!.userId },\n    select: { email: true, name: true },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  await emailService.sendTestEmail(user.email, user.name);\n\n  const devMode = !process.env.SMTP_USER || process.env.SMTP_USER.trim() === \"\";\n\n  res.json({\n    success: true,\n    message: devMode\n      ? \"Dev mode: email logged to console (set SMTP_USER in .env to send real emails)\"\n      : `Test email sent to ${user.email}`,\n    devMode,\n  });\n});\n\n// GET /api/email/status — check email config\nrouter.get(\"/status\", authenticate, async (_req: Request, res: Response) => {\n  const devMode = !process.env.SMTP_USER || process.env.SMTP_USER.trim() === \"\";\n  res.json({\n    success: true,\n    data: {\n      configured: !devMode,\n      devMode,\n      smtpHost: process.env.SMTP_HOST || \"smtp.gmail.com\",\n      smtpPort: process.env.SMTP_PORT || \"587\",\n      from:     process.env.EMAIL_FROM || \"DropOS <noreply@dropos.io>\",\n      hint:     devMode ? \"Set SMTP_USER and SMTP_PASS in backend/.env to enable real emails\" : \"Email is configured and active\",\n    },\n  });\n});\n\n// POST /api/email/low-stock-check — manually trigger low stock check for a store\nrouter.post(\"/low-stock-check/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n\n  const store = await prisma.store.findUnique({\n    where: { id: storeId },\n    include: { owner: { select: { email: true, name: true } } },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  const lowStockProducts = await prisma.product.findMany({\n    where: { storeId, inventory: { lte: 5 } },\n    select: { name: true, sku: true, inventory: true },\n  });\n\n  if (lowStockProducts.length === 0) {\n    return res.json({ success: true, message: \"No low-stock products found\" });\n  }\n\n  await emailService.sendLowStockAlert(\n    store.owner.email,\n    store.owner.name,\n    lowStockProducts,\n    store.name\n  );\n\n  res.json({\n    success: true,\n    message: `Low stock alert sent for ${lowStockProducts.length} product(s)`,\n    data: lowStockProducts,\n  });\n});\n\nexport default router;\n\n// POST /api/email/weekly-digest/:storeId — trigger weekly digest for a store\nrouter.post(\"/weekly-digest/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const store = await prisma.store.findUnique({\n    where:   { id: req.params.storeId },\n    include: { owner: { select: { email: true, name: true } } },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);\n  const orders  = await prisma.order.findMany({\n    where:   { storeId: req.params.storeId, createdAt: { gte: weekAgo }, status: \"COMPLETED\" },\n    include: { items: { include: { product: { select: { name: true } } } } },\n  });\n\n  const revenue      = orders.reduce((s, o) => s + Number(o.total), 0);\n  const newCustomers = await prisma.storeCustomer.count({ where: { storeId: req.params.storeId, createdAt: { gte: weekAgo } } });\n\n  // Top product by quantity sold\n  const productCount: Record<string, { name: string; qty: number }> = {};\n  orders.forEach(o => o.items.forEach((i: any) => {\n    const name = i.product?.name || i.productName || \"Unknown\";\n    if (!productCount[name]) productCount[name] = { name, qty: 0 };\n    productCount[name].qty += i.quantity;\n  }));\n  const topProduct = Object.values(productCount).sort((a, b) => b.qty - a.qty)[0]?.name || \"—\";\n\n  await emailService.sendWeeklyDigest(store.owner.email, store.owner.name, {\n    storeName: store.name, revenue, orders: orders.length,\n    newCustomers, topProduct, currency: store.currency || \"USD\",\n  });\n\n  res.json({ success: true, message: \"Weekly digest sent\", data: { revenue, orders: orders.length, newCustomers, topProduct } });\n});\n\n// POST /api/email/refund/:orderId — trigger refund email\nrouter.post(\"/refund/:orderId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const order = await prisma.order.findUnique({\n    where:   { id: req.params.orderId },\n    include: { store: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  const sym = (order.store as any)?.currency === \"NGN\" ? \"₦\" : \"$\";\n  await emailService.sendRefundProcessed(\n    order.customerEmail, order.customerName, order.orderNumber,\n    `${sym}${Number(order.total).toFixed(2)}`, (order.store as any)?.name || \"Store\"\n  );\n  res.json({ success: true, message: \"Refund email sent\" });\n});\n","backend/src/routes/supplier.routes.ts":"// src/routes/supplier.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { authenticate, AuthRequest } from \"../middleware/auth\";\nimport { AppError } from \"../utils/AppError\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\nimport { supplierService, FulfillmentPayload } from \"../services/supplier.service\";\n\nconst router = Router();\n\n// ── All routes require auth ───────────────────────────────────────────────────\nrouter.use(authenticate);\n\n// ── GET /api/suppliers/:storeId — list all suppliers ─────────────────────────\nrouter.get(\"/:storeId\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const suppliers = await prisma.supplier.findMany({\n    where:   { storeId },\n    include: {\n      _count: { select: { products: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return res.json({ success: true, data: suppliers });\n});\n\n// ── POST /api/suppliers/:storeId — create supplier ────────────────────────────\nrouter.post(\"/:storeId\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const data = z.object({\n    name:         z.string().min(1).max(200),\n    type:         z.enum([\"MANUAL\",\"ALIEXPRESS\",\"CSV\",\"WEBHOOK\"]).default(\"MANUAL\"),\n    websiteUrl:   z.string().url().optional().or(z.literal(\"\")),\n    apiKey:       z.string().optional(),\n    apiSecret:    z.string().optional(),\n    contactEmail: z.string().email().optional().or(z.literal(\"\")),\n    contactName:  z.string().optional(),\n    notes:        z.string().optional(),\n    autoFulfill:  z.boolean().default(false),\n    fulfillEmail: z.string().email().optional().or(z.literal(\"\")),\n    webhookUrl:   z.string().url().optional().or(z.literal(\"\")),\n  }).parse(req.body);\n\n  const supplier = await (prisma.supplier as any).create({\n    data: { ...data, storeId },\n  });\n\n  return res.status(201).json({ success: true, data: supplier });\n});\n\n// ── PUT /api/suppliers/:storeId/:supplierId — update supplier ─────────────────\nrouter.put(\"/:storeId/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const supplier = await prisma.supplier.findFirst({ where: { id: supplierId, storeId } });\n  if (!supplier) throw new AppError(\"Supplier not found\", 404);\n\n  const data = z.object({\n    name:         z.string().min(1).max(200).optional(),\n    type:         z.enum([\"MANUAL\",\"ALIEXPRESS\",\"CSV\",\"WEBHOOK\"]).optional(),\n    websiteUrl:   z.string().optional(),\n    apiKey:       z.string().optional(),\n    apiSecret:    z.string().optional(),\n    contactEmail: z.string().optional(),\n    contactName:  z.string().optional(),\n    notes:        z.string().optional(),\n    isActive:     z.boolean().optional(),\n    autoFulfill:  z.boolean().optional(),\n    fulfillEmail: z.string().optional(),\n    webhookUrl:   z.string().optional(),\n  }).parse(req.body);\n\n  const updated = await prisma.supplier.update({\n    where: { id: supplierId },\n    data,\n  });\n\n  return res.json({ success: true, data: updated });\n});\n\n// ── DELETE /api/suppliers/:storeId/:supplierId ────────────────────────────────\nrouter.delete(\"/:storeId/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const supplier = await prisma.supplier.findFirst({ where: { id: supplierId, storeId } });\n  if (!supplier) throw new AppError(\"Supplier not found\", 404);\n\n  await prisma.supplier.delete({ where: { id: supplierId } });\n  return res.json({ success: true, message: \"Supplier deleted\" });\n});\n\n// ── POST /api/suppliers/:storeId/import/url — scrape product from URL ─────────\nrouter.post(\"/:storeId/import/url\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { url } = z.object({ url: z.string().url() }).parse(req.body);\n\n  const scraped = await supplierService.scrapeProductUrl(url);\n  return res.json({ success: true, data: scraped });\n});\n\n// ── POST /api/suppliers/:storeId/import/save — save scraped product ───────────\nrouter.post(\"/:storeId/import/save\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:      z.string().optional(),\n    // Product fields\n    name:            z.string().min(1),\n    description:     z.string().default(\"\"),\n    price:           z.number().positive(),\n    comparePrice:    z.number().optional(),\n    costPrice:       z.number().optional(),   // supplier price\n    images:          z.array(z.string()).default([]),\n    category:        z.string().optional(),\n    inventory:       z.number().int().min(0).default(50),\n    status:          z.enum([\"ACTIVE\",\"DRAFT\"]).default(\"DRAFT\"),\n    // Supplier link fields\n    supplierUrl:     z.string().optional(),\n    supplierSku:     z.string().optional(),\n    supplierPrice:   z.number().optional(),\n    supplierCurrency:z.string().default(\"USD\"),\n    processingDays:  z.number().optional(),\n    shippingDays:    z.number().optional(),\n  }).parse(req.body);\n\n  // Check product plan limits\n  const sub = await prisma.subscription.findFirst({\n    where: { user: { stores: { some: { id: storeId } } } },\n  });\n  const plan = sub?.plan || \"STARTER\";\n  const limits: Record<string, number> = { STARTER: 50, PRO: 500, ADVANCED: 999999 };\n  const count = await prisma.product.count({ where: { storeId } });\n  if (count >= (limits[plan] ?? 50)) {\n    throw new AppError(`Product limit reached for your ${plan} plan`, 403);\n  }\n\n  // Slugify name\n  const base = body.name.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-|-$/g, \"\");\n  let slug = base;\n  let i = 1;\n  while (await prisma.product.findFirst({ where: { storeId, slug } })) {\n    slug = `${base}-${i++}`;\n  }\n\n  // Create product\n  const product = await prisma.product.create({\n    data: {\n      storeId,\n      slug,\n      name:         body.name,\n      description:  body.description,\n      price:        body.price,\n      comparePrice: body.comparePrice,\n      costPrice:    body.costPrice ?? body.supplierPrice,\n      images:       body.images,\n      category:     body.category,\n      inventory:    body.inventory,\n      status:       body.status,\n    },\n  });\n\n  // Link to supplier if supplierId provided\n  if (body.supplierId && (body.supplierUrl || body.supplierSku)) {\n    await prisma.supplierProduct.upsert({\n      where:  { supplierId_productId: { supplierId: body.supplierId, productId: product.id } },\n      create: {\n        supplierId:       body.supplierId,\n        productId:        product.id,\n        supplierUrl:      body.supplierUrl,\n        supplierSku:      body.supplierSku,\n        supplierPrice:    body.supplierPrice,\n        supplierCurrency: body.supplierCurrency,\n        processingDays:   body.processingDays,\n        shippingDays:     body.shippingDays,\n        lastSynced:       new Date(),\n        stockStatus:      \"IN_STOCK\",\n      },\n      update: {\n        supplierUrl:      body.supplierUrl,\n        supplierSku:      body.supplierSku,\n        supplierPrice:    body.supplierPrice,\n        supplierCurrency: body.supplierCurrency,\n        processingDays:   body.processingDays,\n        shippingDays:     body.shippingDays,\n        lastSynced:       new Date(),\n      },\n    });\n  }\n\n  return res.status(201).json({ success: true, data: product });\n});\n\n// ── GET /api/suppliers/:storeId/products — list supplier-linked products ──────\nrouter.get(\"/:storeId/products/linked\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const linked = await prisma.supplierProduct.findMany({\n    where:   { product: { storeId } },\n    include: {\n      supplier: { select: { id: true, name: true, type: true } },\n      product:  { select: { id: true, name: true, price: true, costPrice: true, status: true, images: true, inventory: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return res.json({ success: true, data: linked });\n});\n\n// ── PUT /api/suppliers/:storeId/products/:productId/link ──────────────────────\nrouter.put(\"/:storeId/products/:productId/link\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:       z.string(),\n    supplierUrl:      z.string().optional(),\n    supplierSku:      z.string().optional(),\n    supplierPrice:    z.number().optional(),\n    supplierCurrency: z.string().default(\"USD\"),\n    processingDays:   z.number().optional(),\n    shippingDays:     z.number().optional(),\n  }).parse(req.body);\n\n  const link = await prisma.supplierProduct.upsert({\n    where:  { supplierId_productId: { supplierId: body.supplierId, productId } },\n    create: { ...body, productId, lastSynced: new Date(), stockStatus: \"IN_STOCK\" },\n    update: { ...body, lastSynced: new Date() },\n  });\n\n  // Also update product costPrice\n  if (body.supplierPrice) {\n    await prisma.product.update({\n      where: { id: productId },\n      data:  { costPrice: body.supplierPrice },\n    });\n  }\n\n  return res.json({ success: true, data: link });\n});\n\n// ── DELETE /api/suppliers/:storeId/products/:productId/link/:supplierId ────────\nrouter.delete(\"/:storeId/products/:productId/link/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  await prisma.supplierProduct.deleteMany({\n    where: { productId, supplierId },\n  });\n\n  return res.json({ success: true, message: \"Supplier link removed\" });\n});\n\n// ── POST /api/suppliers/:storeId/fulfill/:orderId — manual trigger ─────────────\nrouter.post(\"/:storeId/fulfill/:orderId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, orderId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const order = await prisma.order.findFirst({\n    where:   { id: orderId, storeId },\n    include: { items: { include: { product: { include: { supplierProducts: { include: { supplier: true } } } } } } },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { name: true } });\n\n  // Group items by supplier\n  const bySupplier = new Map<string, { supplier: any; items: typeof order.items }>();\n\n  for (const item of order.items) {\n    const link = item.product.supplierProducts?.[0];\n    if (!link?.supplier) continue;\n    const sup = link.supplier;\n    if (!bySupplier.has(sup.id)) bySupplier.set(sup.id, { supplier: sup, items: [] });\n    bySupplier.get(sup.id)!.items.push(item);\n  }\n\n  if (bySupplier.size === 0) {\n    return res.status(400).json({ success: false, message: \"No suppliers linked to items in this order\" });\n  }\n\n  const results: Array<{ supplierId: string; supplierName: string; method: string; success: boolean }> = [];\n\n  for (const [, { supplier, items }] of bySupplier) {\n    const payload: FulfillmentPayload = {\n      orderNumber:     order.orderNumber,\n      orderId:         order.id,\n      customerName:    order.customerName,\n      customerEmail:   order.customerEmail,\n      customerPhone:   order.customerPhone,\n      shippingAddress: order.shippingAddress,\n      storeName:       store?.name ?? storeId,\n      storeId,\n      total:           order.total,\n      currency:        order.currency,\n      notes:           order.notes,\n      items: items.map(i => ({\n        name:        i.name,\n        sku:         i.sku,\n        quantity:    i.quantity,\n        price:       i.price,\n        supplierSku: i.product.supplierProducts?.[0]?.supplierSku ?? null,\n        supplierUrl: i.product.supplierProducts?.[0]?.supplierUrl ?? null,\n      })),\n    };\n\n    let method = \"MANUAL\";\n    let success = false;\n\n    if (supplier.webhookUrl) {\n      method = \"WEBHOOK\";\n      success = await supplierService.fulfillOrderByWebhook(supplier.webhookUrl, payload);\n    } else if (supplier.fulfillEmail) {\n      method = \"EMAIL\";\n      success = await supplierService.fulfillOrderByEmail(supplier.fulfillEmail, supplier.name, payload);\n    } else {\n      method = \"MANUAL\";\n      success = true; // logged as manual\n    }\n\n    // Record fulfillment\n    await prisma.fulfillmentOrder.create({\n      data: {\n        orderId:    order.id,\n        supplierId: supplier.id,\n        storeId,\n        status:     success ? \"SENT\" : \"FAILED\",\n        sentAt:     success ? new Date() : undefined,\n        method,\n        payload:    payload as any,\n      },\n    });\n\n    results.push({ supplierId: supplier.id, supplierName: supplier.name, method, success });\n  }\n\n  return res.json({ success: true, data: results });\n});\n\n// ── GET /api/suppliers/:storeId/fulfillments — list fulfillment records ────────\nrouter.get(\"/:storeId/fulfillments\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const fulfillments = await prisma.fulfillmentOrder.findMany({\n    where:   { storeId },\n    include: { supplier: { select: { id: true, name: true, type: true } } },\n    orderBy: { createdAt: \"desc\" },\n    take:    50,\n  });\n\n  return res.json({ success: true, data: fulfillments });\n});\n\n// ── POST /api/suppliers/:storeId/import/url/batch — scrape multiple URLs ──────\nrouter.post(\"/:storeId/import/url/batch\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { urls } = z.object({\n    urls: z.array(z.string().url()).max(10),\n  }).parse(req.body);\n\n  const results = await Promise.allSettled(\n    urls.map(url => supplierService.scrapeProductUrl(url))\n  );\n\n  const data = results.map((r, i) => ({\n    url:     urls[i],\n    success: r.status === \"fulfilled\",\n    data:    r.status === \"fulfilled\" ? r.value : null,\n    error:   r.status === \"rejected\"  ? r.reason?.message : null,\n  }));\n\n  return res.json({ success: true, data });\n});\n\n// ── GET /api/suppliers/:storeId/products/:productId/suppliers ─────────────────\nrouter.get(\"/:storeId/products/:productId/suppliers\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const assignments = await prisma.supplierProduct.findMany({\n    where: { productId, product: { storeId } },\n    include: { supplier: { select: { id: true, name: true, type: true, isActive: true } } },\n    orderBy: { priority: \"asc\" },\n  });\n\n  return res.json({ success: true, data: assignments });\n});\n\n// ── POST /api/suppliers/:storeId/products/:productId/suppliers ────────────────\nrouter.post(\"/:storeId/products/:productId/suppliers\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:    z.string(),\n    supplierSku:   z.string().optional(),\n    supplierPrice: z.number().optional(),\n    supplierUrl:   z.string().optional(),\n    priority:      z.number().int().min(1).default(1),\n    notes:         z.string().optional(),\n  }).parse(req.body);\n\n  const existing = await prisma.supplierProduct.findFirst({\n    where: { supplierId: body.supplierId, productId },\n  });\n  if (existing) throw new AppError(\"This supplier is already assigned to this product\", 409);\n\n  const assignment = await prisma.supplierProduct.create({\n    data: { ...body, productId },\n    include: { supplier: { select: { id: true, name: true, type: true } } },\n  });\n\n  return res.status(201).json({ success: true, data: assignment });\n});\n\n// ── PATCH /api/suppliers/:storeId/supplier-products/:id ───────────────────────\nrouter.patch(\"/:storeId/supplier-products/:id\", async (req: AuthRequest, res: Response) => {\n  const { storeId, id } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    priority:      z.number().int().min(1).optional(),\n    isActive:      z.boolean().optional(),\n    supplierSku:   z.string().optional(),\n    supplierPrice: z.number().optional(),\n    notes:         z.string().optional(),\n    stockStatus:   z.string().optional(),\n  }).parse(req.body);\n\n  const updated = await prisma.supplierProduct.update({ where: { id }, data: body });\n  return res.json({ success: true, data: updated });\n});\n\n// ── DELETE /api/suppliers/:storeId/supplier-products/:id ─────────────────────\nrouter.delete(\"/:storeId/supplier-products/:id\", async (req: AuthRequest, res: Response) => {\n  const { storeId, id } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  await prisma.supplierProduct.delete({ where: { id } });\n  return res.json({ success: true });\n});\n\n\nexport default router;\n","backend/src/routes/analytics.routes.ts":"// src/routes/analytics.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\n\nconst router = Router();\n\n\n// ── GET /:storeId/report  — monthly breakdown for reports page ───────────────\nrouter.get(\"/:storeId/report\", authenticate, async (req: any, res) => {\n  const { storeId } = req.params;\n  const { period = \"30d\" } = req.query;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const days = period === \"1y\" ? 365 : period === \"90d\" ? 90 : period === \"30d\" ? 30 : 7;\n  const from = new Date(Date.now() - days * 86400000);\n\n  const orders = await prisma.order.findMany({\n    where: { storeId, createdAt: { gte: from } },\n    select: { total: true, createdAt: true, status: true, _count: false },\n    orderBy: { createdAt: \"asc\" },\n  });\n\n  // Build monthly buckets\n  const buckets: Record<string, { month: string; revenue: number; orders: number; customers: number }> = {};\n  for (const o of orders) {\n    const key = o.createdAt.toISOString().slice(0, 7); // YYYY-MM\n    const label = o.createdAt.toLocaleString(\"en\", { month: \"short\", year: \"2-digit\" });\n    if (!buckets[key]) buckets[key] = { month: label, revenue: 0, orders: 0, customers: 0 };\n    buckets[key].orders++;\n    if ([\"COMPLETED\", \"DELIVERED\", \"SHIPPED\"].includes(o.status)) {\n      buckets[key].revenue += o.total;\n    }\n  }\n\n  const monthly = Object.values(buckets);\n  const totRevenue  = monthly.reduce((s, m) => s + m.revenue, 0);\n  const totOrders   = monthly.reduce((s, m) => s + m.orders, 0);\n  const newCust     = await prisma.storeCustomer.count({ where: { storeId, createdAt: { gte: from } } });\n\n  return res.json({\n    success: true,\n    data: {\n      monthly,\n      totals: {\n        revenue:  totRevenue,\n        orders:   totOrders,\n        customers: newCust,\n        avgOrder: totOrders > 0 ? totRevenue / totOrders : 0,\n      },\n    },\n  });\n});\n\n\n// ── GET /:storeId/export — CSV export of orders/products/customers ────────────\nrouter.get(\"/:storeId/export\", authenticate, async (req: any, res) => {\n  const { storeId } = req.params;\n  const { type = \"orders\", period = \"30d\" } = req.query;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const days = period === \"1y\" ? 365 : period === \"90d\" ? 90 : period === \"30d\" ? 30 : 7;\n  const from = new Date(Date.now() - days * 86400000);\n\n  let csv = \"\";\n  if (type === \"orders\") {\n    const rows = await prisma.order.findMany({\n      where: { storeId, createdAt: { gte: from } },\n      orderBy: { createdAt: \"desc\" },\n      select: { orderNumber: true, createdAt: true, customerName: true, customerEmail: true, total: true, status: true },\n    });\n    csv  = \"Order Number,Date,Customer,Email,Total,Status\\n\";\n    csv += rows.map(r => `${r.orderNumber},${r.createdAt.toISOString().split(\"T\")[0]},${r.customerName},${r.customerEmail},${r.total.toFixed(2)},${r.status}`).join(\"\\n\");\n  } else if (type === \"products\") {\n    const rows = await prisma.product.findMany({\n      where: { storeId },\n      select: { name: true, sku: true, price: true, inventory: true, status: true, category: true },\n    });\n    csv  = \"Name,SKU,Price,Inventory,Status,Category\\n\";\n    csv += rows.map(r => `\"${r.name}\",${r.sku || \"\"},${r.price.toFixed(2)},${r.inventory},${r.status},${r.category || \"\"}`).join(\"\\n\");\n  } else if (type === \"customers\") {\n    const rows = await prisma.storeCustomer.findMany({\n      where: { storeId },\n      select: { name: true, email: true, totalOrders: true, totalSpent: true, createdAt: true },\n    });\n    csv  = \"Name,Email,Orders,Total Spent,Since\\n\";\n    csv += rows.map(r => `\"${r.name}\",${r.email},${r.totalOrders},${r.totalSpent.toFixed(2)},${r.createdAt.toISOString().split(\"T\")[0]}`).join(\"\\n\");\n  }\n\n  res.setHeader(\"Content-Type\", \"text/csv\");\n  res.setHeader(\"Content-Disposition\", `attachment; filename=\"dropos-${type}-${new Date().toISOString().split(\"T\")[0]}.csv\"`);\n  return res.send(csv);\n});\n\n\nrouter.get(\"/:storeId\", authenticate, async (req: any, res) => {\n  const { storeId } = req.params;\n  const { period = \"7d\" } = req.query;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const days = period === \"30d\" ? 30 : period === \"90d\" ? 90 : 7;\n  const from = new Date();\n  from.setDate(from.getDate() - days);\n\n  const [orders, revenue, topProducts, customerGrowth] = await Promise.all([\n    prisma.order.groupBy({\n      by: [\"status\"],\n      where: { storeId, createdAt: { gte: from } },\n      _count: { id: true },\n      _sum:   { total: true },\n    }),\n    await prisma.payment.aggregate({\n      where: { storeId, status: \"SUCCESS\", createdAt: { gte: from } },\n      _sum:  { amount: true, platformFee: true, storeEarnings: true },\n    }),\n    prisma.orderItem.groupBy({\n      by: [\"productId\", \"name\"],\n      where: { order: { storeId, createdAt: { gte: from } } },\n      _sum:  { total: true, quantity: true },\n      orderBy: { _sum: { total: \"desc\" } },\n      take: 5,\n    }),\n    await prisma.storeCustomer.count({\n      where: { storeId, createdAt: { gte: from } },\n    }),\n  ]);\n\n  const totalOrders  = orders.reduce((s, o) => s + o._count.id, 0);\n  const completedRev = revenue._sum.amount || 0;\n\n  return res.json({\n    success: true,\n    data: {\n      orders, totalOrders,\n      revenue: {\n        total:         completedRev,\n        platformFees:  revenue._sum.platformFee     || 0,\n        storeEarnings: revenue._sum.storeEarnings   || 0,\n      },\n      topProducts,\n      newCustomers: customerGrowth,\n      period,\n    },\n  });\n});\n\nexport default router;\n","backend/src/routes/abandonedCart.routes.ts":"// src/routes/abandonedCart.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  saveAbandonedCart,\n  recoverCart,\n  sendAbandonedCartReminders,\n  getAbandonedCarts,\n  deleteAbandonedCart,\n  resendRecoveryEmail,\n} from \"../controllers/abandonedCart.controller\";\n\nconst router = Router();\n\n// Public — called by storefront JS (no auth needed)\nrouter.post(\"/save\",                    saveAbandonedCart);\nrouter.get (\"/recover/:token\",          recoverCart);\n\n// Internal trigger (protect with secret header or cron auth in production)\nrouter.post(\"/send-reminders\",          sendAbandonedCartReminders);\n\n// Dashboard — authenticated\nrouter.get (\"/:storeId\",                authenticate, getAbandonedCarts);\nrouter.post(\"/:storeId/resend/:cartId\", authenticate, resendRecoveryEmail);\nrouter.delete(\"/:storeId/:cartId\",      authenticate, deleteAbandonedCart);\n\nexport default router;\n","backend/src/routes/admin.routes.ts":"// src/routes/admin.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getDashboardStats, getAllUsers, getUserDetail,\n  updateUser, updateUserSubscription, deleteUser,\n  getSettings, updateSettings,\n  getErrorLogs, resolveErrorLog,\n  getAuditLogs, getPlatformAnalytics,\n} from \"../controllers/admin.controller\";\n\nconst router = Router();\n\n// All admin routes require auth + SUPER_ADMIN role\nrouter.use(authenticate);\n\nrouter.get (\"/dashboard\",                 getDashboardStats);\nrouter.get (\"/analytics\",                 getPlatformAnalytics);\n\nrouter.get (\"/users\",                     getAllUsers);\nrouter.get (\"/users/:userId\",             getUserDetail);\nrouter.patch(\"/users/:userId\",            updateUser);\nrouter.patch(\"/users/:userId/subscription\", updateUserSubscription);\nrouter.delete(\"/users/:userId\",           deleteUser);\n\nrouter.get (\"/settings\",                  getSettings);\nrouter.patch(\"/settings\",                 updateSettings);\n\nrouter.get (\"/error-logs\",                getErrorLogs);\nrouter.patch(\"/error-logs/:logId/resolve\",resolveErrorLog);\nrouter.get (\"/audit-logs\",                getAuditLogs);\n\nexport default router;\n","backend/src/routes/affiliate.routes.ts":"// src/routes/affiliate.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\nimport { globalRateLimiter } from \"../middleware/rateLimiter\";\n\nconst router = Router();\n\n// ── Helper: verify caller owns this store ────────────────────────────────────\nasync function verifiedStoreId(req: AuthRequest) {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  return storeId;\n}\n\n// ── Helpers ─────────────────────────────────────────────────────────────────\nfunction randomCode(len = 8) {\n  return Math.random().toString(36).substring(2, 2 + len).toUpperCase();\n}\n\n// ── GET /api/affiliates/:storeId — list all affiliates ──────────────────────\nrouter.get(\"/:storeId\", authenticate, async (req: Request, res: Response) => {\n  const affiliates = await prisma.affiliate.findMany({\n    where:   { storeId: req.params.storeId },\n    include: { _count: { select: { referrals: true } } },\n    orderBy: { createdAt: \"desc\" },\n  });\n  res.json({ success: true, data: affiliates });\n});\n\n// ── POST /api/affiliates/:storeId — create affiliate ───────────────────────\nrouter.post(\"/:storeId\", authenticate, async (req: Request, res: Response) => {\n  const { storeId } = req.params;\n  const { name, email, commissionPct, commissionFlat, payoutMethod, notes } = req.body;\n  if (!name || !email) throw new AppError(\"name and email required\", 400);\n\n  // Generate unique code\n  let code = req.body.code?.toUpperCase() || randomCode();\n  const existing = await prisma.affiliate.findFirst({ where: { storeId, code } });\n  if (existing) code = randomCode(10);\n\n  const affiliate = await prisma.affiliate.create({\n    data: {\n      storeId, name, email, code,\n      commissionPct:  Number(commissionPct)  || 10,\n      commissionFlat: commissionFlat ? Number(commissionFlat) : null,\n      payoutMethod:   payoutMethod || null,\n      notes:          notes || null,\n      status:         \"ACTIVE\",\n    },\n  });\n  res.status(201).json({ success: true, data: affiliate });\n});\n\n// ── PATCH /api/affiliates/:storeId/:id — update ──────────────────────────\nrouter.patch(\"/:storeId/:id\", authenticate, async (req: Request, res: Response) => {\n  const { storeId, id } = req.params;\n  const aff = await prisma.affiliate.findFirst({ where: { id, storeId } });\n  if (!aff) throw new AppError(\"Affiliate not found\", 404);\n\n  const updated = await prisma.affiliate.update({ where: { id }, data: req.body });\n  res.json({ success: true, data: updated });\n});\n\n// ── PATCH /api/affiliates/:storeId/:id/status — change status ──────────────\nrouter.patch(\"/:storeId/:id/status\", authenticate, async (req: Request, res: Response) => {\n  const { storeId, id } = req.params;\n  const { status } = req.body;\n  await prisma.affiliate.update({ where: { id }, data: { status } });\n  res.json({ success: true });\n});\n\n// ── DELETE /api/affiliates/:storeId/:id ───────────────────────────────────\nrouter.delete(\"/:storeId/:id\", authenticate, async (req: Request, res: Response) => {\n  await prisma.affiliate.deleteMany({ where: { id: req.params.id, storeId: req.params.storeId } });\n  res.json({ success: true });\n});\n\n// ── GET /api/affiliates/:storeId/:id/stats ─────────────────────────────────\nrouter.get(\"/:storeId/:id/stats\", authenticate, async (req: Request, res: Response) => {\n  const { storeId, id } = req.params;\n  const aff = await prisma.affiliate.findFirst({ where: { id, storeId } });\n  if (!aff) throw new AppError(\"Not found\", 404);\n\n  const [conversions, clicks, payouts] = await Promise.all([\n    await prisma.referralConversion.findMany({ where: { affiliateId: id }, orderBy: { createdAt: \"desc\" }, take: 20 }),\n    await prisma.referralClick.count({ where: { affiliateId: id } }),\n    await prisma.affiliatePayout.findMany({ where: { affiliateId: id }, orderBy: { createdAt: \"desc\" }, take: 10 }),\n  ]);\n\n  const pendingBalance = conversions\n    .filter(c => c.status === \"PENDING\" || c.status === \"APPROVED\")\n    .reduce((s, c) => s + c.commission, 0);\n\n  const conversionRate = clicks > 0\n    ? ((conversions.length / clicks) * 100).toFixed(1)\n    : \"0\";\n\n  res.json({ success: true, data: { conversions, clicks, payouts, pendingBalance, conversionRate } });\n});\n\n// ── POST /api/affiliates/:storeId/:id/payout ──────────────────────────────\nrouter.post(\"/:storeId/:id/payout\", authenticate, async (req: Request, res: Response) => {\n  const { storeId, id } = req.params;\n  const { amount, method, reference, note } = req.body;\n  if (!amount || amount <= 0) throw new AppError(\"Amount required\", 400);\n\n  const payout = await prisma.affiliatePayout.create({\n    data: { affiliateId: id, storeId, amount: Number(amount), method: method || \"manual\", reference, note, status: \"SENT\" },\n  });\n\n  await prisma.affiliate.update({\n    where: { id },\n    data:  { totalPaid: { increment: Number(amount) } },\n  });\n\n  res.json({ success: true, data: payout });\n});\n\n// ── POST /api/affiliates/track-click — public (from storefront) ─────────────\nrouter.post(\"/track-click\", globalRateLimiter, async (req: Request, res: Response) => {\n  const { code, storeId, page } = req.body;\n  if (!code || !storeId) return res.json({ success: true });\n\n  const aff = await prisma.affiliate.findFirst({ where: { storeId, code, status: \"ACTIVE\" } });\n  if (!aff) return res.json({ success: true });\n\n  await Promise.all([\n    await prisma.referralClick.create({\n      data: { affiliateId: aff.id, storeId, ip: req.ip, userAgent: req.headers[\"user-agent\"], page },\n    }),\n    await prisma.affiliate.update({ where: { id: aff.id }, data: { totalClicks: { increment: 1 } } }),\n  ]);\n\n  res.json({ success: true, data: { affiliateId: aff.id, name: aff.name } });\n});\n\n// ── POST /api/affiliates/record-conversion — called after order ──────────────\nrouter.post(\"/record-conversion\", globalRateLimiter, async (req: Request, res: Response) => {\n  const { affiliateId, orderId, storeId, orderValue } = req.body;\n  if (!affiliateId || !orderId) return res.json({ success: true });\n\n  const aff = await prisma.affiliate.findFirst({ where: { id: affiliateId, storeId, status: \"ACTIVE\" } });\n  if (!aff) return res.json({ success: true });\n\n  const commission = aff.commissionFlat\n    ? aff.commissionFlat\n    : (Number(orderValue) * aff.commissionPct) / 100;\n\n  await Promise.all([\n    await prisma.referralConversion.create({\n      data: { affiliateId, orderId, storeId, orderValue: Number(orderValue), commission, status: \"PENDING\" },\n    }),\n    await prisma.affiliate.update({\n      where: { id: affiliateId },\n      data:  { totalEarned: { increment: commission }, totalOrders: { increment: 1 } },\n    }),\n  ]);\n\n  res.json({ success: true, data: { commission } });\n});\n\nexport default router;\n","backend/src/routes/ai.routes.ts":"// src/routes/ai.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport rateLimit from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport { AppError } from \"../utils/AppError\";\n\n// AI endpoints get tighter rate limiting — they're expensive\nconst aiRateLimiter = rateLimit({\n  windowMs: 60 * 1000,  // 1 minute\n  max: 1000,          // 10 AI calls per minute per IP\n  standardHeaders: true,\n  legacyHeaders:   false,\n  message: { success: false, message: \"Too many AI requests, please wait a moment.\" },\n});\n\n// Sanitize user input before interpolating into prompts (prevent injection)\nfunction sanitizeForPrompt(input: string, maxLen = 200): string {\n  return String(input)\n    .replace(/[<>{}|\\\\]/g, \"\")  // strip chars that can alter prompt structure\n    .slice(0, maxLen)\n    .trim();\n}\n\nconst router = Router();\n\n// POST /api/ai/product-description\n// Generates SEO-optimised product description from keywords/image URL\nrouter.post(\"/product-description\", authenticate, aiRateLimiter, async (req: Request, res: Response) => {\n  const { productName, keywords, tone, imageUrl, category, targetAudience } = req.body;\n  if (!productName) throw new AppError(\"productName required\", 400);\n\n  // Sanitize all user inputs before injecting into prompts\n  const safeProductName    = sanitizeForPrompt(productName, 150);\n  const safeCategory       = category       ? sanitizeForPrompt(category, 80)       : \"\";\n  const safeTargetAudience = targetAudience ? sanitizeForPrompt(targetAudience, 100) : \"\";\n  const safeKeywords       = Array.isArray(keywords)\n    ? keywords.slice(0, 10).map((k: string) => sanitizeForPrompt(k, 40)).join(\", \")\n    : \"\";\n  // imageUrl — only allow https URLs, no data: or file: URIs\n  let safeImageUrl = \"\";\n  if (imageUrl) {\n    try {\n      const u = new URL(imageUrl);\n      if (u.protocol === \"https:\") safeImageUrl = u.href.slice(0, 500);\n    } catch {}\n  }\n\n  const toneMap: Record<string, string> = {\n    professional: \"professional, polished, and authoritative\",\n    casual:       \"friendly, conversational, and approachable\",\n    luxury:       \"elegant, premium, and aspirational\",\n    energetic:    \"bold, exciting, and action-oriented\",\n    minimalist:   \"clean, simple, and concise\",\n  };\n\n  const toneDesc = toneMap[tone] || toneMap.professional;\n\n  const systemPrompt = `You are an expert ecommerce copywriter specializing in high-converting product descriptions. \nYou write in a ${toneDesc} tone.\nOutput ONLY a JSON object with no markdown, no preamble, no backticks — just raw JSON.`;\n\n  const userPrompt = `Write a compelling product description for:\nProduct: ${safeProductName}\n${safeCategory ? `Category: ${safeCategory}` : \"\"}\n${safeKeywords ? `Keywords: ${safeKeywords}` : \"\"}\n${safeTargetAudience ? `Target audience: ${safeTargetAudience}` : \"\"}\n${safeImageUrl ? `The product image URL is: ${safeImageUrl} (use visual cues if the product is identifiable)` : \"\"}\n\nReturn ONLY this JSON:\n{\n  \"headline\": \"Catchy 6-10 word headline\",\n  \"shortDescription\": \"1-2 sentence hook (under 120 chars)\",\n  \"fullDescription\": \"Rich 3-4 paragraph description with benefits and features\",\n  \"bulletPoints\": [\"benefit 1\", \"benefit 2\", \"benefit 3\", \"benefit 4\", \"benefit 5\"],\n  \"seoTitle\": \"SEO optimised page title (under 60 chars)\",\n  \"seoDescription\": \"Meta description (under 155 chars)\",\n  \"tags\": [\"tag1\", \"tag2\", \"tag3\", \"tag4\", \"tag5\"]\n}`;\n\n  // Call Anthropic API — use env var key\n  const apiKey = process.env.ANTHROPIC_API_KEY;\n  if (!apiKey) throw new AppError(\"AI service not configured\", 503);\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 1200,\n      system: systemPrompt,\n      messages: [{ role: \"user\", content: userPrompt }],\n    }),\n  });\n\n  if (!response.ok) {\n    const err = await response.text();\n    throw new AppError(\"AI generation failed: \" + err, 500);\n  }\n\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"{}\";\n\n  let parsed: any;\n  try {\n    parsed = JSON.parse(text.replace(/```json|```/g, \"\").trim());\n  } catch {\n    throw new AppError(\"AI returned invalid response\", 500);\n  }\n\n  res.json({ success: true, data: parsed });\n});\n\n// POST /api/ai/product-tags\nrouter.post(\"/product-tags\", authenticate, aiRateLimiter, async (req: Request, res: Response) => {\n  const { productName, description, category } = req.body;\n  if (!productName) throw new AppError(\"productName required\", 400);\n\n  const apiKey = process.env.ANTHROPIC_API_KEY;\n  if (!apiKey) throw new AppError(\"AI service not configured\", 503);\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 300,\n      messages: [{\n        role: \"user\",\n        content: `Generate 8-12 ecommerce search tags for: \"${productName}\". ${description ? \"Description: \" + description : \"\"} ${category ? \"Category: \" + category : \"\"}. Return ONLY a JSON array of lowercase strings. No explanation.`,\n      }],\n    }),\n  });\n\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"[]\";\n  let tags: string[] = [];\n  try { tags = JSON.parse(text.replace(/```json|```/g, \"\").trim()); } catch {}\n\n  res.json({ success: true, data: { tags } });\n});\n\n// POST /api/ai/store-name\nrouter.post(\"/store-name\", authenticate, aiRateLimiter, async (req: Request, res: Response) => {\n  const { niche, keywords, style } = req.body;\n  const apiKey = process.env.ANTHROPIC_API_KEY;\n  if (!apiKey) throw new AppError(\"AI service not configured\", 503);\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 400,\n      messages: [{\n        role: \"user\",\n        content: `Generate 6 creative store name ideas for a ${niche || \"dropshipping\"} store. ${keywords ? \"Keywords: \" + keywords : \"\"} ${style ? \"Style: \" + style : \"\"}. Return ONLY a JSON array of objects: [{\"name\":\"StoreName\",\"tagline\":\"Short tagline\",\"domain\":\"storename.com\"}]. No explanation.`,\n      }],\n    }),\n  });\n\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"[]\";\n  let names: any[] = [];\n  try { names = JSON.parse(text.replace(/```json|```/g, \"\").trim()); } catch {}\n\n  res.json({ success: true, data: { names } });\n});\n\nexport default router;\n","backend/src/routes/apiKey.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { createApiKey, getApiKeys, revokeApiKey, updateApiKey, listPermissions } from \"../controllers/apiKey.controller\";\nconst r = Router();\nr.get(\"/permissions\", authenticate, listPermissions);\nr.post(\"/:storeId\", authenticate, createApiKey);\nr.get(\"/:storeId\", authenticate, getApiKeys);\nr.delete(\"/:storeId/:keyId\", authenticate, revokeApiKey);\nr.patch(\"/:storeId/:keyId\", authenticate, updateApiKey);\nexport default r;\n","backend/src/routes/auth.refresh.routes.ts":"// ============================================================\n// Auth Routes — Session-Persistent\n// Path: backend/src/routes/auth.routes.ts (additions)\n// Add these endpoints to your existing auth routes\n// ============================================================\nimport { Router, Request, Response } from \"express\";\nimport {\n  generateTokens, saveRefreshToken,\n  setRefreshCookie, clearRefreshCookie,\n  rotateRefreshToken, revokeAllSessions,\n} from \"../services/session.service\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\n\n// ── POST /api/auth/refresh ────────────────────────────────────\n// Called automatically by frontend every 13 minutes\n// Uses httpOnly cookie — user never sees this\nrouter.post(\"/refresh\", async (req: Request, res: Response) => {\n  try {\n    const oldToken = req.cookies?.dropos_refresh;\n    if (!oldToken) {\n      return res.status(401).json({\n        success: false,\n        code:    \"NO_REFRESH_TOKEN\",\n        message: \"No refresh token\",\n      });\n    }\n\n    const result = await rotateRefreshToken(\n      oldToken,\n      req.ip,\n      req.headers[\"user-agent\"],\n    );\n\n    if (!result) {\n      clearRefreshCookie(res);\n      return res.status(401).json({\n        success: false,\n        code:    \"INVALID_REFRESH_TOKEN\",\n        message: \"Session expired — please log in again\",\n      });\n    }\n\n    // Set new refresh token as httpOnly cookie\n    setRefreshCookie(res, result.refreshToken);\n\n    res.json({\n      success: true,\n      data: {\n        accessToken: result.accessToken,\n        user:        result.user,\n      },\n    });\n  } catch (err) {\n    console.error(\"[Auth/Refresh]\", err);\n    res.status(500).json({ success: false, message: \"Session refresh failed\" });\n  }\n});\n\n// ── POST /api/auth/logout ─────────────────────────────────────\nrouter.post(\"/logout\", async (req: Request, res: Response) => {\n  try {\n    const refreshToken = req.cookies?.dropos_refresh;\n    if (refreshToken) {\n      // Revoke the specific token\n      await prisma.refreshToken.updateMany({\n        where: { token: refreshToken },\n        data:  { revokedAt: new Date() },\n      }).catch(() => {});\n    }\n    clearRefreshCookie(res);\n    res.json({ success: true, message: \"Logged out\" });\n  } catch {\n    res.json({ success: true }); // Always succeed logout\n  }\n});\n\n// ── POST /api/auth/logout-all ─────────────────────────────────\n// Logout from all devices\nrouter.post(\"/logout-all\", async (req: Request, res: Response) => {\n  try {\n    const user = (req as any).user;\n    if (user?.id) await revokeAllSessions(user.id);\n    clearRefreshCookie(res);\n    res.json({ success: true, message: \"Logged out from all devices\" });\n  } catch {\n    res.json({ success: true });\n  }\n});\n\n// ── GET /api/auth/me ──────────────────────────────────────────\n// Get current user — used on app load to restore session\nrouter.get(\"/me\", async (req: Request, res: Response) => {\n  try {\n    const refreshToken = req.cookies?.dropos_refresh;\n    if (!refreshToken) {\n      return res.status(401).json({ success: false, code: \"NO_SESSION\" });\n    }\n\n    // Try to refresh if we have a cookie\n    const result = await rotateRefreshToken(refreshToken, req.ip, req.headers[\"user-agent\"]);\n    if (!result) {\n      clearRefreshCookie(res);\n      return res.status(401).json({ success: false, code: \"SESSION_EXPIRED\" });\n    }\n\n    setRefreshCookie(res, result.refreshToken);\n    res.json({\n      success: true,\n      data: { accessToken: result.accessToken, user: result.user },\n    });\n  } catch (err) {\n    res.status(500).json({ success: false, message: \"Could not restore session\" });\n  }\n});\n\nexport default router;\n","backend/src/routes/auth.routes.ts":"// src/routes/auth.routes.ts\nimport { Router } from \"express\";\nimport { authRateLimiter } from \"../middleware/rateLimiter\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  register, login, logout, refreshToken,\n  verifyEmail, forgotPassword, resetPassword,\n  getMe, updateProfile, changePassword,\n} from \"../controllers/auth.controller\";\n\nconst router = Router();\n\nrouter.post(\"/register\",               authRateLimiter, register);\nrouter.post(\"/login\",                  authRateLimiter, login);\nrouter.post(\"/logout\",                 authenticate, logout);\nrouter.post(\"/refresh\",                authRateLimiter, refreshToken);\nrouter.get (\"/verify-email/:token\",    verifyEmail);\nrouter.post(\"/forgot-password\",        authRateLimiter, forgotPassword);\nrouter.post(\"/reset-password\",         authRateLimiter, resetPassword);\nrouter.get (\"/me\",                     authenticate, getMe);\nrouter.patch(\"/me\",                    authenticate, updateProfile);\nrouter.patch(\"/me/password\",           authenticate, changePassword);\n\nexport default router;\n","backend/src/routes/bundle.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/bundles/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const bundles = await prisma.bundle.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: bundles });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/bundles/:storeId\nrouter.post(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const { name, productIds, discountPercent } = req.body;\n    if (!name || !productIds?.length) return res.status(400).json({ success: false, message: \"Name and products required\" });\n\n    // Get products to calculate price\n    const products = await prisma.product.findMany({ where: { id: { in: productIds } } });\n    const originalPrice = products.reduce((a: number, p: any) => a + (p.price || 0), 0);\n    const bundlePrice   = originalPrice * (1 - (discountPercent || 10) / 100);\n\n    const bundle = await prisma.bundle.create({\n      data: { storeId: req.params.storeId, name, productIds, discountPercent: discountPercent || 10, originalPrice, bundlePrice },\n    });\n    res.status(201).json({ success: true, data: bundle });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// DELETE /api/bundles/:storeId/:bundleId\nrouter.delete(\"/:storeId/:bundleId\", async (req: any, res: Response) => {\n  try {\n    await prisma.bundle.delete({ where: { id: req.params.bundleId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/contact.routes.ts":"import { Router, Request, Response } from \"express\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\n\n// POST /api/contact\nrouter.post(\"/\", async (req: Request, res: Response) => {\n  try {\n    const { name, email, subject, message } = req.body;\n    if (!name || !email || !message) {\n      return res.status(400).json({ success: false, message: \"Name, email and message are required\" });\n    }\n    await prisma.contactMessage.create({ data: { name, email, subject: subject || \"general\", message } });\n    // TODO: send email notification to hello@droposhq.com via Resend\n    res.json({ success: true, message: \"Message received. We will reply within 24 hours.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/coupon.routes.ts":"// src/routes/coupon.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { z } from \"zod\";\n\nconst router = Router();\n\n// ── Helper: verify store ownership and return storeId ──────────────────────\nasync function verifiedStoreId(req: AuthRequest) {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  return storeId;\n}\n\n// POST /api/coupons/validate  (public — no auth required, minimal data exposure)\nrouter.post(\"/validate\", async (req: Request, res: Response) => {\n  const schema = z.object({\n    code:       z.string().min(1).max(50),\n    storeId:    z.string().uuid(),\n    orderTotal: z.number().nonnegative().optional(),\n  });\n  const { code, storeId, orderTotal } = schema.parse(req.body);\n\n  const coupon = await prisma.coupon.findFirst({\n    where: {\n      storeId,\n      code:     code.toUpperCase().trim(),\n      isActive: true,\n    },\n    select: {\n      id: true, code: true, type: true, value: true,\n      minOrderValue: true, maxUses: true, usedCount: true, expiresAt: true,\n    },\n  });\n\n  if (!coupon)                                           throw new AppError(\"Invalid coupon code\", 400);\n  if (coupon.expiresAt && new Date() > coupon.expiresAt) throw new AppError(\"Coupon has expired\", 400);\n  if (coupon.maxUses && coupon.usedCount >= coupon.maxUses) throw new AppError(\"Coupon usage limit reached\", 400);\n  if (coupon.minOrderValue && Number(orderTotal ?? 0) < coupon.minOrderValue)\n    throw new AppError(`Minimum order of $${coupon.minOrderValue} required`, 400);\n\n  const order = Number(orderTotal ?? 0);\n  const discount = coupon.type === \"PERCENTAGE\"\n    ? (order * coupon.value) / 100\n    : coupon.value;\n\n  // Only return safe fields — not internal DB ids etc\n  res.json({\n    success: true,\n    data: {\n      coupon:   { code: coupon.code, type: coupon.type, value: coupon.value },\n      discount: Math.min(discount, order),\n    },\n  });\n});\n\n// GET /api/coupons/:storeId — list (owner only)\nrouter.get(\"/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const coupons = await prisma.coupon.findMany({\n    where:   { storeId },\n    orderBy: { createdAt: \"desc\" },\n  });\n  res.json({ success: true, data: coupons });\n});\n\n// POST /api/coupons/:storeId — create (owner only)\nrouter.post(\"/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n\n  const schema = z.object({\n    code:          z.string().min(1).max(50),\n    type:          z.enum([\"PERCENTAGE\", \"FIXED\"]),\n    value:         z.number().positive(),\n    minOrderValue: z.number().nonnegative().optional(),\n    maxUses:       z.number().int().positive().optional(),\n    expiresAt:     z.string().datetime().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const existing = await prisma.coupon.findFirst({\n    where: { storeId, code: data.code.toUpperCase() },\n  });\n  if (existing) throw new AppError(\"Coupon code already exists\", 400);\n\n  const coupon = await prisma.coupon.create({\n    data: {\n      storeId,\n      code:          data.code.toUpperCase().trim(),\n      type:          data.type,\n      value:         data.value,\n      minOrderValue: data.minOrderValue ?? 0,\n      maxUses:       data.maxUses ?? null,\n      expiresAt:     data.expiresAt ? new Date(data.expiresAt) : null,\n      isActive:      true,\n      usedCount:     0,\n    },\n  });\n  res.status(201).json({ success: true, data: coupon });\n});\n\n// PATCH /api/coupons/:storeId/:id — update (owner only)\nrouter.patch(\"/:storeId/:id\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n\n  const schema = z.object({\n    isActive:      z.boolean().optional(),\n    maxUses:       z.number().int().positive().nullable().optional(),\n    expiresAt:     z.string().datetime().nullable().optional(),\n    minOrderValue: z.number().nonnegative().optional(),\n  }).strict();\n  const data = schema.parse(req.body);\n\n  const coupon = await prisma.coupon.findFirst({\n    where: { id: req.params.id, storeId },\n  });\n  if (!coupon) throw new AppError(\"Coupon not found\", 404);\n\n  const updated = await prisma.coupon.update({\n    where: { id: req.params.id },\n    data:  {\n      ...data,\n      expiresAt: data.expiresAt ? new Date(data.expiresAt) : data.expiresAt,\n    },\n  });\n  res.json({ success: true, data: updated });\n});\n\n// DELETE /api/coupons/:storeId/:id — delete (owner only)\nrouter.delete(\"/:storeId/:id\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n\n  const coupon = await prisma.coupon.findFirst({\n    where: { id: req.params.id, storeId },\n  });\n  if (!coupon) throw new AppError(\"Coupon not found\", 404);\n\n  await prisma.coupon.delete({ where: { id: req.params.id } });\n  res.json({ success: true });\n});\n\nexport default router;\n","backend/src/routes/currency.routes.ts":"// src/routes/currency.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { currencyService, CURRENCY_META, COUNTRY_TO_CURRENCY } from \"../services/currency.service\";\nimport axios from \"axios\";\n\nconst router = Router();\n\n// ── GET /api/currency/rates — all rates relative to USD ──────────────────────\nrouter.get(\"/rates\", async (_req: Request, res: Response) => {\n  try {\n    const rates = await currencyService.getRates();\n    return res.json({ success: true, data: { rates, base: \"USD\", updatedAt: new Date().toISOString() } });\n  } catch {\n    return res.status(500).json({ success: false, message: \"Failed to fetch rates\" });\n  }\n});\n\n// ── GET /api/currency/available — list all supported currencies ───────────────\nrouter.get(\"/available\", (_req: Request, res: Response) => {\n  const currencies = Object.entries(CURRENCY_META).map(([code, meta]) => ({\n    code, ...meta,\n  }));\n  return res.json({ success: true, data: currencies });\n});\n\n// ── GET /api/currency/detect — detect currency from visitor IP ───────────────\nrouter.get(\"/detect\", async (req: Request, res: Response) => {\n  try {\n    // Extract real IP (works behind proxies / Vercel / Railway)\n    const ip =\n      (req.headers[\"x-forwarded-for\"] as string)?.split(\",\")[0]?.trim() ||\n      (req.headers[\"x-real-ip\"] as string) ||\n      req.socket.remoteAddress ||\n      \"\";\n\n    // Skip for localhost / private IPs\n    const isLocal = !ip || ip === \"::1\" || ip === \"127.0.0.1\" || ip.startsWith(\"192.168\") || ip.startsWith(\"10.\");\n\n    if (isLocal) {\n      return res.json({\n        success:  true,\n        data: { currency: \"USD\", country: \"US\", countryName: \"United States\", ip, source: \"default\" },\n      });\n    }\n\n    // Free tier geo IP — no API key needed\n    const geoRes = await axios.get(`http://ip-api.com/json/${ip}?fields=status,country,countryCode`, {\n      timeout: 3000,\n    });\n\n    const { status, country, countryCode } = geoRes.data;\n    if (status !== \"success\") throw new Error(\"Geo lookup failed\");\n\n    const currency = COUNTRY_TO_CURRENCY[countryCode] ?? \"USD\";\n    return res.json({\n      success: true,\n      data: { currency, country: countryCode, countryName: country, ip, source: \"geo\" },\n    });\n  } catch (err: any) {\n    // Graceful fallback — never hard-fail\n    return res.json({\n      success: true,\n      data: { currency: \"USD\", country: \"US\", countryName: \"United States\", ip: \"\", source: \"fallback\" },\n    });\n  }\n});\n\n// ── POST /api/currency/convert — convert a price ─────────────────────────────\nrouter.post(\"/convert\", async (req: Request, res: Response) => {\n  try {\n    const { amount, from, to } = req.body;\n    if (!amount || !from || !to) {\n      return res.status(400).json({ success: false, message: \"amount, from, and to are required\" });\n    }\n    const converted = await currencyService.convert(Number(amount), String(from), String(to));\n    return res.json({ success: true, data: { amount, from, to, converted, rate: converted / amount } });\n  } catch {\n    return res.status(500).json({ success: false, message: \"Conversion failed\" });\n  }\n});\n\n// ── GET /api/currency/rates/:code — rates relative to a specific base ─────────\nrouter.get(\"/rates/:base\", async (req: Request, res: Response) => {\n  try {\n    const { base } = req.params;\n    const usdRates = await currencyService.getRates();\n    const baseRate = usdRates[base.toUpperCase()] ?? 1;\n\n    // Rebase all rates to the requested currency\n    const rebased: Record<string, number> = {};\n    for (const [code, usdRate] of Object.entries(usdRates)) {\n      rebased[code] = usdRate / baseRate;\n    }\n\n    return res.json({ success: true, data: { rates: rebased, base: base.toUpperCase() } });\n  } catch {\n    return res.status(500).json({ success: false, message: \"Failed to rebase rates\" });\n  }\n});\n\nexport default router;\n","backend/src/routes/customer.routes.ts":"// src/routes/customer.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { paginate } from \"../utils/helpers\";\n\nconst router = Router();\n\nrouter.get(\"/:storeId\", authenticate, async (req: any, res) => {\n  const { storeId } = req.params;\n  const { page = 1, limit = 20, search } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = { storeId };\n  if (search) where.OR = [\n    { name:  { contains: search as string, mode: \"insensitive\" } },\n    { email: { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  const [customers, total] = await Promise.all([\n    await prisma.storeCustomer.findMany({\n      where, take, skip,\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.storeCustomer.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: customers,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n});\n\nrouter.get(\"/:storeId/:customerId\", authenticate, async (req: any, res) => {\n  const { storeId, customerId } = req.params;\n  const customer = await prisma.storeCustomer.findFirst({\n    where: { id: customerId, storeId },\n    include: {\n      orders: {\n        orderBy: { createdAt: \"desc\" },\n        take: 10,\n        include: { payment: { select: { status: true, gateway: true } } },\n      },\n    },\n  });\n  if (!customer) return res.status(404).json({ success: false, message: \"Customer not found\" });\n  return res.json({ success: true, data: customer });\n});\n\nexport default router;\n","backend/src/routes/customerAccount.routes.ts":"import { Router } from \"express\";\nimport { authenticateCustomer } from \"../middleware/customerAuth\";\nimport {\n  registerCustomer, loginCustomer, getCustomerProfile, updateCustomerProfile,\n  toggleWishlist, getWishlist, customerForgotPassword,\n} from \"../controllers/customerAccount.controller\";\n\nconst r = Router();\n// Public\nr.post(\"/register\", registerCustomer);\nr.post(\"/login\", loginCustomer);\nr.post(\"/forgot-password\", customerForgotPassword);\n// Authenticated customer\nr.get(\"/profile\", authenticateCustomer, getCustomerProfile);\nr.patch(\"/profile\", authenticateCustomer, updateCustomerProfile);\nr.post(\"/wishlist/toggle\", authenticateCustomer, toggleWishlist);\nr.get(\"/wishlist\", authenticateCustomer, getWishlist);\nexport default r;\n","backend/src/routes/discount.routes.ts":"// src/routes/discount.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { DiscountService } from \"../services/discount.service\";\nimport { AppError } from \"../utils/AppError\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\nimport { globalRateLimiter } from \"../middleware/rateLimiter\";\n\nconst router = Router();\n\n// ── Helper: verify caller owns this store ────────────────────────────────────\nasync function verifiedStoreId(req: AuthRequest) {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  return storeId;\n}\n\n// GET /api/discounts/:storeId — list all discounts (owner only)\nrouter.get(\"/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const discounts = await prisma.discount.findMany({\n    where:   { storeId },\n    include: { _count: { select: { usages: true } } },\n    orderBy: [{ status: \"asc\" }, { priority: \"desc\" }, { createdAt: \"desc\" }],\n  });\n  res.json({ success: true, data: discounts });\n});\n\n// POST /api/discounts/:storeId — create discount (owner only)\nrouter.post(\"/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const {\n    name, description, type, valueType, value, maxDiscount, freeShipping,\n    minOrderValue, minQuantity, productIds, firstOrderOnly,\n    bogoRequiredQty, bogoGetQty, bogoPctOff,\n    tiers, flashSaleStartsAt, flashSaleEndsAt,\n    maxUses, maxUsesPerCustomer,\n    startsAt, expiresAt, isAutomatic, priority, stackable,\n  } = req.body;\n\n  if (!name || !type || !valueType) throw new AppError(\"name, type, valueType required\", 400);\n\n  const discount = await prisma.discount.create({\n    data: {\n      storeId, name, description, type, valueType,\n      value:         Number(value) || 0,\n      maxDiscount:   maxDiscount   ? Number(maxDiscount)   : null,\n      minOrderValue: minOrderValue ? Number(minOrderValue) : null,\n      minQuantity:   minQuantity   ? Number(minQuantity)   : null,\n      productIds:    productIds    || [],\n      freeShipping:  Boolean(freeShipping),\n      firstOrderOnly:Boolean(firstOrderOnly),\n      isAutomatic:   Boolean(isAutomatic),\n      stackable:     Boolean(stackable),\n      priority:      Number(priority) || 0,\n      bogoRequiredQty:  bogoRequiredQty  ? Number(bogoRequiredQty)  : null,\n      bogoGetQty:       bogoGetQty       ? Number(bogoGetQty)       : null,\n      bogoPctOff:       bogoPctOff       ? Number(bogoPctOff)       : null,\n      tiers:            tiers            || null,\n      flashSaleStartsAt: flashSaleStartsAt ? new Date(flashSaleStartsAt) : null,\n      flashSaleEndsAt:   flashSaleEndsAt   ? new Date(flashSaleEndsAt)   : null,\n      maxUses:            maxUses            ? Number(maxUses)            : null,\n      maxUsesPerCustomer: maxUsesPerCustomer ? Number(maxUsesPerCustomer) : null,\n      startsAt:  startsAt  ? new Date(startsAt)  : null,\n      expiresAt: expiresAt ? new Date(expiresAt) : null,\n    },\n  });\n\n  res.status(201).json({ success: true, data: discount });\n});\n\n// PATCH /api/discounts/:storeId/:id — update discount (owner only)\nrouter.patch(\"/:storeId/:id\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const { id }  = req.params;\n\n  const discount = await prisma.discount.findFirst({ where: { id, storeId } });\n  if (!discount) throw new AppError(\"Discount not found\", 404);\n\n  // Whitelist updatable fields — prevent mass assignment\n  const {\n    name, description, value, maxDiscount, freeShipping, minOrderValue,\n    minQuantity, productIds, maxUses, maxUsesPerCustomer,\n    startsAt, expiresAt, priority, stackable, status,\n  } = req.body;\n\n  const updated = await prisma.discount.update({\n    where: { id },\n    data: {\n      ...(name          !== undefined && { name }),\n      ...(description   !== undefined && { description }),\n      ...(value         !== undefined && { value: Number(value) }),\n      ...(maxDiscount   !== undefined && { maxDiscount: maxDiscount ? Number(maxDiscount) : null }),\n      ...(freeShipping  !== undefined && { freeShipping: Boolean(freeShipping) }),\n      ...(minOrderValue !== undefined && { minOrderValue: minOrderValue ? Number(minOrderValue) : null }),\n      ...(minQuantity   !== undefined && { minQuantity: minQuantity ? Number(minQuantity) : null }),\n      ...(productIds    !== undefined && { productIds }),\n      ...(maxUses       !== undefined && { maxUses: maxUses ? Number(maxUses) : null }),\n      ...(maxUsesPerCustomer !== undefined && { maxUsesPerCustomer: maxUsesPerCustomer ? Number(maxUsesPerCustomer) : null }),\n      ...(startsAt      !== undefined && { startsAt: startsAt ? new Date(startsAt) : null }),\n      ...(expiresAt     !== undefined && { expiresAt: expiresAt ? new Date(expiresAt) : null }),\n      ...(priority      !== undefined && { priority: Number(priority) }),\n      ...(stackable     !== undefined && { stackable: Boolean(stackable) }),\n      ...(status        !== undefined && { status }),\n    },\n  });\n  res.json({ success: true, data: updated });\n});\n\n// PATCH /api/discounts/:storeId/:id/toggle — toggle status (owner only)\nrouter.patch(\"/:storeId/:id/toggle\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const { id }  = req.params;\n\n  const d = await prisma.discount.findFirst({ where: { id, storeId } });\n  if (!d) throw new AppError(\"Discount not found\", 404);\n\n  const updated = await prisma.discount.update({\n    where: { id },\n    data:  { status: d.status === \"ACTIVE\" ? \"PAUSED\" : \"ACTIVE\" },\n  });\n  res.json({ success: true, data: updated });\n});\n\n// DELETE /api/discounts/:storeId/:id — delete discount (owner only)\nrouter.delete(\"/:storeId/:id\", authenticate, async (req: AuthRequest, res: Response) => {\n  const storeId = await verifiedStoreId(req);\n  const { id }  = req.params;\n\n  const d = await prisma.discount.findFirst({ where: { id, storeId } });\n  if (!d) throw new AppError(\"Discount not found\", 404);\n\n  await prisma.discount.delete({ where: { id } });\n  res.json({ success: true });\n});\n\n// POST /api/discounts/evaluate — evaluate cart discounts (public, rate limited)\nrouter.post(\"/evaluate\", globalRateLimiter, async (req: Request, res: Response) => {\n  const { storeId, cartItems, subtotal, customerId, code } = req.body;\n  if (!storeId || !Array.isArray(cartItems)) throw new AppError(\"storeId and cartItems required\", 400);\n  if (cartItems.length > 100) throw new AppError(\"Too many cart items\", 400);\n\n  const input = {\n    storeId,\n    cartItems: cartItems.map((i: any) => ({\n      productId: String(i.productId || \"\"),\n      qty:       Math.max(0, Number(i.qty) || 0),\n      price:     Math.max(0, Number(i.price) || 0),\n    })),\n    subtotal:   Math.max(0, Number(subtotal) || 0),\n    customerId: customerId ? String(customerId) : undefined,\n  };\n\n  let autoDiscounts: any[] = [];\n  let codeDiscount: any    = null;\n\n  autoDiscounts = await DiscountService.getAutoDiscounts(input);\n\n  if (code) {\n    try {\n      codeDiscount = await DiscountService.validateCode(String(code).slice(0, 50), storeId, input);\n    } catch (e: any) {\n      return res.json({ success: true, data: { autoDiscounts, codeDiscount: null, codeError: e.message } });\n    }\n  }\n\n  const totalDiscount = autoDiscounts.reduce((s, d) => s + (d.amount || 0), 0)\n    + (codeDiscount?.amount || 0);\n\n  const freeShipping = autoDiscounts.some(d => d.freeShipping) || codeDiscount?.freeShipping;\n\n  res.json({\n    success: true,\n    data: { autoDiscounts, codeDiscount, totalDiscount, freeShipping },\n  });\n});\n\n// GET /api/discounts/:storeId/:id/analytics\nrouter.get(\"/:storeId/:id/analytics\", authenticate, async (req: Request, res: Response) => {\n  const { storeId, id } = req.params;\n  const d = await prisma.discount.findFirst({ where: { id, storeId } });\n  if (!d) throw new AppError(\"Discount not found\", 404);\n\n  const analytics = await DiscountService.getAnalytics(id);\n  res.json({ success: true, data: analytics });\n});\n\nexport default router;\n","backend/src/routes/features.routes.ts":"// ============================================================\n// DropOS — Priority Features Routes\n// Path: backend/src/routes/features.routes.ts\n// Add to app.ts: app.use(\"/api/features\", featuresRoutes);\n// ============================================================\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  healthScore, productGrades, atRiskCustomers,\n  achievements, revenueReplay, weeklyWinners,\n  priceTest, liveSales, sendComeback, setupStatus,\n} from \"../controllers/features.controller\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nrouter.get (\"/health/:storeId\",          healthScore);\nrouter.get (\"/product-grades/:storeId\",  productGrades);\nrouter.get (\"/at-risk/:storeId\",         atRiskCustomers);\nrouter.get (\"/achievements/:storeId\",    achievements);\nrouter.get (\"/replay/:storeId\",          revenueReplay);\nrouter.get (\"/weekly-winners/:storeId\",  weeklyWinners);\nrouter.get (\"/live-sales/:storeId\",      liveSales);\nrouter.get (\"/setup-status\",             setupStatus);\nrouter.post(\"/price-test\",               priceTest);\nrouter.post(\"/send-comeback\",            sendComeback);\n\nexport default router;\n","backend/src/routes/funnel.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { trackFunnelEvent, trackUtmSession, getFunnelAnalytics, getCohortAnalytics } from \"../controllers/funnel.controller\";\nconst r = Router();\nr.post(\"/event\", trackFunnelEvent);\nr.post(\"/utm\", trackUtmSession);\nr.get(\"/:storeId/cohort\", authenticate, getCohortAnalytics); // specific BEFORE generic\nr.get(\"/:storeId\", authenticate, getFunnelAnalytics);\nexport default r;\n","backend/src/routes/giftCard.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { createGiftCard, getGiftCards, validateGiftCard, deactivateGiftCard } from \"../controllers/giftCard.controller\";\nconst r = Router();\nr.post(\"/validate\", validateGiftCard);\nr.post(\"/:storeId\", authenticate, createGiftCard);\nr.get(\"/:storeId\", authenticate, getGiftCards);\nr.patch(\"/:storeId/:id/deactivate\", authenticate, deactivateGiftCard);\nexport default r;\n","backend/src/routes/groupbuy.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\n\n// Public: GET /api/group-buy/public/:id\nrouter.get(\"/public/:id\", async (req: Request, res: Response) => {\n  try {\n    const gb = await prisma.groupBuy.findUnique({\n      where: { id: req.params.id },\n      include: {\n        store:   { select: { name: true, slug: true, logo: true, primaryColor: true, currency: true } },\n        product: { select: { name: true, images: true, price: true } },\n        members: { select: { name: true, createdAt: true }, orderBy: { createdAt: \"asc\" } },\n      },\n    });\n    if (!gb) return res.status(404).json({ success: false, message: \"Group buy not found\" });\n    res.json({ success: true, data: { ...gb, memberCount: gb.members.length } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Public: POST /api/group-buy/:id/join\nrouter.post(\"/:id/join\", async (req: Request, res: Response) => {\n  try {\n    const { name, email } = req.body;\n    if (!name || !email) return res.status(400).json({ success: false, message: \"Name and email required\" });\n\n    const gb = await prisma.groupBuy.findUnique({ where: { id: req.params.id } });\n    if (!gb || !gb.active) return res.status(404).json({ success: false, message: \"Group buy not found or ended\" });\n    if (new Date(gb.endsAt) < new Date()) return res.status(400).json({ success: false, message: \"Group buy has ended\" });\n\n    // Check if already joined\n    const existing = await prisma.groupBuyMember.findFirst({ where: { groupBuyId: req.params.id, email } });\n    if (existing) return res.status(400).json({ success: false, message: \"You have already joined this group buy\" });\n\n    await prisma.groupBuyMember.create({ data: { groupBuyId: req.params.id, name, email } });\n    res.json({ success: true, message: \"Joined! We will email you when the group fills up.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Authenticated: POST /api/group-buy (create)\nrouter.post(\"/\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const { storeId, productId, title, description, groupPrice, originalPrice, minMembers, endsAt } = req.body;\n    const gb = await prisma.groupBuy.create({\n      data: { storeId, productId, title, description, groupPrice, originalPrice, minMembers: minMembers || 10, endsAt: new Date(endsAt) },\n    });\n    res.status(201).json({ success: true, data: gb });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// GET /api/group-buy/store/:storeId (list)\nrouter.get(\"/store/:storeId\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const gbs = await prisma.groupBuy.findMany({\n      where: { storeId: req.params.storeId },\n      include: { _count: { select: { members: true } } },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: gbs });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/invoice.routes.ts":"// src/routes/invoice.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\n\nconst router = Router();\n\n// GET /api/invoices/:orderId  — returns printable HTML invoice\nrouter.get(\"/:orderId\", authenticate, async (req: Request, res: Response) => {\n  const order = await prisma.order.findUnique({\n    where:   { id: req.params.orderId },\n    include: {\n      items: true,\n      store: true,\n    },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n\n  const symbol  = order.currency === \"NGN\" ? \"₦\" : order.currency === \"GBP\" ? \"£\" : \"$\";\n  const fmt     = (n: number) => `${symbol}${n.toFixed(2)}`;\n  const date    = new Date(order.createdAt).toLocaleDateString(\"en-US\", { year: \"numeric\", month: \"long\", day: \"numeric\" });\n  const addr    = order.shippingAddress as any;\n\n  const rows = order.items.map((item: any) => `\n    <tr>\n      <td style=\"padding:12px 14px;border-bottom:1px solid #f1f5f9;font-size:14px\">${item.name}</td>\n      <td style=\"padding:12px 14px;border-bottom:1px solid #f1f5f9;text-align:center;font-size:14px\">${item.quantity}</td>\n      <td style=\"padding:12px 14px;border-bottom:1px solid #f1f5f9;text-align:right;font-size:14px\">${fmt(item.price)}</td>\n      <td style=\"padding:12px 14px;border-bottom:1px solid #f1f5f9;text-align:right;font-weight:700;font-size:14px\">${fmt(item.total)}</td>\n    </tr>`).join(\"\");\n\n  const html = `<!DOCTYPE html>\n<html><head><meta charset=\"utf-8\"><title>Invoice ${order.orderNumber}</title>\n<style>\n  *{box-sizing:border-box;margin:0;padding:0}\n  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1e293b;padding:40px;max-width:800px;margin:0 auto}\n  .header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:40px;padding-bottom:24px;border-bottom:2px solid #e2e8f0}\n  .logo{font-size:26px;font-weight:900;color:#7c3aed}\n  table{width:100%;border-collapse:collapse;margin-bottom:24px}\n  th{background:#f8fafc;padding:10px 14px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;color:#64748b;border-bottom:2px solid #e2e8f0}\n  .total-row{display:flex;justify-content:space-between;padding:6px 0;font-size:14px;color:#475569}\n  .total-final{border-top:2px solid #7c3aed;margin-top:8px;padding-top:12px;font-size:18px;font-weight:900;color:#1e293b}\n  @media print{.no-print{display:none}}\n</style></head>\n<body>\n  <div class=\"header\">\n    <div><div class=\"logo\">⚡ DropOS</div><div style=\"color:#64748b;font-size:14px;margin-top:4px\">${order.store?.name || \"\"}</div></div>\n    <div style=\"text-align:right\">\n      <div style=\"font-size:28px;font-weight:900\">INVOICE</div>\n      <div style=\"color:#7c3aed;font-weight:700\">#${order.orderNumber}</div>\n      <div style=\"color:#64748b;font-size:13px;margin-top:4px\">${date}</div>\n    </div>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:32px\">\n    <div>\n      <div style=\"font-size:11px;font-weight:700;text-transform:uppercase;color:#64748b;margin-bottom:8px\">Bill To</div>\n      <div style=\"font-size:14px;line-height:1.8\">\n        <strong>${order.customerName}</strong><br>\n        ${order.customerEmail}<br>\n        ${addr ? `${addr.address || \"\"}<br>${addr.city || \"\"} ${addr.state || \"\"}<br>${addr.country || \"\"}` : \"\"}\n      </div>\n    </div>\n    <div>\n      <div style=\"font-size:11px;font-weight:700;text-transform:uppercase;color:#64748b;margin-bottom:8px\">Order Info</div>\n      <div style=\"font-size:14px;line-height:1.8\">\n        <strong>Order:</strong> ${order.orderNumber}<br>\n        <strong>Date:</strong> ${date}<br>\n        <strong>Status:</strong> ${order.status}\n      </div>\n    </div>\n  </div>\n\n  <table>\n    <thead><tr>\n      <th>Product</th><th style=\"text-align:center\">Qty</th>\n      <th style=\"text-align:right\">Unit Price</th><th style=\"text-align:right\">Total</th>\n    </tr></thead>\n    <tbody>${rows}</tbody>\n  </table>\n\n  <div style=\"margin-left:auto;width:260px\">\n    <div class=\"total-row\"><span>Subtotal</span><span>${fmt(order.subtotal)}</span></div>\n    ${order.shippingCost > 0 ? `<div class=\"total-row\"><span>Shipping</span><span>${fmt(order.shippingCost)}</span></div>` : \"\"}\n    ${order.taxAmount > 0 ? `<div class=\"total-row\"><span>Tax</span><span>${fmt(order.taxAmount)}</span></div>` : \"\"}\n    ${order.discountAmount > 0 ? `<div class=\"total-row\" style=\"color:#16a34a\"><span>Discount</span><span>-${fmt(order.discountAmount)}</span></div>` : \"\"}\n    <div class=\"total-row total-final\"><span>Total</span><span>${fmt(order.total)}</span></div>\n  </div>\n\n  <div style=\"margin-top:48px;padding-top:24px;border-top:1px solid #e2e8f0;text-align:center;font-size:12px;color:#94a3b8\">\n    Thank you! Questions? ${order.store?.supportEmail || \"support@dropos.io\"}\n  </div>\n\n  <div class=\"no-print\" style=\"margin-top:24px;text-align:center\">\n    <button onclick=\"window.print()\" style=\"padding:12px 28px;background:#7c3aed;color:white;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer\">\n      🖨️ Print / Save as PDF\n    </button>\n  </div>\n</body></html>`;\n\n  res.setHeader(\"Content-Type\", \"text/html\");\n  res.send(html);\n});\n\nexport default router;\n","backend/src/routes/kai.agent.routes.ts":"// ============================================================\n// KAI Agent Routes\n// Path: backend/src/routes/kai.agent.routes.ts\n// Add to app.ts: app.use(\"/api/kai/agent\", kaiAgentRoutes);\n// ============================================================\nimport { Router }    from \"express\";\nimport rateLimit     from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport { getMyStores, agentChat, executeAction, getAgentContext } from \"../controllers/kai.agent.controller\";\n\nconst router  = Router();\nconst limit   = rateLimit({ windowMs: 60000, max: 30, message: { success: false, message: \"Too many requests\" } });\n\nrouter.use(authenticate);\n\nrouter.get (\"/stores\",               getMyStores);\nrouter.post(\"/chat\",     limit,      agentChat);\nrouter.post(\"/execute\",              executeAction);\nrouter.get (\"/context/:storeId\",     getAgentContext);\n\nexport default router;\n","backend/src/routes/kai.power.routes.ts":"// ============================================================\n// KAI — Power Features Routes\n// Path: backend/src/routes/kai.power.routes.ts\n// Add to app.ts: app.use(\"/api/kai/power\", kaiPowerRoutes);\n// ============================================================\nimport { Router } from \"express\";\nimport rateLimit from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  productPage, adCopy, winningProducts,\n  profitCalc, nicheResearch, competitorAnalysis, buyerMotivation,\n} from \"../controllers/kai.power.controller\";\n\nconst router = Router();\n\n// These calls use Claude Sonnet — limit more strictly\nconst powerLimit = rateLimit({\n  windowMs: 60 * 1000,\n  max: 10,\n  message: { success: false, message: \"Rate limit reached — wait a moment\" },\n});\n\nrouter.use(authenticate);\n\nrouter.post(\"/product-page\",      powerLimit, productPage);\nrouter.post(\"/ad-copy\",           powerLimit, adCopy);\nrouter.get (\"/winning-products\",  powerLimit, winningProducts);\nrouter.post(\"/profit-calc\",       profitCalc);   // no limit — pure calculation\nrouter.post(\"/niche-research\",    powerLimit, nicheResearch);\nrouter.post(\"/competitor\",        powerLimit, competitorAnalysis);\nrouter.post(\"/buyer-motivation\",  powerLimit, buyerMotivation);\n\nexport default router;\n","backend/src/routes/kai.routes.ts":"// ============================================================\n// KAI — Complete Routes (10/10)\n// Path: backend/src/routes/kai.routes.ts\n// ============================================================\nimport { Router } from \"express\";\nimport rateLimit from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getGreeting, getConversations, getConversation, smartChat,\n  executeAction, updateConversation, deleteConversation,\n  deleteAllConversations, getKaiMemories, deleteKaiMemory,\n  getPulseAlerts, readPulseAlert, getSkills, createSkill,\n  deleteSkill, useSkill, analyzeVoice, getGoals, createGoal,\n} from \"../controllers/kai.controller\";\n\nconst router = Router();\n\nconst kaiLimit = rateLimit({\n  windowMs: 60 * 1000,\n  max: 25,\n  message: { success: false, message: \"Too many KAI requests — slow down a bit\" },\n});\n\nrouter.use(authenticate);\n\n// Core chat\nrouter.get   (\"/greeting\",              getGreeting);\nrouter.post  (\"/smart-chat\",            kaiLimit, smartChat);\nrouter.post  (\"/action\",                executeAction);\n\n// Conversations\nrouter.get   (\"/conversations\",         getConversations);\nrouter.get   (\"/conversation/:id\",      getConversation);\nrouter.patch (\"/conversation/:id\",      updateConversation);\nrouter.delete(\"/conversation/:id\",      deleteConversation);\nrouter.delete(\"/conversations/all\",     deleteAllConversations);\n\n// Memory\nrouter.get   (\"/memories\",              getKaiMemories);\nrouter.delete(\"/memory/:key\",           deleteKaiMemory);\n\n// KAI Pulse (proactive alerts)\nrouter.get   (\"/pulse\",                 getPulseAlerts);\nrouter.patch (\"/pulse/:id/read\",        readPulseAlert);\n\n// Skills (saved prompts)\nrouter.get   (\"/skills\",                getSkills);\nrouter.post  (\"/skills\",                createSkill);\nrouter.delete(\"/skills/:id\",            deleteSkill);\nrouter.post  (\"/skills/:id/use\",        useSkill);\n\n// Brand voice\nrouter.post  (\"/analyze-voice\",         analyzeVoice);\n\n// Goals\nrouter.get   (\"/goals\",                 getGoals);\nrouter.post  (\"/goals\",                 createGoal);\n\nexport default router;\n","backend/src/routes/loyalty.routes.ts":"// ============================================================\n// Loyalty Points — Routes + Controller\n// Path: backend/src/routes/loyalty.routes.ts\n// Add to app.ts: app.use(\"/api/loyalty\", loyaltyRoutes);\n// ============================================================\nimport { Router, Request, Response } from \"express\";\nimport { authenticate }       from \"../middleware/auth\";\nimport { awardPoints, redeemPoints, getLoyaltyStatus } from \"../services/loyalty.service\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/loyalty/status?customerId=X&storeId=Y\nrouter.get(\"/status\", async (req: Request, res: Response) => {\n  try {\n    const { customerId, storeId } = req.query as { customerId: string; storeId: string };\n    const data = await getLoyaltyStatus(customerId, storeId);\n    res.json({ success: true, data });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n});\n\n// POST /api/loyalty/award (called internally after order paid)\nrouter.post(\"/award\", async (req: Request, res: Response) => {\n  try {\n    const { orderId } = req.body;\n    await awardPoints(orderId);\n    res.json({ success: true });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n});\n\n// POST /api/loyalty/redeem\nrouter.post(\"/redeem\", async (req: Request, res: Response) => {\n  try {\n    const { customerId, storeId, pointsToRedeem, orderId } = req.body;\n    const result = await redeemPoints({ customerId, storeId, pointsToRedeem: Number(pointsToRedeem), orderId });\n    res.json({ success: true, data: result });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n});\n\nexport default router;\n","backend/src/routes/milestone.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/milestones/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const milestones = await prisma.milestone.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n      take: 20,\n    });\n    res.json({ success: true, data: milestones });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// PATCH /api/milestones/:id/seen\nrouter.patch(\"/:id/seen\", async (req: any, res: Response) => {\n  try {\n    await prisma.milestone.update({ where: { id: req.params.id }, data: { seen: true } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Internal: create milestone (called from other services)\nexport async function createMilestone(storeId: string, type: string, title: string, message: string, cta?: any) {\n  return prisma.milestone.create({ data: { storeId, type, title, message, cta } });\n}\n\nexport default router;\n","backend/src/routes/navlevel.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/nav-level/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const storeId = req.params.storeId;\n    const [productCount, orderCount, store] = await Promise.all([\n      prisma.product.count({ where: { storeId } }),\n      prisma.order.count({ where: { storeId } }),\n      prisma.store.findUnique({ where: { id: storeId }, select: { paystackConnected: true } }),\n    ]);\n    res.json({\n      success: true,\n      data: { productCount, orderCount, hasPaystack: store?.paystackConnected ?? false },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/notification.routes.ts":"// src/routes/notification.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nrouter.get(\"/\", async (req: any, res) => {\n  const notifications = await prisma.notification.findMany({\n    where: { userId: req.user!.userId },\n    orderBy: { createdAt: \"desc\" },\n    take: 50,\n  });\n  return res.json({ success: true, data: notifications });\n});\n\nrouter.patch(\"/:id/read\", async (req: any, res) => {\n  await prisma.notification.update({\n    where: { id: req.params.id, userId: req.user!.userId },\n    data:  { read: true },\n  });\n  return res.json({ success: true });\n});\n\nrouter.patch(\"/mark-all-read\", async (req: any, res) => {\n  await prisma.notification.updateMany({\n    where: { userId: req.user!.userId, read: false },\n    data:  { read: true },\n  });\n  return res.json({ success: true });\n});\n\nrouter.get(\"/unread-count\", async (req: any, res) => {\n  const count = await prisma.notification.count({\n    where: { userId: req.user!.userId, read: false },\n  });\n  return res.json({ success: true, data: { count } });\n});\n\nexport default router;\n","backend/src/routes/notificationSettings.routes.ts":"// src/routes/notificationSettings.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getNotificationSettings,\n  updateNotificationSettings,\n  sendTestNotification,\n  getNotificationLogs,\n} from \"../controllers/notificationSettings.controller\";\n\nconst router = Router();\n\nrouter.get (\"/logs/:storeId\",   authenticate, getNotificationLogs);\nrouter.post(\"/test/:storeId\",   authenticate, sendTestNotification);\nrouter.get (\"/:storeId\",        authenticate, getNotificationSettings);\nrouter.put (\"/:storeId\",        authenticate, updateNotificationSettings);\n\nexport default router;\n","backend/src/routes/onboarding.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// POST /api/onboarding/complete\nrouter.post(\"/complete\", async (req: any, res: Response) => {\n  try {\n    const { niche, stage, goal, template } = req.body;\n    const userId  = req.user.id;\n    const storeId = req.user.stores?.[0]?.id;\n\n    // Update user as onboarded\n    const user = await prisma.user.update({\n      where: { id: userId },\n      data: { onboarded: true, onboardNiche: niche, onboardStage: stage, onboardGoal: goal, onboardTemplate: template },\n    });\n\n    // Apply template to store if exists\n    if (storeId && template) {\n      await prisma.store.update({\n        where: { id: storeId },\n        data: { templateId: template, primaryColor: getColorForNiche(niche) },\n      }).catch(() => {}); // Non-critical\n    }\n\n    // Generate KIRO welcome message based on answers\n    const nicheLabels: Record<string,string> = {\n      hair:\"Hair and Beauty\", fashion:\"Fashion and Clothing\", electronics:\"Electronics\",\n      food:\"Food and Drinks\", skincare:\"Skincare and Wellness\", home:\"Home and Living\",\n      kids:\"Kids and Baby\", other:\"your niche\",\n    };\n    const nicheLabel = nicheLabels[niche] || \"your niche\";\n\n    const kiroMessage = `Perfect. I am setting up your ${nicheLabel} store right now. I am picking the best template, importing trending products in your category, and configuring Paystack for Nigerian buyers. This takes about 10 seconds.`;\n\n    // Create first milestone: store setup\n    if (storeId) {\n      await prisma.milestone.create({\n        data: {\n          storeId, type: \"store_complete\",\n          title: \"Your store is live\",\n          message: `KIRO has set up your ${nicheLabel} store. Share your link and get your first sale today.`,\n          cta: { label: \"View your store\", href: \"/dashboard/stores\" },\n        },\n      }).catch(() => {});\n    }\n\n    res.json({ success: true, data: { kiroMessage, user: { ...user, password: undefined } } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nfunction getColorForNiche(niche: string): string {\n  const colors: Record<string,string> = {\n    hair:\"#E91E8C\", fashion:\"#8B5CF6\", electronics:\"#06B6D4\",\n    food:\"#F59E0B\", skincare:\"#10B981\", home:\"#F97316\", kids:\"#EC4899\",\n  };\n  return colors[niche] || \"#6B35E8\";\n}\n\nexport default router;\n","backend/src/routes/order.routes.ts":"// src/routes/order.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  createOrder, getOrders, getOrder,\n  updateOrderStatus, trackOrder,\n} from \"../controllers/order.controller\";\n\nconst router = Router();\n\n// Public\nrouter.post(\"/\",                        createOrder);\nrouter.get (\"/track/:orderNumber\",      trackOrder);\n\n// Authenticated store owners\nrouter.get (\"/:storeId\",                authenticate, getOrders);\nrouter.get (\"/:storeId/:orderId\",       authenticate, getOrder);\nrouter.patch(\"/:storeId/:orderId/status\", authenticate, updateOrderStatus);\n\nexport default router;\n","backend/src/routes/payment.routes.ts":"// src/routes/payment.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { paymentRateLimiter } from \"../middleware/rateLimiter\";\nimport {\n  initializePayment, verifyPayment,\n  stripeWebhook, paystackWebhook, flutterwaveWebhook,\n  getAllPayments,\n} from \"../controllers/payment.controller\";\n\nconst router = Router();\n\n// Webhooks\nrouter.post(\"/webhook/stripe\",      stripeWebhook);\nrouter.post(\"/webhook/paystack\",    paystackWebhook);\nrouter.post(\"/webhook/flutterwave\", flutterwaveWebhook);\n\n// Public checkout\nrouter.post(\"/initialize\",          paymentRateLimiter, initializePayment);\nrouter.get (\"/verify\",              verifyPayment);\n\n// Admin\nrouter.get (\"/admin/all\",           authenticate, getAllPayments);\n\nexport default router;","backend/src/routes/product.routes.ts":"// src/routes/product.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  createProduct, getProducts, getProduct,\n  updateProduct, deleteProduct, bulkCreateProducts,\n  getPublicProducts, getPublicProduct,\n  createVariant, updateVariant, deleteVariant, getVariants,\n} from \"../controllers/product.controller\";\n\nconst router = Router();\n\n// Public store products\nrouter.get (\"/public/:storeId\",             getPublicProducts);\nrouter.get (\"/public/:storeId/:slug\",       getPublicProduct);\n\n// Authenticated store management\nrouter.post  (\"/:storeId\",                              authenticate, createProduct);\nrouter.post  (\"/:storeId/bulk\",                         authenticate, bulkCreateProducts);\nrouter.get   (\"/:storeId\",                              authenticate, getProducts);\nrouter.get   (\"/:storeId/:productId\",                   authenticate, getProduct);\nrouter.put   (\"/:storeId/:productId\",                   authenticate, updateProduct);\nrouter.delete(\"/:storeId/:productId\",                   authenticate, deleteProduct);\n\n// Variant management\nrouter.get   (\"/:storeId/:productId/variants\",            authenticate, getVariants);\nrouter.post  (\"/:storeId/:productId/variants\",            authenticate, createVariant);\nrouter.put   (\"/:storeId/:productId/variants/:variantId\", authenticate, updateVariant);\nrouter.delete(\"/:storeId/:productId/variants/:variantId\", authenticate, deleteVariant);\n\nexport default router;\n","backend/src/routes/productSubscription.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { createProductSubscription, getProductSubscriptions, updateProductSubscription } from \"../controllers/productSubscription.controller\";\nconst r = Router();\nr.post(\"/:storeId\", createProductSubscription);\nr.get(\"/:storeId\", authenticate, getProductSubscriptions);\nr.patch(\"/:storeId/:subId\", authenticate, updateProductSubscription);\nexport default r;\n","backend/src/routes/push.routes.ts":"// src/routes/push.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { pushToUser, PushTemplates } from \"../services/push.service\";\nimport { AppError } from \"../utils/AppError\";\n\nconst router = Router();\n\n// ── GET /api/push/vapid-public-key — returns public VAPID key to client ─────\nrouter.get(\"/vapid-public-key\", (req: Request, res: Response) => {\n  const key = process.env.VAPID_PUBLIC_KEY;\n  if (!key) return res.json({ success: false, data: { key: null } });\n  res.json({ success: true, data: { key } });\n});\n\n// ── POST /api/push/subscribe — save a new push subscription ─────────────────\nrouter.post(\"/subscribe\", authenticate, async (req: Request, res: Response) => {\n  const { endpoint, keys, deviceName } = req.body;\n  if (!endpoint || !keys?.p256dh || !keys?.auth)\n    throw new AppError(\"endpoint, keys.p256dh, and keys.auth required\", 400);\n\n  // Validate endpoint is a real HTTPS push service URL (SSRF prevention)\n  let endpointUrl: URL;\n  try { endpointUrl = new URL(endpoint); } catch { throw new AppError(\"Invalid endpoint URL\", 400); }\n  if (endpointUrl.protocol !== \"https:\") throw new AppError(\"Endpoint must use HTTPS\", 400);\n  const ALLOWED_PUSH_HOSTS = [\n    \"fcm.googleapis.com\", \"updates.push.services.mozilla.com\",\n    \"notify.windows.com\", \"push.apple.com\", \"web.push.apple.com\",\n  ];\n  if (!ALLOWED_PUSH_HOSTS.some(h => endpointUrl.hostname.endsWith(h)))\n    throw new AppError(\"Endpoint host not allowed\", 400);\n\n  // Sanitize deviceName\n  const safeName = deviceName ? String(deviceName).slice(0, 100) : undefined;\n\n  const userId = (req as any).user.userId;\n\n  // Upsert — if endpoint already registered, just reactivate\n  await prisma.pushSubscription.upsert({\n    where:  { endpoint },\n    create: { userId, endpoint, p256dh: keys.p256dh, auth: keys.auth, deviceName: safeName, isActive: true },\n    update: { userId, p256dh: keys.p256dh, auth: keys.auth, deviceName: safeName, isActive: true },\n  });\n\n  res.json({ success: true, data: { message: \"Subscribed successfully\" } });\n});\n\n// ── DELETE /api/push/unsubscribe — remove subscription ──────────────────────\nrouter.delete(\"/unsubscribe\", authenticate, async (req: Request, res: Response) => {\n  const { endpoint } = req.body;\n  if (!endpoint) throw new AppError(\"endpoint required\", 400);\n\n  await prisma.pushSubscription.updateMany({\n    where: { endpoint, userId: (req as any).user.userId },\n    data:  { isActive: false },\n  });\n\n  res.json({ success: true });\n});\n\n// ── GET /api/push/subscriptions — list user's devices ───────────────────────\nrouter.get(\"/subscriptions\", authenticate, async (req: Request, res: Response) => {\n  const userId = (req as any).user.userId;\n  const subs = await prisma.pushSubscription.findMany({\n    where:   { userId, isActive: true },\n    orderBy: { createdAt: \"desc\" },\n    select:  { id: true, deviceName: true, createdAt: true, endpoint: true },\n  });\n  res.json({ success: true, data: subs });\n});\n\n// ── POST /api/push/test — send test notification to self ─────────────────────\nrouter.post(\"/test\", authenticate, async (req: Request, res: Response) => {\n  const userId = (req as any).user.userId;\n  const sent = await pushToUser(userId, {\n    title: \"🎉 DropOS Push Notifications\",\n    body:  \"Push notifications are working perfectly!\",\n    tag:   \"test\",\n    url:   \"/dashboard/notifications\",\n  });\n  if (sent === 0) throw new AppError(\"No active subscriptions or VAPID not configured\", 400);\n  res.json({ success: true, data: { sent } });\n});\n\n// ── POST /api/push/send/:storeId — manual push from dashboard ───────────────\nrouter.post(\"/send/:storeId\", authenticate, async (req: Request, res: Response) => {\n  const userId = (req as any).user.userId;\n  const { title, body, url } = req.body;\n  if (!title || !body) throw new AppError(\"title and body required\", 400);\n  if (typeof title !== \"string\" || title.length > 100) throw new AppError(\"title must be string under 100 chars\", 400);\n  if (typeof body  !== \"string\" || body.length  > 500) throw new AppError(\"body must be string under 500 chars\", 400);\n  // Validate URL if provided\n  if (url) { try { new URL(url); } catch { throw new AppError(\"Invalid url\", 400); } }\n\n  const sent = await pushToUser(userId, { title, body, url, icon: \"/icons/icon-192.png\" });\n  res.json({ success: true, data: { sent } });\n});\n\nexport default router;\n","backend/src/routes/referral.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport crypto from \"crypto\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/referral/stats\nrouter.get(\"/stats\", async (req: any, res: Response) => {\n  try {\n    let referral = await prisma.referral.findUnique({ where: { userId: req.user.id } });\n    if (!referral) {\n      const code = crypto.randomBytes(4).toString(\"hex\").toUpperCase();\n      referral = await prisma.referral.create({ data: { userId: req.user.id, code } });\n    }\n    res.json({ success: true, data: referral });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/referral/click (track referral click)\nrouter.post(\"/click\", async (req: Request, res: Response) => {\n  try {\n    const { code } = req.body;\n    if (!code) return res.status(400).json({ success: false });\n    await prisma.referral.update({ where: { code }, data: { clicks: { increment: 1 } } }).catch(() => {});\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/refund.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { createRefund, getRefunds, processRefund, customerRequestRefund } from \"../controllers/refund.controller\";\nconst r = Router();\nr.post(\"/customer/:orderNumber\", customerRequestRefund);\nr.post(\"/:storeId/:orderId\", authenticate, createRefund);\nr.get(\"/:storeId\", authenticate, getRefunds);\nr.patch(\"/:storeId/:refundId/process\", authenticate, processRefund);\nexport default r;\n","backend/src/routes/reports.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nfunction toCSV(headers: string[], rows: any[][]): string {\n  const escape = (v: any) => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n  return [headers.map(escape).join(\",\"), ...rows.map(r => r.map(escape).join(\",\"))].join(\"\\n\");\n}\n\n// GET /api/reports/:storeId/:reportId\nrouter.get(\"/:storeId/:reportId\", async (req: any, res: Response) => {\n  try {\n    const { storeId, reportId } = req.params;\n    const period = parseInt(req.query.period as string) || 30;\n    const format = req.query.format as string || \"csv\";\n    const since  = new Date(Date.now() - period * 86400000);\n\n    let csv = \"\";\n    let filename = `dropos-${reportId}`;\n\n    switch (reportId) {\n      case \"revenue\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Total (NGN)\", \"Status\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, o.total, o.status, o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-revenue-${period}days`;\n        break;\n      }\n      case \"orders\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          include: { customer: { select: { name: true, email: true } }, items: { include: { product: { select: { name: true } } } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Customer Name\", \"Customer Email\", \"Items\", \"Total\", \"Status\", \"Date\"],\n          orders.map(o => [\n            o.id, o.customer?.name ?? \"Guest\", o.customer?.email ?? \"\",\n            o.items.map((i: any) => i.product?.name ?? \"\").join(\"; \"),\n            o.total, o.status, o.createdAt.toISOString().split(\"T\")[0],\n          ])\n        );\n        filename = `dropos-orders-${period}days`;\n        break;\n      }\n      case \"customers\": {\n        const customers = await prisma.storeCustomer.findMany({\n          where: { storeId },\n          include: { _count: { select: { orders: true } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Customer ID\", \"Name\", \"Email\", \"Phone\", \"Total Orders\", \"Joined\"],\n          customers.map(c => [c.id, c.name, c.email, c.phone ?? \"\", c._count.orders, c.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-customers`;\n        break;\n      }\n      case \"products\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, price: true, inventory: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"Price (NGN)\", \"Stock\", \"Status\", \"Created\"],\n          products.map(p => [p.id, p.name, p.price, p.inventory, p.status, p.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-products`;\n        break;\n      }\n      case \"inventory\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, sku: true, inventory: true, price: true },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"SKU\", \"Stock\", \"Price (NGN)\"],\n          products.map(p => [p.id, p.name, p.sku ?? \"\", p.inventory, p.price])\n        );\n        filename = `dropos-inventory`;\n        break;\n      }\n      case \"tax\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, tax: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Subtotal\", \"Tax\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, (o.total - (o.tax || 0)).toFixed(2), (o.tax || 0).toFixed(2), o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-tax-${period}days`;\n        break;\n      }\n      default:\n        return res.status(400).json({ success: false, message: \"Unknown report type\" });\n    }\n\n    res.setHeader(\"Content-Type\", \"text/csv\");\n    res.setHeader(\"Content-Disposition\", `attachment; filename=\"${filename}.csv\"`);\n    res.send(csv);\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/returns.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  requestReturn, getReturns, updateReturn,\n  createFlashSale, getFlashSales, updateFlashSale, deleteFlashSale, getActiveFlashSales,\n  exportStoreData,\n} from \"../controllers/returns.controller\";\n\nconst r = Router();\n\n// Returns\nr.post(\"/return/:orderNumber\",             requestReturn);\nr.get(\"/returns/:storeId\",                 authenticate, getReturns);\nr.patch(\"/returns/:storeId/:returnId\",     authenticate, updateReturn);\n\n// Flash Sales — specific routes BEFORE generic /:storeId\nr.get(\"/flash-sales/:storeId/active\",      getActiveFlashSales);   // public, specific first\nr.get(\"/flash-sales/:storeId\",             authenticate, getFlashSales);\nr.post(\"/flash-sales/:storeId\",            authenticate, createFlashSale);\nr.patch(\"/flash-sales/:storeId/:saleId\",   authenticate, updateFlashSale);\nr.delete(\"/flash-sales/:storeId/:saleId\",  authenticate, deleteFlashSale);\n\n// Export\nr.get(\"/export/:storeId\",                  authenticate, exportStoreData);\n\nexport default r;\n","backend/src/routes/review.routes.ts":"// src/routes/review.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport prisma from \"../lib/prisma\";\nimport { authenticate } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\nimport { AppError } from \"../utils/AppError\";\nimport { globalRateLimiter } from \"../middleware/rateLimiter\";\n\nconst router = Router();\n\n// GET /api/reviews/:storeId/all — dashboard (all reviews including unapproved)\nrouter.get(\"/:storeId/all\", authenticate, async (req: Request, res: Response) => {\n  const reviews = await prisma.review.findMany({\n    where:   { storeId: req.params.storeId },\n    orderBy: { createdAt: \"desc\" },\n  });\n  res.json({ success: true, data: reviews });\n});\n\n// GET /api/reviews/:storeId/:productId — public (approved only)\nrouter.get(\"/:storeId/:productId\", async (req: Request, res: Response) => {\n  const reviews = await prisma.review.findMany({\n    where:   { productId: req.params.productId, storeId: req.params.storeId, approved: true },\n    orderBy: { createdAt: \"desc\" },\n  });\n  res.json({ success: true, data: reviews });\n});\n\n// POST /api/reviews/:storeId/:productId — public (customer submits)\nrouter.post(\"/:storeId/:productId\", globalRateLimiter, async (req: Request, res: Response) => {\n  const { name, email, rating, title, body } = req.body;\n  if (!name || !email || !rating || !body) throw new AppError(\"name, email, rating, body required\", 400);\n  if (Number(rating) < 1 || Number(rating) > 5) throw new AppError(\"Rating must be 1–5\", 400);\n\n  const dupe = await prisma.review.findFirst({ where: { productId: req.params.productId, email } });\n  if (dupe) throw new AppError(\"You have already reviewed this product\", 400);\n\n  const review = await prisma.review.create({\n    data: {\n      storeId:   req.params.storeId,\n      productId: req.params.productId,\n      name, email,\n      rating:  Number(rating),\n      title:   title || null,\n      body,\n      approved: false,\n      helpful:  0,\n    },\n  });\n\n  // Notify store owner\n  try {\n    const store = await prisma.store.findUnique({\n      where:   { id: req.params.storeId },\n      include: { owner: { select: { email: true, name: true } } },\n    });\n    const product = await prisma.product.findUnique({\n      where:  { id: req.params.productId },\n      select: { name: true },\n    });\n    if (store && product) {\n      emailService.sendNewReviewAlert(\n        store.owner.email,\n        store.owner.name,\n        product.name,\n        name,\n        Number(rating),\n        store.name\n      );\n    }\n  } catch {}\n\n  res.status(201).json({ success: true, data: review, message: \"Review submitted — pending approval\" });\n});\n\n// POST helpful\nrouter.post(\"/:storeId/:productId/:id/helpful\", globalRateLimiter, async (req: Request, res: Response) => {\n  await prisma.review.update({ where: { id: req.params.id }, data: { helpful: { increment: 1 } } });\n  res.json({ success: true });\n});\n\n// PATCH approve\nrouter.patch(\"/:storeId/:id/approve\", authenticate, async (req: Request, res: Response) => {\n  const review = await prisma.review.update({ where: { id: req.params.id }, data: { approved: true } });\n  res.json({ success: true, data: review });\n});\n\n// PATCH feature toggle\nrouter.patch(\"/:storeId/:id/feature\", authenticate, async (req: Request, res: Response) => {\n  const r = await prisma.review.findFirst({ where: { id: req.params.id, storeId: req.params.storeId } });\n  if (!r) throw new AppError(\"Review not found\", 404);\n  const updated = await prisma.review.update({ where: { id: req.params.id }, data: { featured: !r.featured } });\n  res.json({ success: true, data: updated });\n});\n\n// PATCH reply\nrouter.patch(\"/:storeId/:id/reply\", authenticate, async (req: Request, res: Response) => {\n  const { replyBody } = req.body;\n  const updated = await prisma.review.update({\n    where: { id: req.params.id },\n    data:  { replyBody: replyBody || null, repliedAt: replyBody ? new Date() : null },\n  });\n  res.json({ success: true, data: updated });\n});\n\n// POST approve-all pending\nrouter.post(\"/:storeId/approve-all\", authenticate, async (req: Request, res: Response) => {\n  const result = await prisma.review.updateMany({\n    where: { storeId: req.params.storeId, approved: false },\n    data:  { approved: true },\n  });\n  res.json({ success: true, data: { count: result.count } });\n});\n\n// DELETE\nrouter.delete(\"/:storeId/:id\", authenticate, async (req: Request, res: Response) => {\n  await prisma.review.delete({ where: { id: req.params.id } });\n  res.json({ success: true });\n});\n\nexport default router;\n","backend/src/routes/shipping.routes.ts":"// src/routes/shipping.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\n\nconst router = Router();\n\n// GET /api/shipping/:storeId/rate?country=Nigeria&total=45  (public — before /:storeId)\nrouter.get(\"/:storeId/rate\", async (req: Request, res: Response) => {\n  const { country, total } = req.query;\n  const zones = await prisma.shippingZone.findMany({\n    where:   { storeId: req.params.storeId },\n    orderBy: { createdAt: \"asc\" },\n  });\n  const match = zones.find((z) =>\n    z.countries.some((c) => c.toLowerCase() === String(country || \"\").toLowerCase())\n  ) || zones.find((z) => z.countries.includes(\"Worldwide\") || z.countries.includes(\"*\"));\n\n  if (!match) return res.json({ success: true, data: { rate: 0, zone: null, free: true } });\n\n  const orderTotal = Number(total) || 0;\n  const free = match.freeThreshold ? orderTotal >= match.freeThreshold : match.shippingRate === 0;\n  res.json({ success: true, data: { rate: free ? 0 : match.shippingRate, zone: match.name, free, estimatedDays: match.estimatedDays, freeThreshold: match.freeThreshold } });\n});\n\n// GET /api/shipping/:storeId\nrouter.get(\"/:storeId\", authenticate, async (req: Request, res: Response) => {\n  const zones = await prisma.shippingZone.findMany({ where: { storeId: req.params.storeId }, orderBy: { createdAt: \"asc\" } });\n  res.json({ success: true, data: zones });\n});\n\n// POST /api/shipping/:storeId\nrouter.post(\"/:storeId\", authenticate, async (req: Request, res: Response) => {\n  const { name, countries, shippingRate, freeThreshold, estimatedDays } = req.body;\n  const zone = await prisma.shippingZone.create({\n    data: {\n      storeId:       req.params.storeId,\n      name,\n      countries:     Array.isArray(countries) ? countries : [countries],\n      shippingRate:  Number(shippingRate) || 0,\n      freeThreshold: freeThreshold ? Number(freeThreshold) : null,\n      estimatedDays: estimatedDays || null,\n    },\n  });\n  res.status(201).json({ success: true, data: zone });\n});\n\n// PUT /api/shipping/:storeId/:id\nrouter.put(\"/:storeId/:id\", authenticate, async (req: Request, res: Response) => {\n  const { name, countries, shippingRate, freeThreshold, estimatedDays } = req.body;\n  const zone = await prisma.shippingZone.update({\n    where: { id: req.params.id },\n    data: {\n      name,\n      countries:     Array.isArray(countries) ? countries : [countries],\n      shippingRate:  Number(shippingRate) || 0,\n      freeThreshold: freeThreshold ? Number(freeThreshold) : null,\n      estimatedDays: estimatedDays || null,\n    },\n  });\n  res.json({ success: true, data: zone });\n});\n\n// DELETE\nrouter.delete(\"/:storeId/:id\", authenticate, async (req: Request, res: Response) => {\n  await prisma.shippingZone.delete({ where: { id: req.params.id } });\n  res.json({ success: true });\n});\n\nexport default router;\n","backend/src/routes/store.routes.ts":"// backend/src/routes/store.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  createStore, getMyStores, getStore,\n  updateStore, deleteStore, updateDomain,\n  getPublicStore,\n} from \"../controllers/store.controller\";\n\nconst router = Router();\n\n// Public\nrouter.get(\"/public/:slug\", getPublicStore);\n\n// Authenticated\nrouter.post(\"/\",            authenticate, createStore);\nrouter.get(\"/\",             authenticate, getMyStores);\nrouter.get(\"/:id\",          authenticate, getStore);\nrouter.put(\"/:id\",          authenticate, updateStore);\nrouter.patch(\"/:id\",        authenticate, updateStore);\nrouter.delete(\"/:id\",       authenticate, deleteStore);\nrouter.patch(\"/:id/domain\", authenticate, updateDomain);\n\nexport default router;","backend/src/routes/supercharge.routes.ts":"// ============================================================\n// Supercharge Routes\n// Path: backend/src/routes/supercharge.routes.ts\n// Add to app.ts: app.use(\"/api/super\", superchargeRoutes);\n// ============================================================\nimport { Router }    from \"express\";\nimport rateLimit     from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  listBroadcasts, createBroadcastHandler, sendBroadcastHandler,\n  generateMessageHandler, audiencePreview,\n  removeBg, generateLifestyle, generateAd,\n  forecast, scrapeProduct, importScrapedProduct,\n} from \"../controllers/supercharge.controller\";\n\nconst router  = Router();\nconst aiLimit = rateLimit({ windowMs: 60000, max: 15, message: { success: false, message: \"Rate limit\" } });\n\nrouter.use(authenticate);\n\n// Broadcasts\nrouter.get  (\"/broadcasts\",               listBroadcasts);\nrouter.post (\"/broadcasts\",               createBroadcastHandler);\nrouter.post (\"/broadcasts/:broadcastId/send\", sendBroadcastHandler);\nrouter.post (\"/broadcasts/generate\",      aiLimit, generateMessageHandler);\nrouter.get  (\"/broadcasts/audience\",      audiencePreview);\n\n// Image Studio\nrouter.post (\"/images/remove-bg\",         aiLimit, removeBg);\nrouter.post (\"/images/lifestyle\",         aiLimit, generateLifestyle);\nrouter.post (\"/images/ad-creative\",       aiLimit, generateAd);\n\n// Forecasting\nrouter.get  (\"/forecast\",                 aiLimit, forecast);\n\n// Product Scraper\nrouter.post (\"/scrape\",                   aiLimit, scrapeProduct);\nrouter.post (\"/import\",                   importScrapedProduct);\n\nexport default router;\n","backend/src/routes/support.routes.ts":"// src/routes/support.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport prisma from \"../lib/prisma\";\nimport { z } from \"zod\";\nimport { paginate } from \"../utils/helpers\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// Create ticket (store owner)\nrouter.post(\"/\", async (req: any, res) => {\n  const { subject, message, priority } = z.object({\n    subject:  z.string().min(5),\n    message:  z.string().min(10),\n    priority: z.enum([\"LOW\",\"MEDIUM\",\"HIGH\",\"URGENT\"]).default(\"MEDIUM\"),\n  }).parse(req.body);\n\n  const ticket = await prisma.supportTicket.create({\n    data: { userId: req.user!.userId, subject, message, priority },\n  });\n  return res.status(201).json({ success: true, data: ticket });\n});\n\n// Get my tickets\nrouter.get(\"/\", async (req: any, res) => {\n  const { page = 1, limit = 20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where = req.user!.role === \"SUPER_ADMIN\" ? {} : { userId: req.user!.userId };\n  const [tickets, total] = await Promise.all([\n    await prisma.supportTicket.findMany({\n      where, take, skip,\n      include: { user: { select: { name: true, email: true } }, replies: true },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.supportTicket.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: tickets,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n});\n\n// Reply / resolve (admin)\nrouter.patch(\"/:ticketId\", async (req: any, res) => {\n  const { message, status } = z.object({\n    message: z.string().optional(),\n    status:  z.enum([\"OPEN\",\"IN_PROGRESS\",\"RESOLVED\",\"CLOSED\"]).optional(),\n  }).parse(req.body);\n\n  const ticket = await prisma.supportTicket.update({\n    where: { id: req.params.ticketId },\n    data: {\n      status,\n      ...(message && { adminReply: message }),\n      ...(status === \"RESOLVED\" && { resolvedAt: new Date() }),\n    },\n  });\n\n  if (message) {\n    await prisma.ticketReply.create({\n      data: {\n        ticketId: ticket.id,\n        senderId: req.user!.userId,\n        isAdmin:  req.user!.role === \"SUPER_ADMIN\",\n        message,\n      },\n    });\n  }\n\n  return res.json({ success: true, data: ticket });\n});\n\nexport default router;\n","backend/src/routes/theme.routes.ts":"// ============================================================\n// Theme Routes\n// Path: backend/src/routes/theme.routes.ts\n// Add to app.ts: app.use(\"/api/theme\", themeRoutes);\n// ============================================================\nimport { Router }    from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { getTheme, updateTheme, kaiThemeCommand } from \"../controllers/theme.controller\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nrouter.get  (\"/:storeId\",     getTheme);\nrouter.patch(\"/:storeId\",     updateTheme);\nrouter.post (\"/:storeId/kai\", kaiThemeCommand);\n\nexport default router;\n","backend/src/routes/twoFA.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { setup2FA, verify2FA, disable2FA, validate2FALogin } from \"../controllers/twoFA.controller\";\nconst r = Router();\nr.post(\"/setup\", authenticate, setup2FA);\nr.post(\"/verify\", authenticate, verify2FA);\nr.post(\"/disable\", authenticate, disable2FA);\nr.post(\"/validate\", validate2FALogin);\nexport default r;\n","backend/src/routes/upload.routes.ts":"// src/routes/upload.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport multer from \"multer\";\nimport { authenticate } from \"../middleware/auth\";\nimport { AppError } from \"../utils/AppError\";\nimport { v2 as cloudinary } from \"cloudinary\";\nimport { Readable } from \"stream\";\n\n// ── Cloudinary config ─────────────────────────────────────────────────────────\n// REPLACE with your real Cloudinary credentials when going live\n// Get them FREE at https://cloudinary.com → Dashboard → API Keys\ncloudinary.config({\n  cloud_name: process.env.CLOUDINARY_CLOUD_NAME || \"demo\",\n  api_key:    process.env.CLOUDINARY_API_KEY    || \"demo\",\n  api_secret: process.env.CLOUDINARY_API_SECRET || \"demo\",\n});\n\nconst USE_CLOUDINARY = !!(\n  process.env.CLOUDINARY_CLOUD_NAME &&\n  process.env.CLOUDINARY_API_KEY &&\n  process.env.CLOUDINARY_API_SECRET &&\n  process.env.CLOUDINARY_CLOUD_NAME !== \"demo\"\n);\n\n// ── Multer memory storage ──────────────────────────────────────────────────────\n// Verify actual file bytes match claimed mimetype (prevent mimetype spoofing)\nfunction verifyImageMagicBytes(buffer: Buffer, mimetype: string): boolean {\n  if (buffer.length < 4) return false;\n  const b = buffer;\n  if (mimetype === \"image/jpeg\") return b[0] === 0xFF && b[1] === 0xD8 && b[2] === 0xFF;\n  if (mimetype === \"image/png\")  return b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4E && b[3] === 0x47;\n  if (mimetype === \"image/webp\") return b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50;\n  if (mimetype === \"image/gif\")  return b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46;\n  return false;\n}\n\nconst MAX_FILE_BYTES = (Number(process.env.MAX_FILE_SIZE_MB) || 5) * 1024 * 1024; // 5MB default\n\nconst upload = multer({\n  storage: multer.memoryStorage(),\n  limits:  { fileSize: MAX_FILE_BYTES, files: 10 },\n  fileFilter: (_req, file, cb) => {\n    const allowed = [\"image/jpeg\", \"image/png\", \"image/webp\", \"image/gif\"];\n    if (!allowed.includes(file.mimetype))\n      return cb(new AppError(\"Only JPEG, PNG, WebP, GIF images allowed\", 400));\n    // Sanitize filename\n    file.originalname = file.originalname.replace(/[^a-zA-Z0-9._-]/g, \"_\").slice(0, 100);\n    cb(null, true);\n  },\n});\n\n// ── Upload buffer to Cloudinary ────────────────────────────────────────────────\nfunction uploadToCloudinary(buffer: Buffer, folder = \"dropos/products\", mimetype = \"image/jpeg\"): Promise<{ url: string; publicId: string }> {\n  // Double-check magic bytes before uploading\n  if (!verifyImageMagicBytes(buffer, mimetype)) {\n    return Promise.reject(new AppError(\"File content does not match its type\", 400));\n  }\n  return new Promise((resolve, reject) => {\n    const stream = cloudinary.uploader.upload_stream(\n      { folder, transformation: [{ quality: \"auto\", fetch_format: \"auto\" }] },\n      (err, result) => {\n        if (err || !result) return reject(err || new Error(\"Upload failed\"));\n        resolve({ url: result.secure_url, publicId: result.public_id });\n      }\n    );\n    Readable.from(buffer).pipe(stream);\n  });\n}\n\nasync function saveLocally(file: any /* Express.Multer.File */): Promise<string> {\n  const fs   = await import(\"fs\");\n  const path = await import(\"path\");\n  const { v4: uuid } = await import(\"uuid\");\n  const uploadDir = path.join(process.cwd(), \"uploads\");\n  if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir, { recursive: true });\n  const ext      = path.extname(file.originalname);\n  const filename = `${uuid()}${ext}`;\n  fs.writeFileSync(path.join(uploadDir, filename), file.buffer);\n  return `${process.env.BACKEND_URL || \"http://localhost:5000\"}/uploads/${filename}`;\n}\n\nconst router = Router();\nrouter.use(authenticate);\n\n// POST /api/upload\nrouter.post(\"/\", upload.single(\"file\"), async (req: Request, res: Response) => {\n  if (!req.file) throw new AppError(\"No file uploaded\", 400);\n  if (USE_CLOUDINARY) {\n    const { url, publicId } = await uploadToCloudinary(req.file.buffer);\n    return res.json({ success: true, data: { url, publicId } });\n  }\n  const url = await saveLocally(req.file);\n  return res.json({ success: true, data: { url, publicId: url } });\n});\n\n// POST /api/upload/multiple\nrouter.post(\"/multiple\", upload.array(\"files\", 10), async (req: Request, res: Response) => {\n  const files = req.files as any /* Express.Multer.File */[];\n  if (!files?.length) throw new AppError(\"No files uploaded\", 400);\n  if (USE_CLOUDINARY) {\n    const results = await Promise.all(files.map((f) => uploadToCloudinary(f.buffer)));\n    return res.json({ success: true, data: { urls: results.map((r) => r.url), publicIds: results.map((r) => r.publicId) } });\n  }\n  const urls = await Promise.all(files.map(saveLocally));\n  return res.json({ success: true, data: { urls } });\n});\n\n// DELETE /api/upload\nrouter.delete(\"/\", async (req: Request, res: Response) => {\n  const { publicId } = req.body;\n  if (!publicId) throw new AppError(\"publicId required\", 400);\n  if (USE_CLOUDINARY) await cloudinary.uploader.destroy(publicId);\n  return res.json({ success: true, message: \"Deleted\" });\n});\n\nexport default router;\n","backend/src/routes/upsell.routes.ts":"// src/routes/upsell.routes.ts\nimport { Router } from \"express\";\nimport { getUpsellProducts, getFrequentlyBoughtTogether, getCartUpsell } from \"../controllers/upsell.controller\";\n\nconst r = Router();\n\n// All public — no auth needed\nr.get (\"/:storeId/:productId/related\",              getUpsellProducts);\nr.get (\"/:storeId/:productId/bought-together\",      getFrequentlyBoughtTogether);\nr.post(\"/:storeId/cart-suggestions\",                getCartUpsell);\n\nexport default r;\n","backend/src/routes/waitlist.routes.ts":"// backend/src/routes/waitlist.routes.ts\nimport { Router } from \"express\";\nimport {\n  joinWaitlist,\n  getWaitlistStats,\n  getWaitlistEntries,\n  deleteWaitlistEntry,\n  resendWaitlistEmail,\n} from \"../controllers/waitlist.controller\";\nimport { authenticate } from \"../middleware/auth\";\nimport rateLimit from \"express-rate-limit\";\n\nconst router = Router();\n\nconst waitlistLimiter = rateLimit({\n  windowMs: 60 * 60 * 1000,\n  max:      100, // raise for testing, lower to 5 in production\n  message:  { success: false, message: \"Too many requests. Try again later.\" },\n  standardHeaders: true,\n  legacyHeaders:   false,\n});\n\n// Public\nrouter.post(\"/\",      waitlistLimiter, joinWaitlist);\nrouter.get( \"/stats\", getWaitlistStats);\n\n// Admin — requires login\nrouter.get(   \"/admin\",           authenticate, getWaitlistEntries);\nrouter.delete(\"/admin/:id\",       authenticate, deleteWaitlistEntry);\nrouter.post(  \"/admin/:id/resend\",authenticate, resendWaitlistEmail);\n\nexport default router;","backend/src/routes/webhook.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { createWebhook, getWebhooks, deleteWebhook, updateWebhook, testWebhook } from \"../controllers/webhook.controller\";\nconst r = Router();\nr.post(\"/:storeId\", authenticate, createWebhook);\nr.get(\"/:storeId\", authenticate, getWebhooks);\nr.delete(\"/:storeId/:webhookId\", authenticate, deleteWebhook);\nr.patch(\"/:storeId/:webhookId\", authenticate, updateWebhook);\nr.post(\"/:storeId/:webhookId/test\", authenticate, testWebhook);\nexport default r;\n","backend/src/controllers/abandonedCart.controller.ts":"// src/controllers/abandonedCart.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { emailService }        from \"../services/email.service\";\nimport { notificationService } from \"../services/notification.service\";\nimport { requireStoreOwner } from \"./store.controller\";\n\nconst cartItemSchema = z.object({\n  productId:    z.string(),\n  name:         z.string(),\n  price:        z.number(),\n  quantity:     z.number().int().positive(),\n  image:        z.string().optional(),\n  variantId:    z.string().optional(),\n  variantLabel: z.string().optional(),\n  storeId:      z.string(),\n  storeSlug:    z.string(),\n});\n\n// ── POST /api/abandoned-carts/save ───────────────────────────────────────────\n// Called by the storefront when a user has been idle 30min with items in cart\nexport const saveAbandonedCart = async (req: Request, res: Response) => {\n  const data = z.object({\n    storeId:  z.string(),\n    email:    z.string().email(),\n    name:     z.string().optional(),\n    items:    z.array(cartItemSchema).min(1),\n    total:    z.number().positive(),\n    currency: z.string().default(\"USD\"),\n  }).parse(req.body);\n\n  // Upsert — one record per (storeId, email) pair, update if re-abandoned\n  const existing = await prisma.abandonedCart.findFirst({\n    where: { storeId: data.storeId, email: data.email, recovered: false },\n  });\n\n  if (existing) {\n    // Update items/total, reset email sent so they get a fresh reminder\n    await prisma.abandonedCart.update({\n      where: { id: existing.id },\n      data: {\n        items:    data.items as any,\n        total:    data.total,\n        currency: data.currency,\n        name:     data.name,\n        emailSent: false,\n        updatedAt: new Date(),\n      },\n    });\n    return res.json({ success: true, token: existing.token });\n  }\n\n  const cart = await prisma.abandonedCart.create({\n    data: {\n      storeId:  data.storeId,\n      email:    data.email,\n      name:     data.name,\n      items:    data.items as any,\n      total:    data.total,\n      currency: data.currency,\n    },\n  });\n\n  return res.status(201).json({ success: true, token: cart.token });\n};\n\n// ── POST /api/abandoned-carts/recover/:token ─────────────────────────────────\n// Called when shopper clicks the email recovery link — marks cart recovered\nexport const recoverCart = async (req: Request, res: Response) => {\n  const cart = await prisma.abandonedCart.findUnique({\n    where: { token: req.params.token },\n    include: { store: { select: { slug: true, name: true } } },\n  });\n\n  if (!cart) throw new AppError(\"Recovery link not found\", 404);\n  if (cart.recovered) {\n    // Already recovered — still redirect them to the store\n    return res.json({ success: true, storeSlug: cart.store.slug, items: cart.items, recovered: true });\n  }\n\n  await prisma.abandonedCart.update({\n    where: { id: cart.id },\n    data:  { recovered: true, recoveredAt: new Date() },\n  });\n\n  return res.json({\n    success:   true,\n    storeSlug: cart.store.slug,\n    storeName: cart.store.name,\n    items:     cart.items,\n    total:     cart.total,\n    currency:  cart.currency,\n    recovered: false, // was not previously recovered\n  });\n};\n\n// ── POST /api/abandoned-carts/send-reminders ─────────────────────────────────\n// Called by a cron or manually from the dashboard\n// Finds all un-emailed carts older than 1h and sends recovery emails\nexport const sendAbandonedCartReminders = async (req: Request, res: Response) => {\n  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);\n\n  const carts = await prisma.abandonedCart.findMany({\n    where: {\n      recovered:  false,\n      emailSent:  false,\n      createdAt:  { lte: oneHourAgo },\n      reminderCount: { lt: 2 }, // max 2 reminder emails\n    },\n    include: {\n      store: {\n        select: { name: true, slug: true, primaryColor: true, supportEmail: true, smsEnabled: true, notifyCustomerSms: true, whatsappEnabled: true, whatsappPhone: true, smsPhone: true, owner: { select: { email: true } } },\n      },\n    },\n    take: 50, // process max 50 at a time\n  });\n\n  let sent = 0, failed = 0;\n\n  for (const cart of carts) {\n    try {\n      const recoveryUrl = `${process.env.FRONTEND_URL || \"http://localhost:3000\"}/store/${cart.store.slug}/recover/${cart.token}`;\n      const items = cart.items as any[];\n\n      await emailService.sendAbandonedCart({\n        email:       cart.email,\n        name:        cart.name || \"there\",\n        storeName:   cart.store.name,\n        storeSlug:   cart.store.slug,\n        items:       items.slice(0, 4),\n        total:       cart.total,\n        currency:    cart.currency,\n        recoveryUrl,\n        brandColor:  cart.store.primaryColor || \"#c9a84c\",\n      });\n\n      // Best-effort SMS nudge if store has customer SMS enabled\n      notificationService.notifyCustomerAbandonedCart({\n        customerPhone: null, // not captured for anonymous carts\n        smsEnabled:    false, // only fires if phone is known\n        storeName:     cart.store.name,\n        total:         cart.total,\n        currency:      cart.currency,\n        recoveryUrl,\n      });\n\n      await prisma.abandonedCart.update({\n        where: { id: cart.id },\n        data:  { emailSent: true, emailSentAt: new Date(), reminderCount: { increment: 1 } },\n      });\n      sent++;\n    } catch (err) {\n      console.error(`Failed to send abandoned cart email to ${cart.email}:`, err);\n      failed++;\n    }\n  }\n\n  return res.json({ success: true, sent, failed, processed: carts.length });\n};\n\n// ── GET /api/abandoned-carts/:storeId ────────────────────────────────────────\n// Dashboard: list abandoned carts for a store\nexport const getAbandonedCarts = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { page = 1, limit = 20, recovered } = req.query;\n  const take = Number(limit);\n  const skip = (Number(page) - 1) * take;\n\n  const where: any = { storeId };\n  if (recovered === \"true\")  where.recovered = true;\n  if (recovered === \"false\") where.recovered = false;\n\n  const [carts, total] = await Promise.all([\n    await prisma.abandonedCart.findMany({\n      where, take, skip,\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.abandonedCart.count({ where }),\n  ]);\n\n  // Compute summary stats\n  const [totalAbandoned, totalRecovered, totalRevenue] = await Promise.all([\n    await prisma.abandonedCart.count({ where: { storeId } }),\n    await prisma.abandonedCart.count({ where: { storeId, recovered: true } }),\n    await prisma.abandonedCart.aggregate({\n      where: { storeId, recovered: true },\n      _sum: { total: true },\n    }),\n  ]);\n\n  return res.json({\n    success: true,\n    data:    carts,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n    stats: {\n      totalAbandoned,\n      totalRecovered,\n      recoveryRate: totalAbandoned > 0 ? Math.round((totalRecovered / totalAbandoned) * 100) : 0,\n      recoveredRevenue: totalRevenue._sum.total || 0,\n    },\n  });\n};\n\n// ── DELETE /api/abandoned-carts/:storeId/:cartId ─────────────────────────────\nexport const deleteAbandonedCart = async (req: AuthRequest, res: Response) => {\n  const { storeId, cartId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  await prisma.abandonedCart.deleteMany({\n    where: { id: cartId, storeId },\n  });\n\n  return res.json({ success: true, message: \"Cart deleted\" });\n};\n\n// ── POST /api/abandoned-carts/:storeId/resend/:cartId ────────────────────────\n// Manually resend recovery email for a specific cart\nexport const resendRecoveryEmail = async (req: AuthRequest, res: Response) => {\n  const { storeId, cartId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const cart = await prisma.abandonedCart.findFirst({\n    where: { id: cartId, storeId },\n    include: {\n      store: { select: { name: true, slug: true, primaryColor: true } },\n    },\n  });\n\n  if (!cart) throw new AppError(\"Abandoned cart not found\", 404);\n  if (cart.recovered) throw new AppError(\"Cart already recovered\", 400);\n\n  const recoveryUrl = `${process.env.FRONTEND_URL || \"http://localhost:3000\"}/store/${cart.store.slug}/recover/${cart.token}`;\n\n  await emailService.sendAbandonedCart({\n    email:      cart.email,\n    name:       cart.name || \"there\",\n    storeName:  cart.store.name,\n    storeSlug:  cart.store.slug,\n    items:      (cart.items as any[]).slice(0, 4),\n    total:      cart.total,\n    currency:   cart.currency,\n    recoveryUrl,\n    brandColor: cart.store.primaryColor || \"#c9a84c\",\n  });\n\n  await prisma.abandonedCart.update({\n    where: { id: cart.id },\n    data:  { emailSent: true, emailSentAt: new Date(), reminderCount: { increment: 1 } },\n  });\n\n  return res.json({ success: true, message: \"Recovery email sent\" });\n};\n","backend/src/controllers/admin.controller.ts":"// src/controllers/admin.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { paginate, sanitizeUser } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport bcrypt from \"bcryptjs\";\n\n// ── Dashboard Stats ───────────────────────────────────────────────────────────\nexport const getDashboardStats = async (_req: AuthRequest, res: Response) => {\n  const [\n    totalUsers, activeUsers, suspendedUsers,\n    totalStores, activeStores,\n    totalOrders, totalRevenue, platformFees,\n    failedPayments, openTickets,\n    newUsersThisMonth, revenueThisMonth,\n  ] = await Promise.all([\n    await prisma.user.count({ where: { role: \"STORE_OWNER\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"ACTIVE\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"SUSPENDED\" } }),\n    await prisma.store.count(),\n    await prisma.store.count({ where: { status: \"ACTIVE\" } }),\n    await prisma.order.count(),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { amount: true } }),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { platformFee: true } }),\n    await prisma.payment.count({ where: { status: \"FAILED\" } }),\n    await prisma.supportTicket.count({ where: { status: { in: [\"OPEN\",\"IN_PROGRESS\"] } } }),\n    await prisma.user.count({\n      where: {\n        role: \"STORE_OWNER\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n    }),\n    await prisma.payment.aggregate({\n      where: {\n        status: \"SUCCESS\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n      _sum: { amount: true },\n    }),\n  ]);\n\n  // Monthly revenue for last 7 months\n  const months = Array.from({ length: 7 }, (_, i) => {\n    const d = new Date();\n    d.setMonth(d.getMonth() - (6 - i));\n    return new Date(d.getFullYear(), d.getMonth(), 1);\n  });\n\n  const monthlyRevenue = await Promise.all(\n    months.map(async (start) => {\n      const end = new Date(start.getFullYear(), start.getMonth() + 1, 0);\n      const agg = await prisma.payment.aggregate({\n        where: { status: \"SUCCESS\", createdAt: { gte: start, lte: end } },\n        _sum:  { amount: true, platformFee: true },\n      });\n      return {\n        month:    start.toLocaleString(\"default\", { month: \"short\" }),\n        revenue:  agg._sum.amount || 0,\n        fees:     agg._sum.platformFee || 0,\n      };\n    })\n  );\n\n  // Gateway distribution\n  const gatewayStats = await prisma.payment.groupBy({\n    by:    [\"gateway\"],\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true },\n    _count:{ id: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      users:         { total: totalUsers, active: activeUsers, suspended: suspendedUsers, newThisMonth: newUsersThisMonth },\n      stores:        { total: totalStores, active: activeStores },\n      orders:        { total: totalOrders },\n      revenue:       { total: totalRevenue._sum.amount || 0, thisMonth: revenueThisMonth._sum.amount || 0 },\n      platformFees:  { total: platformFees._sum.platformFee || 0 },\n      failedPayments,\n      openTickets,\n      monthlyRevenue,\n      gatewayStats,\n    },\n  });\n};\n\n// ── Get All Users ─────────────────────────────────────────────────────────────\nexport const getAllUsers = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, plan, search, role } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = {};\n  if (role)   where.role   = role;\n  if (status) where.status = status;\n  if (search) where.OR = [\n    { name:  { contains: search as string, mode: \"insensitive\" } },\n    { email: { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  if (plan) where.subscription = { plan };\n\n  const [users, total] = await Promise.all([\n    await prisma.user.findMany({\n      where, take, skip,\n      include: {\n        subscription: true,\n        stores: {\n          select: { id: true, name: true, status: true, _count: { select: { orders: true } } },\n        },\n        _count: { select: { stores: true, supportTickets: true } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.user.count({ where }),\n  ]);\n\n  // Attach total revenue per user\n  const usersWithRevenue = await Promise.all(\n    users.map(async (user) => {\n      const revenue = await prisma.payment.aggregate({\n        where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n        _sum:  { amount: true, platformFee: true, storeEarnings: true },\n      });\n      return {\n        ...sanitizeUser(user),\n        revenue: {\n          total:         revenue._sum.amount || 0,\n          platformFees:  revenue._sum.platformFee || 0,\n          storeEarnings: revenue._sum.storeEarnings || 0,\n        },\n      };\n    })\n  );\n\n  return res.json({\n    success: true,\n    data: usersWithRevenue,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Get Single User (full detail) ─────────────────────────────────────────────\nexport const getUserDetail = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({\n    where: { id: userId },\n    include: {\n      subscription: true,\n      stores: {\n        include: {\n          _count:  { select: { products: true, orders: true, customers: true } },\n          payments:{ where: { status: \"SUCCESS\" }, select: { amount: true, platformFee: true, storeEarnings: true } },\n        },\n      },\n      supportTickets: { orderBy: { createdAt: \"desc\" }, take: 5 },\n      _count: { select: { stores: true, supportTickets: true } },\n    },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  const totalRevenue = await prisma.payment.aggregate({\n    where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      ...sanitizeUser(user),\n      totalRevenue: totalRevenue._sum.amount     || 0,\n      platformFees: totalRevenue._sum.platformFee|| 0,\n      payouts:      totalRevenue._sum.storeEarnings || 0,\n    },\n  });\n};\n\n// ── Update User ───────────────────────────────────────────────────────────────\nexport const updateUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    name:          z.string().min(2).optional(),\n    email:         z.string().email().optional(),\n    phone:         z.string().optional(),\n    status:        z.enum([\"ACTIVE\",\"SUSPENDED\",\"BANNED\"]).optional(),\n    emailVerified: z.boolean().optional(),\n    twoFAEnabled:  z.boolean().optional(),\n    adminNotes:    z.string().optional(),\n    flags:         z.array(z.string()).optional(),\n    country:       z.string().optional(),\n    city:          z.string().optional(),\n    role:          z.enum([\"STORE_OWNER\",\"SUPER_ADMIN\"]).optional(),\n  });\n\n  const data = schema.parse(req.body);\n  const user = await prisma.user.update({ where: { id: userId }, data });\n\n  // Audit log\n  await prisma.auditLog.create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"User updated\", data: sanitizeUser(user) });\n};\n\n// ── Update Subscription ───────────────────────────────────────────────────────\nexport const updateUserSubscription = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    plan:            z.enum([\"STARTER\",\"PRO\",\"ADVANCED\"]),\n    status:          z.enum([\"ACTIVE\",\"CANCELLED\",\"EXPIRED\",\"PAST_DUE\"]).optional(),\n    currentPeriodEnd:z.string().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const sub = await prisma.subscription.update({\n    where: { userId },\n    data:  {\n      plan:   data.plan,\n      status: data.status,\n      ...(data.currentPeriodEnd && { currentPeriodEnd: new Date(data.currentPeriodEnd) }),\n    },\n    include: { user: { select: { email: true, name: true } } },\n  });\n\n  await prisma.auditLog.create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_SUBSCRIPTION\",\n      entity:   \"Subscription\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  // Send subscription email\n  try {\n    const { emailService } = await import(\"../services/email.service\");\n    const u = (sub as any).user;\n    const endDate = sub.currentPeriodEnd?.toLocaleDateString(\"en-US\", { year: \"numeric\", month: \"long\", day: \"numeric\" }) || \"N/A\";\n    if (data.status === \"ACTIVE\" || (!data.status && sub.status === \"ACTIVE\")) {\n      emailService.sendSubscriptionStarted(u.email, u.name, data.plan, endDate);\n    } else if (data.status === \"CANCELLED\") {\n      emailService.sendSubscriptionCancelled(u.email, u.name, data.plan, endDate);\n    }\n  } catch {}\n\n  return res.json({ success: true, message: \"Subscription updated\", data: sub });\n};\n\n// ── Delete User ───────────────────────────────────────────────────────────────\nexport const deleteUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({ where: { id: userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n  if (user.role === \"SUPER_ADMIN\") throw new AppError(\"Cannot delete super admin\", 403);\n\n  await prisma.user.delete({ where: { id: userId } });\n\n  await prisma.auditLog.create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"DELETE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n    },\n  });\n\n  return res.json({ success: true, message: \"User deleted\" });\n};\n\n// ── Platform Settings ─────────────────────────────────────────────────────────\nexport const getSettings = async (_req: AuthRequest, res: Response) => {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return res.json({ success: true, data: settings });\n};\n\nexport const updateSettings = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    platformFeePercent: z.number().min(0).max(50).optional(),\n    starterPrice:       z.number().optional(),\n    proPrice:           z.number().optional(),\n    advancedPrice:      z.number().optional(),\n    maintenanceMode:    z.boolean().optional(),\n    allowRegistration:  z.boolean().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const settings = await prisma.platformSettings.update({\n    where: { id: \"singleton\" },\n    data,\n  });\n\n  await prisma.auditLog.create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_PLATFORM_SETTINGS\",\n      entity:   \"PlatformSettings\",\n      entityId: \"singleton\",\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"Settings updated\", data: settings });\n};\n\n// ── Error Logs ────────────────────────────────────────────────────────────────\nexport const getErrorLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, resolved } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (resolved !== undefined) where.resolved = resolved === \"true\";\n\n  const [logs, total] = await Promise.all([\n    await prisma.errorLog.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.errorLog.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\nexport const resolveErrorLog = async (req: AuthRequest, res: Response) => {\n  const { logId } = req.params;\n  await prisma.errorLog.update({ where: { id: logId }, data: { resolved: true } });\n  return res.json({ success: true, message: \"Log resolved\" });\n};\n\n// ── Audit Logs ────────────────────────────────────────────────────────────────\nexport const getAuditLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const [logs, total] = await Promise.all([\n    await prisma.auditLog.findMany({\n      take, skip,\n      include: { user: { select: { name: true, email: true } } },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.auditLog.count(),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Platform Analytics ────────────────────────────────────────────────────────\nexport const getPlatformAnalytics = async (req: AuthRequest, res: Response) => {\n  const { period = \"7d\" } = req.query;\n  const days = period === \"30d\" ? 30 : period === \"90d\" ? 90 : 7;\n  const from = new Date();\n  from.setDate(from.getDate() - days);\n\n  const [revenueByDay, ordersByDay, newUsersByDay] = await Promise.all([\n    prisma.payment.groupBy({\n      by: [\"createdAt\"],\n      where: { status: \"SUCCESS\", createdAt: { gte: from } },\n      _sum: { amount: true, platformFee: true },\n    }),\n    prisma.order.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from } },\n      _count: { id: true },\n    }),\n    prisma.user.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from }, role: \"STORE_OWNER\" },\n      _count: { id: true },\n    }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: { revenueByDay, ordersByDay, newUsersByDay },\n  });\n};\n","backend/src/controllers/apiKey.controller.ts":"// src/controllers/apiKey.controller.ts\nimport { Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport crypto from \"crypto\";\n\nconst PERMISSIONS = [\"orders:read\",\"orders:write\",\"products:read\",\"products:write\",\"customers:read\",\"analytics:read\",\"webhooks:write\"];\n\nconst createSchema = z.object({\n  name: z.string().min(1).max(60),\n  permissions: z.array(z.enum(PERMISSIONS as [string,...string[]])).min(1),\n  expiresAt: z.string().datetime().optional(),\n});\n\nfunction hashKey(key: string) { return crypto.createHash(\"sha256\").update(key).digest(\"hex\"); }\n\n// POST /api-keys/:storeId\nexport const createApiKey = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const data = createSchema.parse(req.body);\n\n  // Check existing key count\n  const count = await prisma.apiKey.count({ where: { storeId, isActive: true } });\n  if (count >= 10) throw new AppError(\"Maximum 10 active API keys per store\", 400);\n\n  const rawKey = `dropos_${storeId.slice(0,8)}_${crypto.randomBytes(24).toString(\"hex\")}`;\n  const keyHash = hashKey(rawKey);\n  const keyPrefix = rawKey.slice(0, 16);\n\n  const apiKey = await prisma.apiKey.create({\n    data: {\n      storeId, name: data.name, keyHash, keyPrefix,\n      permissions: data.permissions,\n      expiresAt: data.expiresAt ? new Date(data.expiresAt) : null,\n    },\n    select: { id: true, name: true, keyPrefix: true, permissions: true, isActive: true, expiresAt: true, createdAt: true },\n  });\n\n  // Return raw key ONLY on creation — never stored\n  res.status(201).json({ success: true, data: { ...apiKey, key: rawKey, warning: \"Store this key securely — it will not be shown again.\" } });\n};\n\n// GET /api-keys/:storeId\nexport const getApiKeys = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const keys = await prisma.apiKey.findMany({\n    where: { storeId },\n    select: { id: true, name: true, keyPrefix: true, permissions: true, isActive: true, lastUsedAt: true, expiresAt: true, createdAt: true },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  res.json({ success: true, data: keys });\n};\n\n// DELETE /api-keys/:storeId/:keyId\nexport const revokeApiKey = async (req: AuthRequest, res: Response) => {\n  const { storeId, keyId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const key = await prisma.apiKey.findFirst({ where: { id: keyId, storeId } });\n  if (!key) throw new AppError(\"API key not found\", 404);\n\n  await prisma.apiKey.update({ where: { id: keyId }, data: { isActive: false } });\n  res.json({ success: true, message: \"API key revoked\" });\n};\n\n// PATCH /api-keys/:storeId/:keyId\nexport const updateApiKey = async (req: AuthRequest, res: Response) => {\n  const { storeId, keyId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const { name, permissions } = req.body;\n  const updated = await prisma.apiKey.update({\n    where: { id: keyId },\n    data: { name, permissions },\n    select: { id: true, name: true, keyPrefix: true, permissions: true, isActive: true, expiresAt: true },\n  });\n\n  res.json({ success: true, data: updated });\n};\n\n// GET /api-keys/permissions  — list available permissions\nexport const listPermissions = async (_req: AuthRequest, res: Response) => {\n  res.json({ success: true, data: PERMISSIONS });\n};\n\nasync function verifyOwner(storeId: string, userId: string) {\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n}\n","backend/src/controllers/auth.controller.ts":"// src/controllers/auth.controller.ts\nimport { Request, Response } from \"express\";\nimport bcrypt from \"bcryptjs\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport {\n  signAccessToken, signRefreshToken, verifyRefreshToken,\n  setRefreshCookie, clearRefreshCookie\n} from \"../config/jwt\";\nimport { AppError } from \"../utils/AppError\";\nimport { generateToken, sanitizeUser } from \"../utils/helpers\";\nimport { emailService } from \"../services/email.service\";\nimport { AuthRequest } from \"../middleware/auth\";\n\n// ── Schemas ──────────────────────────────────────────────────────────────────\nconst registerSchema = z.object({\n  name:     z.string().min(2).max(100),\n  email:    z.string().email(),\n  password: z.string().min(8).regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)/, {\n    message: \"Password must contain uppercase, lowercase, and number\",\n  }),\n  phone:    z.string().optional(),\n  country:  z.string().optional(),\n});\n\nconst loginSchema = z.object({\n  email:    z.string().email(),\n  password: z.string().min(1),\n});\n\n// ── Register ─────────────────────────────────────────────────────────────────\nexport const register = async (req: Request, res: Response) => {\n  const body = registerSchema.parse(req.body);\n\n  // Check platform allows registration\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  if (settings && !settings.allowRegistration) {\n    throw new AppError(\"Registration is currently disabled\", 403);\n  }\n\n  // Check existing user\n  const existing = await prisma.user.findUnique({ where: { email: body.email } });\n  if (existing) throw new AppError(\"Email already registered\", 409);\n\n  // Hash password\n  const password = await bcrypt.hash(body.password, 12);\n  const verifyToken = generateToken();\n\n  // Create user\n  const user = await prisma.user.create({\n    data: {\n      email:            body.email,\n      password,\n      name:             body.name,\n      phone:            body.phone,\n      country:          body.country,\n      role:             \"STORE_OWNER\",\n      status:           \"ACTIVE\",\n      emailVerified:    true,\n      emailVerifyToken: verifyToken,\n    },\n  });\n\n  // Create default Starter subscription\n  const now = new Date();\n  const trialEnd = new Date(now);\n  trialEnd.setDate(trialEnd.getDate() + 14); // 14-day trial\n  await prisma.subscription.create({\n    data: {\n      userId:             user.id,\n      plan:               \"STARTER\",\n      status:             \"ACTIVE\",\n      price:              9,\n      currentPeriodStart: now,\n      currentPeriodEnd:   trialEnd,\n    },\n  });\n\n  // Send verification email\n  await emailService.sendVerificationEmail(user.email, user.name, verifyToken);\n\n  return res.status(201).json({\n    success: true,\n    message: \"Registration successful. Please check your email to verify your account.\",\n    data: { id: user.id, email: user.email, name: user.name },\n  });\n};\n\n// ── Verify Email ─────────────────────────────────────────────────────────────\nexport const verifyEmail = async (req: Request, res: Response) => {\n  const { token } = req.params;\n  const user = await prisma.user.findFirst({ where: { emailVerifyToken: token } });\n  if (!user) throw new AppError(\"Invalid or expired verification link\", 400);\n\n  await prisma.user.update({\n    where: { id: user.id },\n    data: { emailVerified: true, status: \"ACTIVE\", emailVerifyToken: null },\n  });\n\n  // Send welcome email now that they're verified\n  emailService.sendWelcomeEmail(user.email, user.name);\n\n  return res.json({ success: true, message: \"Email verified. You can now log in.\" });\n};\n\n// ── Login ─────────────────────────────────────────────────────────────────────\nexport const login = async (req: Request, res: Response) => {\n  const { email, password } = loginSchema.parse(req.body);\n\n  const user = await prisma.user.findUnique({\n    where: { email },\n    include: {\n      subscription: true,\n      stores: { select: { id: true, name: true, slug: true, status: true } },\n    },\n  });\n  if (!user) throw new AppError(\"Invalid email or password\", 401);\n\n  // Check lock\n  if (user.lockedUntil && user.lockedUntil > new Date()) {\n    throw new AppError(`Account locked until ${user.lockedUntil.toISOString()}`, 423);\n  }\n\n  // Check password\n  const valid = await bcrypt.compare(password, user.password);\n  if (!valid) {\n    const attempts = user.loginAttempts + 1;\n    const lockData = attempts >= 5\n      ? { loginAttempts: 0, lockedUntil: new Date(Date.now() + 15 * 60 * 1000) }\n      : { loginAttempts: attempts };\n    await prisma.user.update({ where: { id: user.id }, data: lockData });\n    throw new AppError(\"Invalid email or password\", 401);\n  }\n\n  // Check status\n  if (user.status === \"PENDING_VERIFICATION\") {\n    throw new AppError(\"Please verify your email before logging in\", 403);\n  }\n  if (user.status === \"SUSPENDED\") throw new AppError(\"Account suspended\", 403);\n  if (user.status === \"BANNED\")    throw new AppError(\"Account banned\", 403);\n\n  // Issue tokens\n  const payload = { userId: user.id, email: user.email, role: user.role };\n  const accessToken  = signAccessToken(payload);\n  const refreshToken = signRefreshToken(payload);\n\n  // Save refresh token & update login\n  await prisma.user.update({\n    where: { id: user.id },\n    data: { refreshToken, loginAttempts: 0, lockedUntil: null, lastLogin: new Date() },\n  });\n\n  setRefreshCookie(res, refreshToken);\n\n  return res.json({\n    success: true,\n    message: \"Login successful\",\n    data: {\n      accessToken,\n      refreshToken,\n      user: sanitizeUser(user),\n    },\n  });\n};\n\n// ── Refresh Token ─────────────────────────────────────────────────────────────\nexport const refreshToken = async (req: Request, res: Response) => {\n  const token = req.cookies?.refresh_token || req.body?.refreshToken;\n  if (!token) throw new AppError(\"No refresh token\", 401);\n\n  const payload = verifyRefreshToken(token);\n\n  const user = await prisma.user.findUnique({ where: { id: payload.userId } });\n  if (!user || user.refreshToken !== token) throw new AppError(\"Invalid refresh token\", 401);\n\n  const newPayload      = { userId: user.id, email: user.email, role: user.role };\n  const newAccessToken  = signAccessToken(newPayload);\n  const newRefreshToken = signRefreshToken(newPayload);\n\n  await prisma.user.update({ where: { id: user.id }, data: { refreshToken: newRefreshToken } });\n  setRefreshCookie(res, newRefreshToken);\n\n  return res.json({\n    success: true,\n    data: { accessToken: newAccessToken },\n  });\n};\n\n// ── Logout ────────────────────────────────────────────────────────────────────\nexport const logout = async (req: AuthRequest, res: Response) => {\n  if (req.user?.userId) {\n    await prisma.user.update({\n      where: { id: req.user.userId },\n      data:  { refreshToken: null },\n    });\n  }\n  clearRefreshCookie(res);\n  return res.json({ success: true, message: \"Logged out successfully\" });\n};\n\n// ── Get Me ────────────────────────────────────────────────────────────────────\nexport const getMe = async (req: AuthRequest, res: Response) => {\n  const user = await prisma.user.findUnique({\n    where: { id: req.user!.userId },\n    include: {\n      subscription: true,\n      stores: { select: { id: true, name: true, slug: true, status: true } },\n    },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n  return res.json({ success: true, data: sanitizeUser(user) });\n};\n\n// ── Forgot Password ───────────────────────────────────────────────────────────\nexport const forgotPassword = async (req: Request, res: Response) => {\n  const { email } = z.object({ email: z.string().email() }).parse(req.body);\n  const user = await prisma.user.findUnique({ where: { email } });\n\n  // Always return 200 to prevent email enumeration\n  if (!user) return res.json({ success: true, message: \"If that email exists, a reset link was sent.\" });\n\n  const resetToken  = generateToken();\n  const resetExpiry = new Date(Date.now() + 60 * 60 * 1000); // 1 hour\n\n  await prisma.user.update({\n    where: { id: user.id },\n    data:  { passwordResetToken: resetToken, passwordResetExpiry: resetExpiry },\n  });\n\n  await emailService.sendPasswordReset(user.email, user.name, resetToken);\n  return res.json({ success: true, message: \"If that email exists, a reset link was sent.\" });\n};\n\n// ── Reset Password ────────────────────────────────────────────────────────────\nexport const resetPassword = async (req: Request, res: Response) => {\n  const schema = z.object({\n    token:    z.string(),\n    password: z.string().min(8).regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)/),\n  });\n  const { token, password } = schema.parse(req.body);\n\n  const user = await prisma.user.findFirst({\n    where: {\n      passwordResetToken:  token,\n      passwordResetExpiry: { gt: new Date() },\n    },\n  });\n  if (!user) throw new AppError(\"Invalid or expired reset token\", 400);\n\n  const hashed = await bcrypt.hash(password, 12);\n  await prisma.user.update({\n    where: { id: user.id },\n    data:  { password: hashed, passwordResetToken: null, passwordResetExpiry: null },\n  });\n\n  return res.json({ success: true, message: \"Password reset successfully\" });\n};\n\n// ── Update Profile ────────────────────────────────────────────────────────────\nexport const updateProfile = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    name:     z.string().min(2).max(100).optional(),\n    phone:    z.string().optional(),\n    country:  z.string().optional(),\n    city:     z.string().optional(),\n    timezone: z.string().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const user = await prisma.user.update({\n    where: { id: req.user!.userId },\n    data,\n  });\n  return res.json({ success: true, message: \"Profile updated\", data: sanitizeUser(user) });\n};\n\n// ── Change Password ───────────────────────────────────────────────────────────\nexport const changePassword = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    currentPassword: z.string(),\n    newPassword:     z.string().min(8).regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)/),\n  });\n  const { currentPassword, newPassword } = schema.parse(req.body);\n\n  const user = await prisma.user.findUnique({ where: { id: req.user!.userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  const valid = await bcrypt.compare(currentPassword, user.password);\n  if (!valid) throw new AppError(\"Current password is incorrect\", 400);\n\n  const hashed = await bcrypt.hash(newPassword, 12);\n  await prisma.user.update({ where: { id: user.id }, data: { password: hashed } });\n\n  return res.json({ success: true, message: \"Password changed successfully\" });\n};","backend/src/controllers/customerAccount.controller.ts":"// src/controllers/customerAccount.controller.ts\nimport { Request, Response } from \"express\";\nimport { CustomerAuthRequest } from \"../middleware/customerAuth\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport bcrypt from \"bcryptjs\";\nimport jwt from \"jsonwebtoken\";\nimport { emailService } from \"../services/email.service\";\nimport crypto from \"crypto\";\n\nconst registerSchema = z.object({\n  storeId:  z.string().uuid(),\n  email:    z.string().email(),\n  name:     z.string().min(2),\n  phone:    z.string().optional(),\n  password: z.string().min(8),\n});\n\nconst loginSchema = z.object({\n  storeId:  z.string().uuid(),\n  email:    z.string().email(),\n  password: z.string(),\n});\n\nconst JWT_SECRET = process.env.JWT_SECRET || \"secret\";\n\nfunction signToken(id: string, storeId: string) {\n  return jwt.sign({ id, storeId, type: \"customer\" }, JWT_SECRET, { expiresIn: \"7d\" });\n}\n\n// POST /customer-auth/register\nexport const registerCustomer = async (req: Request, res: Response) => {\n  const data = registerSchema.parse(req.body);\n\n  const store = await prisma.store.findFirst({ where: { id: data.storeId, status: \"ACTIVE\" } });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  const existing = await prisma.customerAccount.findUnique({ where: { storeId_email: { storeId: data.storeId, email: data.email } } });\n  if (existing) throw new AppError(\"An account with this email already exists\", 409);\n\n  const passwordHash = await bcrypt.hash(data.password, 12);\n  const verifyToken = crypto.randomBytes(32).toString(\"hex\");\n\n  const account = await prisma.customerAccount.create({\n    data: { storeId: data.storeId, email: data.email, name: data.name, phone: data.phone, passwordHash, verifyToken },\n    select: { id: true, email: true, name: true, emailVerified: true, createdAt: true },\n  });\n\n  await emailService.send({\n    to: data.email,\n    subject: `Verify your ${store.name} account`,\n    html: `<p>Hi ${data.name}, welcome to ${store.name}!</p><p><a href=\"${process.env.STOREFRONT_URL}/store/${store.slug}/verify-email?token=${verifyToken}\">Verify your email</a></p>`,\n  });\n\n  const token = signToken(account.id, data.storeId);\n  res.status(201).json({ success: true, data: { account, token } });\n};\n\n// POST /customer-auth/login\nexport const loginCustomer = async (req: Request, res: Response) => {\n  const data = loginSchema.parse(req.body);\n\n  const account = await prisma.customerAccount.findUnique({ where: { storeId_email: { storeId: data.storeId, email: data.email } } });\n  if (!account) throw new AppError(\"Invalid credentials\", 401);\n\n  const valid = await bcrypt.compare(data.password, account.passwordHash);\n  if (!valid) throw new AppError(\"Invalid credentials\", 401);\n\n  // Get order history\n  const orders = await prisma.order.findMany({\n    where: { storeId: data.storeId, customerEmail: data.email },\n    orderBy: { createdAt: \"desc\" }, take: 20,\n    select: { id: true, orderNumber: true, status: true, total: true, createdAt: true, items: { select: { name: true, quantity: true } } },\n  });\n\n  const token = signToken(account.id, data.storeId);\n  res.json({ success: true, data: { account: { id: account.id, email: account.email, name: account.name, emailVerified: account.emailVerified, defaultAddress: account.defaultAddress, wishlist: account.wishlist }, token, orders } });\n};\n\n// GET /customer-auth/profile — requires customer JWT\nexport const getCustomerProfile = async (req: CustomerAuthRequest, res: Response) => {\n  const { accountId, storeId } = req.customer!;\n  const account = await prisma.customerAccount.findUnique({\n    where: { id: accountId },\n    select: { id: true, email: true, name: true, phone: true, emailVerified: true, defaultAddress: true, savedAddresses: true, wishlist: true, createdAt: true },\n  });\n  if (!account) throw new AppError(\"Account not found\", 404);\n\n  const orders = await prisma.order.findMany({\n    where: { storeId, customerEmail: account.email },\n    orderBy: { createdAt: \"desc\" }, take: 50,\n    select: { id: true, orderNumber: true, status: true, total: true, createdAt: true, trackingNumber: true, items: { select: { name: true, quantity: true, price: true, image: true } } },\n  });\n\n  res.json({ success: true, data: { account, orders } });\n};\n\n// PATCH /customer-auth/profile\nexport const updateCustomerProfile = async (req: CustomerAuthRequest, res: Response) => {\n  const { accountId } = req.customer!;\n  const { name, phone, defaultAddress, savedAddresses } = req.body;\n\n  const updated = await prisma.customerAccount.update({\n    where: { id: accountId },\n    data: { name, phone, defaultAddress, savedAddresses },\n    select: { id: true, email: true, name: true, phone: true, defaultAddress: true, savedAddresses: true },\n  });\n\n  res.json({ success: true, data: updated });\n};\n\n// POST /customer-auth/wishlist/toggle\nexport const toggleWishlist = async (req: CustomerAuthRequest, res: Response) => {\n  const { accountId } = req.customer!;\n  const { productId } = req.body;\n  if (!productId) throw new AppError(\"productId required\", 400);\n\n  const account = await prisma.customerAccount.findUnique({ where: { id: accountId }, select: { wishlist: true } });\n  if (!account) throw new AppError(\"Not found\", 404);\n\n  const inList = account.wishlist.includes(productId);\n  const wishlist = inList ? account.wishlist.filter(id => id !== productId) : [...account.wishlist, productId];\n\n  await prisma.customerAccount.update({ where: { id: accountId }, data: { wishlist } });\n\n  res.json({ success: true, data: { wishlist, added: !inList } });\n};\n\n// GET /customer-auth/wishlist\nexport const getWishlist = async (req: CustomerAuthRequest, res: Response) => {\n  const { accountId, storeId } = req.customer!;\n  const account = await prisma.customerAccount.findUnique({ where: { id: accountId }, select: { wishlist: true } });\n  if (!account) throw new AppError(\"Not found\", 404);\n\n  const products = account.wishlist.length > 0\n    ? await prisma.product.findMany({ where: { id: { in: account.wishlist }, storeId, status: \"ACTIVE\" }, select: { id: true, name: true, price: true, comparePrice: true, images: true, slug: true } })\n    : [];\n\n  res.json({ success: true, data: products });\n};\n\n// POST /customer-auth/forgot-password\nexport const customerForgotPassword = async (req: Request, res: Response) => {\n  const { storeId, email } = req.body;\n  const account = await prisma.customerAccount.findUnique({ where: { storeId_email: { storeId, email } } });\n\n  // Always respond 200 (security)\n  if (!account) return res.json({ success: true, message: \"If that email exists, a reset link was sent.\" });\n\n  const token = crypto.randomBytes(32).toString(\"hex\");\n  await prisma.customerAccount.update({ where: { id: account.id }, data: { resetToken: token, resetExpiry: new Date(Date.now() + 3600000) } });\n\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { slug: true, name: true } });\n  await emailService.send({\n    to: email, subject: \"Reset your password\",\n    html: `<p>Click to reset: <a href=\"${process.env.STOREFRONT_URL}/store/${store!.slug}/reset-password?token=${token}\">Reset Password</a></p><p>Link expires in 1 hour.</p>`,\n  });\n\n  res.json({ success: true, message: \"If that email exists, a reset link was sent.\" });\n};\n","backend/src/controllers/features.controller.ts":"// ============================================================\n// DropOS — Priority 1-3 Features Controller\n// Path: backend/src/controllers/features.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  calculateHealthScore, gradeProducts, getAtRiskCustomers,\n  getStoreAchievements, getRevenueReplay, getWeeklyWinners,\n  createPriceTest,\n} from \"../services/features.service\";\n\nconst prisma = new PrismaClient();\n\n// ── GET /api/features/health/:storeId ─────────────────────────\nexport async function healthScore(req: Request, res: Response) {\n  try {\n    const data = await calculateHealthScore(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/product-grades/:storeId ─────────────────\nexport async function productGrades(req: Request, res: Response) {\n  try {\n    const data = await gradeProducts(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/at-risk/:storeId ────────────────────────\nexport async function atRiskCustomers(req: Request, res: Response) {\n  try {\n    const data = await getAtRiskCustomers(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/achievements/:storeId ───────────────────\nexport async function achievements(req: Request, res: Response) {\n  try {\n    const data = await getStoreAchievements(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/replay/:storeId ─────────────────────────\nexport async function revenueReplay(req: Request, res: Response) {\n  try {\n    const data = await getRevenueReplay(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/weekly-winners/:storeId ─────────────────\nexport async function weeklyWinners(req: Request, res: Response) {\n  try {\n    const data = await getWeeklyWinners(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/features/price-test ────────────────────────────\nexport async function priceTest(req: Request, res: Response) {\n  try {\n    const { storeId, productId, priceA, priceB } = req.body;\n    if (!storeId || !productId || !priceA || !priceB)\n      return res.status(400).json({ success: false, message: \"storeId, productId, priceA, priceB required\" });\n    const data = await createPriceTest(storeId, productId, Number(priceA), Number(priceB));\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/live-sales/:storeId ────────────────────\n// Returns the last 10 orders for the live ticker\nexport async function liveSales(req: Request, res: Response) {\n  try {\n    const { storeId } = req.params;\n    const orders = await prisma.order.findMany({\n      where: { storeId, status: { in: [\"PAID\", \"SHIPPED\", \"DELIVERED\"] } },\n      orderBy: { createdAt: \"desc\" },\n      take: 10,\n      include: {\n        customer: { select: { name: true, city: true } },\n        items: { take: 1, include: { product: { select: { name: true } } } },\n      },\n    });\n\n    const feed = orders.map(o => ({\n      id: o.id,\n      customerName: o.customer?.name?.split(\" \")[0] || \"Someone\",\n      city: o.customer?.city || \"Nigeria\",\n      productName: o.items[0]?.product?.name || \"a product\",\n      amount: Number(o.total),\n      createdAt: o.createdAt,\n      minutesAgo: Math.round((Date.now() - new Date(o.createdAt).getTime()) / 60000),\n    }));\n\n    res.json({ success: true, data: feed });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/features/send-comeback ─────────────────────────\n// Send win-back WhatsApp message to at-risk customer\nexport async function sendComeback(req: Request, res: Response) {\n  try {\n    const { customerId, message, storeId } = req.body;\n    // Store the intent — actual WhatsApp sending handled by WhatsApp service\n    await prisma.customer.update({\n      where: { id: customerId },\n      data: { notes: `Win-back sent ${new Date().toLocaleDateString()}` } as any,\n    });\n    res.json({ success: true, message: \"Win-back message queued\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/store-setup-status ─────────────────────\n// Check what's needed for 5-min store setup\nexport async function setupStatus(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    const [store, products, shipping] = await Promise.all([\n      prisma.store.findUnique({\n        where: { id: storeId },\n        select: { name: true, logo: true, description: true, country: true, currency: true },\n      }),\n      prisma.product.count({ where: { storeId } }),\n      prisma.shippingZone?.count({ where: { storeId } }).catch(() => 0),\n    ]);\n\n    const steps = [\n      { id: \"store_info\",  label: \"Store info\",        done: !!(store?.name && store?.description) },\n      { id: \"logo\",        label: \"Store logo\",        done: !!store?.logo },\n      { id: \"products\",    label: \"Add products\",      done: products >= 3 },\n      { id: \"shipping\",    label: \"Set up shipping\",   done: (shipping || 0) >= 1 },\n      { id: \"payment\",     label: \"Connect payment\",   done: true }, // assume Paystack connected on signup\n    ];\n\n    const percent = Math.round((steps.filter(s => s.done).length / steps.length) * 100);\n    res.json({ success: true, data: { steps, percent, isComplete: percent === 100 } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n","backend/src/controllers/fulfillment.controller.ts":"// ============================================================\n// Fulfillment Controller + Routes\n// Path: backend/src/controllers/fulfillment.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { Router }            from \"express\";\nimport { authenticate }      from \"../middleware/auth\";\nimport prisma                from \"../lib/prisma\";\n\nasync function getIntegrationStatus(req: Request, res: Response) {\n  try {\n    const { storeId } = req.params;\n    const integrations = await (prisma as any).storeIntegration.findMany({\n      where: { storeId },\n    }).catch(() => []);\n    const cj     = integrations.find((i: any) => i.provider === \"cjdropshipping\" && i.isActive);\n    const autods = integrations.find((i: any) => i.provider === \"autods\" && i.isActive);\n    res.json({\n      success: true,\n      data: {\n        cj:     { connected: !!cj,     email: cj?.email || null, connectedAt: cj?.createdAt || null },\n        autods: { connected: !!autods, approved: false, message: autods ? \"API key saved\" : \"Not connected\" },\n      },\n    });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nasync function connectCJ(req: Request, res: Response) {\n  try {\n    const { storeId, email, password } = req.body;\n    if (!email || !password) return res.status(400).json({ success: false, message: \"Email and password required\" });\n    let token = \"\", expiresAt = new Date(Date.now() + 3600000);\n    try {\n      const r: any = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/authentication/getAccessToken\", {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ email, password }),\n      });\n      const d: any = await r.json();\n      if (d.code !== 200 || !d.data?.accessToken)\n        return res.json({ success: false, message: \"Invalid CJ credentials\" });\n      token = d.data.accessToken;\n      expiresAt = new Date(Date.now() + (d.data.expiresIn || 3600) * 1000);\n    } catch { return res.json({ success: false, message: \"Could not reach CJDropshipping\" }); }\n    await (prisma as any).storeIntegration.upsert({\n      where:  { storeId_provider: { storeId, provider: \"cjdropshipping\" } },\n      create: { storeId, provider: \"cjdropshipping\", email, password, accessToken: token, expiresAt, isActive: true },\n      update: { email, password, accessToken: token, expiresAt, isActive: true },\n    });\n    res.json({ success: true, message: \"CJDropshipping connected! Autopilot is now active.\" });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nasync function connectADS(req: Request, res: Response) {\n  try {\n    const { storeId, apiKey } = req.body;\n    if (!apiKey) return res.status(400).json({ success: false, message: \"API key required\" });\n    await (prisma as any).storeIntegration.upsert({\n      where:  { storeId_provider: { storeId, provider: \"autods\" } },\n      create: { storeId, provider: \"autods\", accessToken: apiKey, isActive: true },\n      update: { accessToken: apiKey, isActive: true },\n    });\n    res.json({ success: true, message: \"AutoDS API key saved.\" });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nasync function triggerAutoFulfill(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    const integration = await (prisma as any).storeIntegration.findFirst({\n      where: { storeId, provider: \"cjdropshipping\", isActive: true },\n    }).catch(() => null);\n    if (!integration) return res.json({ success: true, data: { fulfilled: 0, failed: 0, skipped: 0, message: \"No CJ account connected\" } });\n    const pendingOrders = await prisma.$queryRaw`SELECT id FROM \"Order\" WHERE \"storeId\" = ${storeId} AND status = 'PAID' LIMIT 20`.catch(() => []) as any[];\n    res.json({ success: true, data: { fulfilled: 0, failed: 0, skipped: pendingOrders.length, message: `${pendingOrders.length} orders queued` } });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nasync function syncTracking(req: Request, res: Response) {\n  res.json({ success: true, message: \"Tracking sync initiated\" });\n}\n\nasync function disconnectIntegration(req: Request, res: Response) {\n  try {\n    const { storeId, provider } = req.body;\n    await (prisma as any).storeIntegration.updateMany({ where: { storeId, provider }, data: { isActive: false } }).catch(() => {});\n    res.json({ success: true, message: `${provider} disconnected` });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nconst router = Router();\nrouter.use(authenticate);\nrouter.get (\"/status/:storeId\",        getIntegrationStatus);\nrouter.post(\"/connect/cj\",             connectCJ);\nrouter.post(\"/connect/autods\",         connectADS);\nrouter.post(\"/fulfill-now\",            triggerAutoFulfill);\nrouter.post(\"/sync-tracking/:storeId\", syncTracking);\nrouter.post(\"/disconnect\",             disconnectIntegration);\nexport default router;","backend/src/controllers/funnel.controller.ts":"// src/controllers/funnel.controller.ts\nimport { Request, Response } from \"express\";\nimport prisma from \"../lib/prisma\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { AppError } from \"../utils/AppError\";\n\n// POST /funnel/event  — public, called from storefront JS\nexport const trackFunnelEvent = async (req: Request, res: Response) => {\n  const { storeId, sessionId, event, productId, orderId, value, meta } = req.body;\n  if (!storeId || !sessionId || !event) return res.json({ success: true }); // silent\n\n  const validEvents = [\"view\", \"add_to_cart\", \"checkout_start\", \"purchase\"];\n  if (!validEvents.includes(event)) return res.json({ success: true });\n\n  await prisma.funnelEvent.create({\n    data: {\n      storeId, sessionId, event, productId, orderId, value,\n      meta: meta || null,\n      ip: req.ip,\n      userAgent: req.headers[\"user-agent\"] || null,\n    },\n  }).catch(() => {}); // non-blocking\n\n  res.json({ success: true });\n};\n\n// POST /funnel/utm  — track UTM session\nexport const trackUtmSession = async (req: Request, res: Response) => {\n  const { storeId, sessionId, source, medium, campaign, term, content, landingPage, referrer } = req.body;\n  if (!storeId || !sessionId) return res.json({ success: true });\n\n  await prisma.utmSession.upsert({\n    where: { storeId_sessionId: { storeId, sessionId } },\n    update: {}, // don't overwrite existing UTM data for this session\n    create: { storeId, sessionId, source, medium, campaign, term, content, landingPage, referrer },\n  }).catch(() => {}); // ignore duplicate race conditions\n\n  res.json({ success: true });\n};\n\n// GET /funnel/:storeId  — funnel analytics for owner dashboard\nexport const getFunnelAnalytics = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const { period = \"30d\" } = req.query as any;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const days = period === \"7d\" ? 7 : period === \"90d\" ? 90 : 30;\n  const since = new Date(Date.now() - days * 86400000);\n\n  const events = await prisma.funnelEvent.groupBy({\n    by: [\"event\"], where: { storeId, createdAt: { gte: since } },\n    _count: { event: true },\n  });\n\n  const map: Record<string, number> = {};\n  events.forEach(e => { map[e.event] = e._count.event; });\n\n  const funnel = [\n    { stage: \"Product Views\",      count: map[\"view\"] || 0 },\n    { stage: \"Add to Cart\",        count: map[\"add_to_cart\"] || 0 },\n    { stage: \"Checkout Started\",   count: map[\"checkout_start\"] || 0 },\n    { stage: \"Purchase Completed\", count: map[\"purchase\"] || 0 },\n  ];\n\n  // Conversion rates\n  const enriched = funnel.map((f, i) => ({\n    ...f,\n    rate: i === 0 ? 100 : funnel[0].count > 0 ? +((f.count / funnel[0].count) * 100).toFixed(1) : 0,\n    dropOff: i === 0 ? 0 : funnel[i-1].count > 0 ? +(((funnel[i-1].count - f.count) / funnel[i-1].count) * 100).toFixed(1) : 0,\n  }));\n\n  // Traffic sources\n  const sources = await prisma.utmSession.groupBy({\n    by: [\"source\"], where: { storeId, createdAt: { gte: since } },\n    _count: { source: true },\n    orderBy: { _count: { source: \"desc\" } },\n  });\n\n  // Top converting UTM campaigns\n  const campaigns = await prisma.utmSession.groupBy({\n    by: [\"campaign\", \"source\", \"medium\"],\n    where: { storeId, createdAt: { gte: since }, campaign: { not: null } },\n    _count: { campaign: true },\n    _sum: { orderValue: true },\n    orderBy: { _sum: { orderValue: \"desc\" } },\n    take: 10,\n  });\n\n  res.json({ success: true, data: { funnel: enriched, sources: sources.map(s => ({ source: s.source || \"direct\", count: s._count.source })), campaigns } });\n};\n\n// GET /funnel/:storeId/cohort\nexport const getCohortAnalytics = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  // Get last 6 months of orders grouped by customer + month\n  const sixMonthsAgo = new Date();\n  sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);\n\n  const orders = await prisma.order.findMany({\n    where: { storeId, createdAt: { gte: sixMonthsAgo }, status: { in: [\"COMPLETED\",\"DELIVERED\"] } },\n    select: { customerEmail: true, createdAt: true, total: true },\n    orderBy: { createdAt: \"asc\" },\n  });\n\n  // Build cohort map: first purchase month → return rates\n  const firstPurchase: Record<string, Date> = {};\n  const cohorts: Record<string, { total: number; d30: number; d60: number; d90: number }> = {};\n\n  orders.forEach(o => {\n    if (!firstPurchase[o.customerEmail]) firstPurchase[o.customerEmail] = o.createdAt;\n  });\n\n  orders.forEach(o => {\n    const first = firstPurchase[o.customerEmail];\n    const month = `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,\"0\")}`;\n    if (!cohorts[month]) cohorts[month] = { total: 0, d30: 0, d60: 0, d90: 0 };\n    if (o.createdAt.getTime() === first.getTime()) { cohorts[month].total++; return; }\n    const diff = (o.createdAt.getTime() - first.getTime()) / 86400000;\n    if (diff <= 30) cohorts[month].d30++;\n    else if (diff <= 60) cohorts[month].d60++;\n    else if (diff <= 90) cohorts[month].d90++;\n  });\n\n  const result = Object.entries(cohorts).map(([month, data]) => ({\n    month,\n    totalCustomers: data.total,\n    day30Rate: data.total > 0 ? +((data.d30 / data.total) * 100).toFixed(1) : 0,\n    day60Rate: data.total > 0 ? +((data.d60 / data.total) * 100).toFixed(1) : 0,\n    day90Rate: data.total > 0 ? +((data.d90 / data.total) * 100).toFixed(1) : 0,\n  })).sort((a,b) => a.month.localeCompare(b.month));\n\n  res.json({ success: true, data: result });\n};\n\nasync function verifyOwner(storeId: string, userId: string) {\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n}\n","backend/src/controllers/giftCard.controller.ts":"// src/controllers/giftCard.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\nimport crypto from \"crypto\";\n\nconst createGiftCardSchema = z.object({\n  amount:      z.number().positive(),\n  currency:    z.string().default(\"USD\"),\n  assignedTo:  z.string().email().optional(),\n  expiresAt:   z.string().datetime().optional(),\n  note:        z.string().optional(),\n  purchasedBy: z.string().email().optional(),\n});\n\nfunction generateGiftCode(): string {\n  const chars = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\";\n  return Array.from({ length: 16 }, (_, i) =>\n    (i > 0 && i % 4 === 0 ? \"-\" : \"\") + chars[Math.floor(Math.random() * chars.length)]\n  ).join(\"\");\n}\n\n// POST /gift-cards/:storeId\nexport const createGiftCard = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyStoreOwner(storeId, req.user!.userId);\n\n  const data = createGiftCardSchema.parse(req.body);\n  const code = generateGiftCode();\n\n  const giftCard = await prisma.giftCard.create({\n    data: {\n      storeId, code, balance: data.amount, initialAmount: data.amount,\n      currency: data.currency, assignedTo: data.assignedTo,\n      purchasedBy: data.purchasedBy, note: data.note,\n      expiresAt: data.expiresAt ? new Date(data.expiresAt) : null,\n    },\n  });\n\n  // Email recipient if assigned\n  if (data.assignedTo) {\n    await emailService.send({\n      to: data.assignedTo,\n      subject: \"You received a Gift Card! 🎁\",\n      html: `<p>You've received a gift card worth <strong>${data.currency} ${data.amount.toFixed(2)}</strong>!</p><p>Your code: <strong style=\"font-size:24px;letter-spacing:4px\">${code}</strong></p>${data.note ? `<p>Message: ${data.note}</p>` : \"\"}${data.expiresAt ? `<p>Expires: ${new Date(data.expiresAt).toLocaleDateString()}</p>` : \"\"}`,\n    });\n  }\n\n  res.status(201).json({ success: true, data: giftCard });\n};\n\n// GET /gift-cards/:storeId\nexport const getGiftCards = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyStoreOwner(storeId, req.user!.userId);\n\n  const giftCards = await prisma.giftCard.findMany({\n    where: { storeId }, orderBy: { createdAt: \"desc\" },\n    include: { usages: { select: { amount: true, orderId: true, createdAt: true } } },\n  });\n\n  res.json({ success: true, data: giftCards });\n};\n\n// POST /gift-cards/validate  — public, validate a code at checkout\nexport const validateGiftCard = async (req: Request, res: Response) => {\n  const { code, storeId } = req.body;\n  if (!code || !storeId) throw new AppError(\"Code and storeId required\", 400);\n\n  const gc = await prisma.giftCard.findFirst({\n    where: { code: code.toUpperCase().replace(/\\s/g,\"\"), storeId, isActive: true },\n  });\n\n  if (!gc) throw new AppError(\"Invalid gift card code\", 404);\n  if (gc.balance <= 0) throw new AppError(\"This gift card has no remaining balance\", 400);\n  if (gc.expiresAt && gc.expiresAt < new Date()) throw new AppError(\"This gift card has expired\", 400);\n\n  res.json({ success: true, data: { id: gc.id, balance: gc.balance, currency: gc.currency } });\n};\n\n// PATCH /gift-cards/:storeId/:id/deactivate\nexport const deactivateGiftCard = async (req: AuthRequest, res: Response) => {\n  const { storeId, id } = req.params;\n  await verifyStoreOwner(storeId, req.user!.userId);\n\n  const gc = await prisma.giftCard.update({ where: { id }, data: { isActive: false } });\n  res.json({ success: true, data: gc });\n};\n\nasync function verifyStoreOwner(storeId: string, userId: string) {\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n}\n","backend/src/controllers/kai.agent.controller.ts":"// ============================================================\n// KAI Agent Controller — Dashboard In Chat\n// Path: backend/src/controllers/kai.agent.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport prisma                from \"../lib/prisma\";\nimport { detectAgentAction, executeAgentAction, getUserStores } from \"../services/kai.agent.service\";\nimport { getStoreContext, buildCompleteSystemPrompt, callClaude, generateTitle, detectIntent, needsWebSearch } from \"../services/kai.service\";\nimport { extractMemoriesFromConversation } from \"../services/kai.memory.service\";\n\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── GET /api/kai/agent/stores ─────────────────────────────────\n// Returns all stores for the logged-in user\nexport async function getMyStores(req: Request, res: Response) {\n  try {\n    const user   = (req as any).user;\n    const stores = await getUserStores(user.id);\n    res.json({ success: true, data: stores });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/agent/chat (STREAMING + AGENT) ─────────────\n// The main endpoint — handles both conversation and actions\nexport async function agentChat(req: Request, res: Response) {\n  const { message, conversationId, storeId, imageBase64, imageMediaType } = req.body;\n  const user = (req as any).user;\n\n  if (!message) return res.status(400).json({ success: false, message: \"message required\" });\n\n  // ── Multi-store: check if store is selected ──────────────────\n  if (!storeId) {\n    const stores = await getUserStores(user.id);\n    if (stores.length === 0) {\n      return res.status(400).json({\n        success: false,\n        code:    \"NO_STORE\",\n        message: \"No stores found. Create a store first.\",\n      });\n    }\n    if (stores.length === 1) {\n      // Auto-select if only one store\n      req.body.storeId = stores[0].id;\n    } else {\n      // Ask which store\n      return res.json({\n        success: true,\n        code:    \"SELECT_STORE\",\n        data: {\n          message: `You have ${stores.length} stores. Which one should I help with?`,\n          stores:  stores.map(s => ({\n            id:       s.id,\n            name:     s.name,\n            products: (s as any)._count.products,\n            orders:   (s as any)._count.orders,\n            status:   s.status,\n          })),\n        },\n      });\n    }\n  }\n\n  const activeStoreId = req.body.storeId || storeId;\n\n  try {\n    // ── Detect if this is an action or a conversation ────────────\n    const { action, confidence, extractedData } = detectAgentAction(message);\n\n    // High confidence action — present for approval before executing\n    if (confidence >= 0.8 && action !== \"unknown\") {\n      const proposal = buildActionProposal(action, extractedData, activeStoreId);\n\n      if (proposal) {\n        return res.json({\n          success: true,\n          code:    \"ACTION_PROPOSAL\",\n          data: {\n            action,\n            proposal,\n            extractedData,\n            storeId: activeStoreId,\n            message: proposal.description,\n          },\n        });\n      }\n    }\n\n    // ── Regular conversation — stream response ───────────────────\n    let conv: any = conversationId\n      ? await prisma.kaiConversation.findUnique({\n          where:   { id: conversationId },\n          include: { messages: { orderBy: { createdAt: \"asc\" }, take: 20 } },\n        })\n      : null;\n\n    if (!conv) {\n      conv = await prisma.kaiConversation.create({\n        data:    { storeId: activeStoreId, title: generateTitle(message) },\n        include: { messages: true },\n      });\n    }\n\n    await prisma.kaiMessage.create({\n      data: { conversationId: conv.id, role: \"user\", content: message },\n    });\n\n    const ctx         = await getStoreContext(activeStoreId);\n    const intent      = detectIntent(message);\n    const useSearch   = needsWebSearch(message, intent);\n    const history     = (conv.messages || []).slice(-8).map((m: any) =>\n      `${m.role === \"user\" ? \"Owner\" : \"KAI\"}: ${m.content.slice(0, 200)}`\n    ).join(\"\\n\");\n\n    const systemPrompt = await buildCompleteSystemPrompt(ctx, activeStoreId, history);\n\n    const claudeMsgs: any[] = (conv.messages || []).slice(-6).map((m: any) => ({\n      role:    m.role,\n      content: m.content,\n    }));\n\n    const currentContent: any[] = [];\n    if (imageBase64 && imageMediaType) {\n      currentContent.push({ type: \"image\", source: { type: \"base64\", media_type: imageMediaType, data: imageBase64 } });\n    }\n    currentContent.push({ type: \"text\", text: message });\n    claudeMsgs.push({ role: \"user\", content: currentContent.length === 1 ? message : currentContent });\n\n    res.setHeader(\"Content-Type\", \"text/event-stream\");\n    res.setHeader(\"Cache-Control\", \"no-cache\");\n    res.setHeader(\"Connection\", \"keep-alive\");\n\n    let fullResponse = \"\";\n\n    await callClaude({\n      systemPrompt,\n      messages:   claudeMsgs,\n      useSearch,\n      maxTokens:  1024,\n      onToken:    (token) => {\n        fullResponse += token;\n        res.write(`data: ${JSON.stringify({ token, conversationId: conv.id })}\\n\\n`);\n      },\n    });\n\n    await prisma.kaiMessage.create({\n      data: { conversationId: conv.id, role: \"assistant\", content: fullResponse, metadata: { intent, searched: useSearch } },\n    });\n    await prisma.kaiConversation.update({ where: { id: conv.id }, data: { updatedAt: new Date() } });\n\n    if (apiKey()) {\n      extractMemoriesFromConversation(activeStoreId, message, fullResponse, conv.id, apiKey()).catch(() => {});\n    }\n\n    res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\\n\\n`);\n    res.end();\n\n  } catch (err: any) {\n    console.error(\"[KAI Agent]\", err);\n    if (!res.headersSent) {\n      res.status(500).json({ success: false, message: \"KAI ran into an issue — please try again\" });\n    } else {\n      res.write(`data: ${JSON.stringify({ error: \"KAI error\" })}\\n\\n`);\n      res.end();\n    }\n  }\n}\n\n// ── POST /api/kai/agent/execute ───────────────────────────────\n// Executes an approved action\nexport async function executeAction(req: Request, res: Response) {\n  const { action, data, storeId, approved } = req.body;\n  const user = (req as any).user;\n\n  if (!approved) return res.status(400).json({ success: false, message: \"Action not approved\" });\n  if (!action)   return res.status(400).json({ success: false, message: \"action required\" });\n\n  try {\n    // Verify user owns this store\n    const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: user.id } });\n    if (!store) return res.status(403).json({ success: false, message: \"Not your store\" });\n\n    const result = await executeAgentAction(action, data || {}, storeId);\n\n    // Log the action\n    await prisma.kaiActionLog.create({\n      data: {\n        storeId,\n        conversationId: data?.conversationId || \"\",\n        actionType:     action,\n        payload:        data || {},\n        approved:       true,\n        executed:       result.success,\n        result:         result.result,\n      },\n    }).catch(() => {});\n\n    res.json({ success: result.success, data: result.result, message: result.message });\n\n  } catch (err: any) {\n    const msg = err.message === \"PRODUCT_NOT_FOUND\"\n      ? \"I couldn't find that product. Can you give me the exact name?\"\n      : err.message === \"NEED_PRODUCT\"\n      ? \"Which product should I update? Give me the name.\"\n      : err.message === \"NEED_ORDER_ID\"\n      ? \"Which order? Share the order number.\"\n      : \"Action failed — please try again\";\n\n    res.status(500).json({ success: false, message: msg });\n  }\n}\n\n// ── GET /api/kai/agent/context/:storeId ──────────────────────\n// Full store context for the frontend action cards\nexport async function getAgentContext(req: Request, res: Response) {\n  try {\n    const { storeId } = req.params;\n    const [products, orders, coupons] = await Promise.all([\n      prisma.product.count({ where: { storeId } }),\n      prisma.order.count({ where: { storeId, status: { in: [\"PENDING\",\"PROCESSING\"] } } }),\n      prisma.coupon.count({ where: { storeId, isActive: true } }),\n    ]);\n    res.json({ success: true, data: { products, pendingOrders: orders, coupons } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── Build action proposal for user approval ───────────────────\nfunction buildActionProposal(action: string, data: any, storeId: string): any | null {\n  const proposals: Record<string, any> = {\n    add_product: {\n      title:       \"Add Product\",\n      description: `Create new product${data.name ? ` \"${data.name}\"` : \"\"}${data.price ? ` at ₦${Number(data.price).toLocaleString()}` : \"\"}`,\n      icon:        \"📦\",\n      color:       \"#34d399\",\n      warning:     null,\n      fields: [\n        { key: \"name\",  label: \"Product name\",   value: data.name  || \"\",  required: true },\n        { key: \"price\", label: \"Selling price ₦\", value: data.price || \"\",  required: true },\n        { key: \"stock\", label: \"Stock quantity\",  value: data.stock || 0,   required: false },\n        { key: \"description\", label: \"Description\", value: \"\", required: false },\n        { key: \"publish\", label: \"Publish immediately\", value: true, type: \"boolean\" },\n      ],\n    },\n    update_product_price: {\n      title:       \"Update Price\",\n      description: `Change price${data.name ? ` of \"${data.name}\"` : \"\"}${data.price ? ` to ₦${Number(data.price).toLocaleString()}` : \"\"}`,\n      icon:        \"💰\",\n      color:       \"#fbbf24\",\n      warning:     null,\n      fields: [\n        { key: \"name\",  label: \"Product\",      value: data.name  || \"\", required: true },\n        { key: \"price\", label: \"New price ₦\",  value: data.price || \"\", required: true },\n      ],\n    },\n    bulk_update_prices: {\n      title:       \"Update All Prices\",\n      description: `${data.direction === \"increase\" ? \"Increase\" : \"Decrease\"} all product prices by ${data.percent}%`,\n      icon:        \"📊\",\n      color:       \"#f97316\",\n      warning:     \"This affects ALL your products\",\n      fields: [\n        { key: \"direction\", label: \"Direction\", value: data.direction, type: \"select\", options: [\"increase\",\"decrease\"] },\n        { key: \"percent\",   label: \"Percentage\", value: data.percent || \"\", required: true },\n      ],\n    },\n    update_product_stock: {\n      title:       \"Update Stock\",\n      description: `Set stock${data.name ? ` for \"${data.name}\"` : \"\"} to ${data.stock} units`,\n      icon:        \"📦\",\n      color:       \"#60a5fa\",\n      warning:     null,\n      fields: [\n        { key: \"name\",  label: \"Product\",      value: data.name  || \"\", required: true },\n        { key: \"stock\", label: \"New quantity\", value: data.stock || \"\", required: true },\n      ],\n    },\n    delete_product: {\n      title:       \"Delete Product\",\n      description: `Permanently delete \"${data.name}\"`,\n      icon:        \"🗑️\",\n      color:       \"#f87171\",\n      warning:     \"This cannot be undone\",\n      fields: [\n        { key: \"name\", label: \"Product to delete\", value: data.name || \"\", required: true },\n      ],\n    },\n    update_order_status: {\n      title:       \"Update Order\",\n      description: `Mark order as ${data.status}`,\n      icon:        \"📬\",\n      color:       \"#34d399\",\n      warning:     null,\n      fields: [\n        { key: \"orderId\", label: \"Order ID\", value: data.orderId || \"\", required: true },\n        { key: \"status\",  label: \"New status\", value: data.status || \"SHIPPED\", type: \"select\", options: [\"PROCESSING\",\"SHIPPED\",\"DELIVERED\",\"CANCELLED\"] },\n      ],\n    },\n    create_coupon: {\n      title:       \"Create Coupon\",\n      description: `New coupon: ${data.code || \"auto-generate\"} — ${data.discount}${data.type === \"PERCENTAGE\" ? \"%\" : \"₦\"} off`,\n      icon:        \"🎟️\",\n      color:       \"#a78bfa\",\n      warning:     null,\n      fields: [\n        { key: \"code\",     label: \"Coupon code (or leave blank)\",  value: data.code || \"\" },\n        { key: \"discount\", label: \"Discount\",                      value: data.discount || 10, required: true },\n        { key: \"type\",     label: \"Type\",                          value: data.type || \"PERCENTAGE\", type: \"select\", options: [\"PERCENTAGE\",\"FIXED\"] },\n        { key: \"limit\",    label: \"Usage limit (0 = unlimited)\",   value: data.limit || 0 },\n      ],\n    },\n    create_flash_sale: {\n      title:       \"Start Flash Sale\",\n      description: `Run a flash sale with ${data.discount}% discount`,\n      icon:        \"⚡\",\n      color:       \"#fbbf24\",\n      warning:     null,\n      fields: [\n        { key: \"discount\",  label: \"Discount %\",     value: data.discount || 20, required: true },\n        { key: \"endHours\",  label: \"Duration (hours)\", value: 24 },\n        { key: \"products\",  label: \"Apply to\", value: \"all\", type: \"select\", options: [\"all\",\"specific\"] },\n      ],\n    },\n    update_store_name: {\n      title:       \"Rename Store\",\n      description: `Change store name to \"${data.name}\"`,\n      icon:        \"🏪\",\n      color:       \"#60a5fa\",\n      warning:     null,\n      fields: [\n        { key: \"name\", label: \"New store name\", value: data.name || \"\", required: true },\n      ],\n    },\n    toggle_store_status: {\n      title:       data.status === \"ACTIVE\" ? \"Open Store\" : \"Close Store\",\n      description: data.status === \"ACTIVE\" ? \"Your store will be visible and accepting orders\" : \"Your store will be hidden from customers\",\n      icon:        data.status === \"ACTIVE\" ? \"🟢\" : \"🔴\",\n      color:       data.status === \"ACTIVE\" ? \"#34d399\" : \"#f87171\",\n      warning:     data.status !== \"ACTIVE\" ? \"Customers won't be able to place orders\" : null,\n      fields:      [],\n    },\n    change_store_template: {\n      title:       \"Change Template\",\n      description: `Switch to \"${data.template}\" theme`,\n      icon:        \"🎨\",\n      color:       \"#a78bfa\",\n      warning:     \"Your store design will change immediately\",\n      fields: [\n        { key: \"template\", label: \"Template\", value: data.template || \"\" },\n      ],\n    },\n  };\n\n  return proposals[action] || null;\n}\n","backend/src/controllers/kai.controller.ts":"// ============================================================\n// KAI — Complete Controller (10/10)\n// Path: backend/src/controllers/kai.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  getStoreContext, buildCompleteSystemPrompt, callClaude,\n  detectIntent, needsWebSearch, generateTitle,\n  buildGreeting, buildQuickActions,\n} from \"../services/kai.service\";\nimport {\n  extractMemoriesFromConversation, getMemories, saveMemory,\n  deleteMemory, getActiveGoals, analyzeBrandVoice,\n} from \"../services/kai.memory.service\";\nimport {\n  getUnreadAlerts, markAlertRead, analyzeStore,\n} from \"../services/kai.pulse.service\";\nimport { getKaiSkills } from \"../services/kai.market.service\";\n\nconst prisma = new PrismaClient();\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── GET /api/kai/greeting ─────────────────────────────────────\nexport async function getGreeting(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const [ctx, alerts] = await Promise.all([\n      getStoreContext(storeId),\n      getUnreadAlerts(storeId),\n    ]);\n\n    const user      = (req as any).user;\n    const firstName = (user?.name || \"there\").split(\" \")[0];\n    const hour      = new Date().getHours();\n\n    const { greeting, contextLine } = buildGreeting(firstName, ctx, hour);\n    const quickActions = buildQuickActions(ctx);\n\n    res.json({\n      success: true,\n      data: { greeting, name: firstName, contextLine, quickActions, storeContext: ctx, unreadAlerts: alerts.length },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversations ────────────────────────────────\nexport async function getConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const conversations = await prisma.kaiConversation.findMany({\n      where: { storeId, archived: false },\n      orderBy: [{ pinned: \"desc\" }, { updatedAt: \"desc\" }],\n      select: {\n        id: true, title: true, pinned: true, createdAt: true, updatedAt: true,\n        messages: { orderBy: { createdAt: \"desc\" }, take: 1, select: { content: true, role: true } },\n      },\n    });\n    res.json({ success: true, data: conversations });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversation/:id ─────────────────────────────\nexport async function getConversation(req: Request, res: Response) {\n  try {\n    const conv = await prisma.kaiConversation.findUnique({\n      where: { id: req.params.id },\n      include: { messages: { orderBy: { createdAt: \"asc\" } } },\n    });\n    if (!conv) return res.status(404).json({ success: false, message: \"Not found\" });\n    res.json({ success: true, data: conv });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/smart-chat (STREAMING + MEMORY) ────────────\nexport async function smartChat(req: Request, res: Response) {\n  const { message, conversationId, storeId, imageBase64, imageMediaType } = req.body;\n  if (!message || !storeId)\n    return res.status(400).json({ success: false, message: \"message and storeId required\" });\n\n  try {\n    // Get or create conversation\n    let conv: any = conversationId\n      ? await prisma.kaiConversation.findUnique({\n          where: { id: conversationId },\n          include: { messages: { orderBy: { createdAt: \"asc\" }, take: 20 } },\n        })\n      : null;\n\n    if (!conv) {\n      conv = await prisma.kaiConversation.create({\n        data: { storeId, title: generateTitle(message) },\n        include: { messages: true },\n      });\n    }\n\n    // Save user message\n    await prisma.kaiMessage.create({\n      data: { conversationId: conv.id, role: \"user\", content: message },\n    });\n\n    // Get everything in parallel\n    const [ctx, intent] = await Promise.all([\n      getStoreContext(storeId),\n      Promise.resolve(detectIntent(message)),\n    ]);\n    const useSearch = needsWebSearch(message, intent);\n\n    // Build conversation history\n    const history = (conv.messages || [])\n      .slice(-8)\n      .map((m: any) => `${m.role === \"user\" ? \"Owner\" : \"KAI\"}: ${m.content.slice(0, 200)}`)\n      .join(\"\\n\");\n\n    // Build complete system prompt (includes memory, goals, brand voice, market data)\n    const systemPrompt = await buildCompleteSystemPrompt(ctx, storeId, history);\n\n    // Build messages array\n    const claudeMsgs: any[] = [];\n    for (const m of (conv.messages || []).slice(-6)) {\n      claudeMsgs.push({ role: m.role, content: m.content });\n    }\n    // Current message (with optional image)\n    const currentContent: any[] = [];\n    if (imageBase64 && imageMediaType) {\n      currentContent.push({ type: \"image\", source: { type: \"base64\", media_type: imageMediaType, data: imageBase64 } });\n    }\n    currentContent.push({ type: \"text\", text: message });\n    claudeMsgs.push({ role: \"user\", content: currentContent.length === 1 ? message : currentContent });\n\n    // Stream response\n    res.setHeader(\"Content-Type\", \"text/event-stream\");\n    res.setHeader(\"Cache-Control\", \"no-cache\");\n    res.setHeader(\"Connection\", \"keep-alive\");\n\n    let fullResponse = \"\";\n\n    await callClaude({\n      systemPrompt,\n      messages: claudeMsgs,\n      useSearch,\n      maxTokens: 1024,\n      onToken: (token) => {\n        fullResponse += token;\n        res.write(`data: ${JSON.stringify({ token, conversationId: conv.id })}\\n\\n`);\n      },\n    });\n\n    // Save KAI response\n    await prisma.kaiMessage.create({\n      data: {\n        conversationId: conv.id,\n        role: \"assistant\",\n        content: fullResponse,\n        metadata: { intent, searched: useSearch },\n      },\n    });\n\n    await prisma.kaiConversation.update({\n      where: { id: conv.id },\n      data: { updatedAt: new Date() },\n    });\n\n    // Extract memories in background (don't await — don't slow down response)\n    if (apiKey()) {\n      extractMemoriesFromConversation(storeId, message, fullResponse, conv.id, apiKey())\n        .catch(err => console.error(\"Memory extraction error:\", err));\n    }\n\n    res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\\n\\n`);\n    res.end();\n\n  } catch (err: any) {\n    console.error(\"KAI smart-chat error:\", err);\n    if (!res.headersSent) {\n      res.status(500).json({ success: false, message: \"KAI is temporarily unavailable\" });\n    } else {\n      res.write(`data: ${JSON.stringify({ error: true })}\\n\\n`);\n      res.end();\n    }\n  }\n}\n\n// ── POST /api/kai/action ──────────────────────────────────────\nexport async function executeAction(req: Request, res: Response) {\n  const { conversationId, storeId, actions } = req.body;\n  if (!actions?.length) return res.status(400).json({ success: false, message: \"actions required\" });\n\n  const results = [];\n  for (const action of actions) {\n    if (!action.approved) continue;\n    try {\n      let result: any = null;\n      switch (action.type) {\n        case \"update_order_status\":\n          result = await prisma.order.update({ where: { id: action.payload.orderId }, data: { status: action.payload.status } });\n          break;\n        case \"create_coupon\":\n          result = await prisma.coupon.create({\n            data: { storeId, code: action.payload.code, discountType: action.payload.discountType || \"PERCENTAGE\",\n              discountValue: action.payload.discountValue, isActive: true,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null },\n          });\n          break;\n        case \"update_price\":\n          result = await prisma.product.update({ where: { id: action.payload.productId }, data: { price: action.payload.price } });\n          break;\n        case \"update_goal\":\n          result = await prisma.kaiGoal.upsert({\n            where: { id: action.payload.goalId || \"new\" },\n            create: { storeId, title: action.payload.title, targetValue: action.payload.targetValue,\n              currentValue: 0, unit: action.payload.unit, deadline: new Date(action.payload.deadline) },\n            update: { currentValue: action.payload.currentValue },\n          });\n          break;\n        default:\n          result = { note: `Action ${action.type} logged for manual execution` };\n      }\n      await prisma.kaiActionLog.create({\n        data: { storeId, conversationId: conversationId || \"\", actionType: action.type,\n          payload: action.payload, approved: true, executed: true, result },\n      });\n      results.push({ actionId: action.id, success: true, result });\n    } catch (err: any) {\n      results.push({ actionId: action.id, success: false, error: err.message });\n    }\n  }\n  res.json({ success: true, data: results });\n}\n\n// ── PATCH /api/kai/conversation/:id ──────────────────────────\nexport async function updateConversation(req: Request, res: Response) {\n  try {\n    const { title, pinned, archived } = req.body;\n    const updated = await prisma.kaiConversation.update({\n      where: { id: req.params.id },\n      data: {\n        ...(title    !== undefined && { title }),\n        ...(pinned   !== undefined && { pinned }),\n        ...(archived !== undefined && { archived }),\n      },\n    });\n    res.json({ success: true, data: updated });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversation/:id ─────────────────────────\nexport async function deleteConversation(req: Request, res: Response) {\n  try {\n    await prisma.kaiConversation.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversations/all ────────────────────────\nexport async function deleteAllConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    await prisma.kaiConversation.deleteMany({ where: { storeId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/memories ─────────────────────────────────────\nexport async function getKaiMemories(req: Request, res: Response) {\n  try {\n    const { storeId, category } = req.query as { storeId: string; category?: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const memories = await getMemories(storeId, category);\n    res.json({ success: true, data: memories });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/memory/:key ───────────────────────────────\nexport async function deleteKaiMemory(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    await deleteMemory(storeId, req.params.key);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/pulse ────────────────────────────────────────\nexport async function getPulseAlerts(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const alerts = await getUnreadAlerts(storeId);\n    res.json({ success: true, data: alerts });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── PATCH /api/kai/pulse/:id/read ────────────────────────────\nexport async function readPulseAlert(req: Request, res: Response) {\n  try {\n    await markAlertRead(req.params.id);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/skills ───────────────────────────────────────\nexport async function getSkills(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const skills = await getKaiSkills(storeId);\n    res.json({ success: true, data: skills });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills ──────────────────────────────────────\nexport async function createSkill(req: Request, res: Response) {\n  try {\n    const { storeId, name, prompt, description, icon, variables } = req.body;\n    if (!storeId || !name || !prompt) return res.status(400).json({ success: false, message: \"storeId, name, prompt required\" });\n    const skill = await prisma.kaiSkill.create({\n      data: { storeId, name, prompt, description, icon, variables: variables || [] },\n    });\n    res.json({ success: true, data: skill });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/skills/:id ────────────────────────────────\nexport async function deleteSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills/:id/use ─────────────────────────────\nexport async function useSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.update({\n      where: { id: req.params.id },\n      data: { usageCount: { increment: 1 } },\n    });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/analyze-voice ───────────────────────────────\nexport async function analyzeVoice(req: Request, res: Response) {\n  try {\n    const { storeId, content } = req.body;\n    if (!storeId || !content) return res.status(400).json({ success: false, message: \"storeId and content required\" });\n    await analyzeBrandVoice(storeId, content, apiKey());\n    res.json({ success: true, message: \"Brand voice analyzed and saved\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/goals ────────────────────────────────────────\nexport async function getGoals(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const goals = await prisma.kaiGoal.findMany({\n      where: { storeId },\n      include: { milestones: true },\n      orderBy: { deadline: \"asc\" },\n    });\n    res.json({ success: true, data: goals });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/goals ───────────────────────────────────────\nexport async function createGoal(req: Request, res: Response) {\n  try {\n    const { storeId, title, targetValue, unit, deadline, description } = req.body;\n    if (!storeId || !title || !targetValue || !deadline)\n      return res.status(400).json({ success: false, message: \"storeId, title, targetValue, deadline required\" });\n\n    const goal = await prisma.kaiGoal.create({\n      data: { storeId, title, description, targetValue, unit: unit || \"NGN\", deadline: new Date(deadline) },\n      include: { milestones: true },\n    });\n\n    // Save to memory\n    await saveMemory(storeId, \"goal\", `goal_${goal.id}`,\n      `Owner wants to ${title} by ${new Date(deadline).toLocaleDateString()}`, 1.0);\n\n    res.json({ success: true, data: goal });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n","backend/src/controllers/kai.intelligence.controller.ts":"// ============================================================\n// KAI Intelligence Controller + Routes\n// Path: backend/src/controllers/kai.intelligence.controller.ts\n// Add to app.ts: app.use(\"/api/intel\", intelRoutes);\n// ============================================================\nimport { Request, Response } from \"express\";\nimport {\n  runAdSpy, generateTikTokScript, getDailyTop10,\n  getProfitRules, createProfitRule, evaluateProfitRules,\n  bulkScrapeSupplierStore, checkFulfillmentStatus, markOrderFulfilling,\n  syncPricesAndStock, spyCompetitorStore, findSupplierAlternatives,\n} from \"../services/kai.intelligence.service\";\nimport prisma from \"../lib/prisma\";\n\nconst wrap = (fn: Function) => async (req: Request, res: Response) => {\n  try {\n    const data = await fn(req);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message || \"Failed\" });\n  }\n};\n\n// ── Ad Spy ────────────────────────────────────────────────────\nexport const adSpy = wrap(async (req: Request) => {\n  const { query, platform = \"all\", storeId } = req.body;\n  if (!query) throw new Error(\"query required\");\n  const store  = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return runAdSpy({ query, platform, country: store?.country || \"NG\", storeId });\n});\n\n// ── TikTok Script ─────────────────────────────────────────────\nexport const tikTokScript = wrap(async (req: Request) => {\n  const { productName, productDesc, price, storeId, duration = 30, angle } = req.body;\n  if (!productName || !price) throw new Error(\"productName and price required\");\n  const store  = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return generateTikTokScript({ productName, productDesc, price: Number(price), country: store?.country || \"NG\", duration, angle });\n});\n\n// ── Daily Top 10 ──────────────────────────────────────────────\nexport const dailyTop10 = wrap(async (req: Request) => {\n  const { storeId } = req.query as any;\n  return getDailyTop10(storeId);\n});\n\n// ── Profit Rules ──────────────────────────────────────────────\nexport const listProfitRules = wrap(async (req: Request) => {\n  return getProfitRules(req.params.storeId);\n});\nexport const addProfitRule = wrap(async (req: Request) => {\n  const { storeId, ...rule } = req.body;\n  return createProfitRule(storeId, rule);\n});\nexport const deleteProfitRule = wrap(async (req: Request) => {\n  await prisma.profitProtectionRule.update({ where: { id: req.params.id }, data: { isActive: false } });\n  return { deleted: true };\n});\nexport const runProfitCheck = wrap(async (req: Request) => {\n  return evaluateProfitRules(req.params.storeId);\n});\n\n// ── Bulk Import ───────────────────────────────────────────────\nexport const bulkImport = wrap(async (req: Request) => {\n  const { storeUrl, storeId, limit } = req.body;\n  if (!storeUrl) throw new Error(\"storeUrl required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return bulkScrapeSupplierStore({ storeUrl, country: store?.country || \"NG\", limit: Number(limit) || 20 });\n});\n\nexport const confirmBulkImport = wrap(async (req: Request) => {\n  const { storeId, products, pricingRule } = req.body;\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  const { getLocale } = require(\"../utils/kai.locale\");\n  const locale = getLocale(store?.country || \"NG\");\n\n  const created = await Promise.all(\n    (products as any[]).map((p: any) => {\n      const sellingPrice = pricingRule === \"2x\" ? p.localCost * 2\n        : pricingRule === \"2.5x\" ? p.localCost * 2.5\n        : pricingRule === \"3x\"   ? p.localCost * 3\n        : p.suggestedLocalPrice || p.localCost * 2.5;\n\n      return prisma.product.create({\n        data: {\n          storeId, name: p.name,\n          price: Math.round(sellingPrice),\n          costPrice: p.localCost,\n          stockQuantity: 50,\n          category: p.category || \"General\",\n          images: p.image ? [p.image] : [],\n          sourceUrl: p.supplierUrl,\n          isActive: true,\n        },\n      }).catch(() => null);\n    })\n  );\n\n  return { imported: created.filter(Boolean).length, total: products.length };\n});\n\n// ── Fulfillment ───────────────────────────────────────────────\nexport const fulfillmentQueue = wrap(async (req: Request) => {\n  const { storeId } = req.query as any;\n  return checkFulfillmentStatus(storeId);\n});\n\nexport const fulfillOrder = wrap(async (req: Request) => {\n  const { orderId, trackingNumber, carrier } = req.body;\n  return markOrderFulfilling(orderId, trackingNumber, carrier);\n});\n\n// ── Price Sync ────────────────────────────────────────────────\nexport const priceSync = wrap(async (req: Request) => {\n  const { storeId } = req.params;\n  return syncPricesAndStock(storeId);\n});\n\n// ── Competitor Spy ────────────────────────────────────────────\nexport const competitorSpy = wrap(async (req: Request) => {\n  const { storeUrl, storeId } = req.body;\n  if (!storeUrl) throw new Error(\"storeUrl required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return spyCompetitorStore({ storeUrl, country: store?.country || \"NG\" });\n});\n\n// ── Supplier Finder ───────────────────────────────────────────\nexport const supplierFinder = wrap(async (req: Request) => {\n  const { productName, currentUrl, storeId, maxPriceUSD } = req.body;\n  if (!productName) throw new Error(\"productName required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return findSupplierAlternatives({ productName, currentUrl, country: store?.country || \"NG\", maxPriceUSD });\n});\n\n// ── ROUTES ────────────────────────────────────────────────────\nimport { Router }    from \"express\";\nimport rateLimit     from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\n\nconst router   = Router();\nconst aiLimit  = rateLimit({ windowMs: 60000, max: 10, message: { success: false, message: \"Too many AI requests — wait a moment\" } });\n\nrouter.use(authenticate);\n\n// Ad Spy\nrouter.post(\"/ad-spy\",                aiLimit, adSpy);\n\n// TikTok Scripts\nrouter.post(\"/tiktok-script\",         aiLimit, tikTokScript);\n\n// Daily Top 10\nrouter.get (\"/daily-top10\",           aiLimit, dailyTop10);\n\n// Profit Rules\nrouter.get (\"/profit-rules/:storeId\", listProfitRules);\nrouter.post(\"/profit-rules\",          addProfitRule);\nrouter.delete(\"/profit-rules/:id\",    deleteProfitRule);\nrouter.post(\"/profit-rules/:storeId/run\", aiLimit, runProfitCheck);\n\n// Bulk Import\nrouter.post(\"/bulk-import\",           aiLimit, bulkImport);\nrouter.post(\"/bulk-import/confirm\",   confirmBulkImport);\n\n// Fulfillment\nrouter.get (\"/fulfillment\",           fulfillmentQueue);\nrouter.post(\"/fulfillment/fulfill\",   fulfillOrder);\n\n// Price Sync\nrouter.post(\"/price-sync/:storeId\",   aiLimit, priceSync);\n\n// Competitor Spy\nrouter.post(\"/competitor-spy\",        aiLimit, competitorSpy);\n\n// Supplier Finder\nrouter.post(\"/suppliers\",             aiLimit, supplierFinder);\n\nexport default router;\n","backend/src/controllers/kai.power.controller.ts":"// ============================================================\n// KAI — Power Features Controller\n// Path: backend/src/controllers/kai.power.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport {\n  generateProductPage, generateAdCopy, getWinningProducts,\n  calculateProfit, researchNiche, analyzeCompetitor,\n  analyzeBuyerMotivation,\n} from \"../services/kai.power.service\";\n\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// POST /api/kai/power/product-page\nexport async function productPage(req: Request, res: Response) {\n  try {\n    const { url, productName, productDescription, language = \"English\", niche } = req.body;\n    const user = (req as any).user;\n    const storeId = user?.stores?.[0]?.id;\n\n    // Get store country\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true, currency: true } });\n    const country = store?.country || \"NG\";\n\n    const page = await generateProductPage({ url, productName, productDescription, country, language, apiKey: apiKey() });\n    res.json({ success: true, data: page });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// POST /api/kai/power/ad-copy\nexport async function adCopy(req: Request, res: Response) {\n  try {\n    const { productName, productDescription, targetAudience, platform, angle } = req.body;\n    if (!productName || !platform)\n      return res.status(400).json({ success: false, message: \"productName and platform required\" });\n\n    const user = (req as any).user;\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true } });\n\n    const copy = await generateAdCopy({\n      productName, productDescription: productDescription || productName,\n      targetAudience: targetAudience || \"general audience\",\n      platform, country: store?.country || \"NG\", angle, apiKey: apiKey(),\n    });\n    res.json({ success: true, data: copy });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// GET /api/kai/power/winning-products\nexport async function winningProducts(req: Request, res: Response) {\n  try {\n    const { storeId, niche, count = 10 } = req.query as any;\n    const user = (req as any).user;\n\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true } });\n\n    const products = await getWinningProducts({\n      storeId: storeId || user?.stores?.[0]?.id,\n      niche, country: store?.country || \"NG\",\n      count: Math.min(Number(count), 20),\n      apiKey: apiKey(),\n    });\n    res.json({ success: true, data: products });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// POST /api/kai/power/profit-calc\nexport async function profitCalc(req: Request, res: Response) {\n  try {\n    const { supplierCostUSD, shippingCostLocal, sellingPriceLocal, adSpendDaily, expectedConversionRate } = req.body;\n    if (!supplierCostUSD || !sellingPriceLocal)\n      return res.status(400).json({ success: false, message: \"supplierCostUSD and sellingPriceLocal required\" });\n\n    const user = (req as any).user;\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true } });\n\n    // Get forex rate from market cache\n    const cache = await prisma.kaiMarketCache.findUnique({ where: { key: \"forex_rates\" } });\n    const rates = cache?.data as any || {};\n    const country = store?.country || \"NG\";\n    const exchangeRate = country === \"NG\" ? (rates.NGN || 1580)\n      : country === \"GH\" ? (rates.GHS || 15.2)\n      : country === \"KE\" ? (rates.KES || 130)\n      : 1;\n\n    const result = calculateProfit({\n      supplierCostUSD: Number(supplierCostUSD),\n      shippingCostLocal: Number(shippingCostLocal || 0),\n      sellingPriceLocal: Number(sellingPriceLocal),\n      country,\n      adSpendDaily: adSpendDaily ? Number(adSpendDaily) : undefined,\n      expectedConversionRate: expectedConversionRate ? Number(expectedConversionRate) : undefined,\n    });\n\n    res.json({ success: true, data: result });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// POST /api/kai/power/niche-research\nexport async function nicheResearch(req: Request, res: Response) {\n  try {\n    const { niche } = req.body;\n    if (!niche) return res.status(400).json({ success: false, message: \"niche required\" });\n\n    const user = (req as any).user;\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true } });\n\n    const research = await researchNiche({ niche, country: store?.country || \"NG\", apiKey: apiKey() });\n    res.json({ success: true, data: research });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// POST /api/kai/power/competitor\nexport async function competitorAnalysis(req: Request, res: Response) {\n  try {\n    const { storeUrl } = req.body;\n    if (!storeUrl) return res.status(400).json({ success: false, message: \"storeUrl required\" });\n\n    const user = (req as any).user;\n    const analysis = await analyzeCompetitor({ storeUrl, apiKey: apiKey() });\n    res.json({ success: true, data: analysis });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// POST /api/kai/power/buyer-motivation\nexport async function buyerMotivation(req: Request, res: Response) {\n  try {\n    const { productName } = req.body;\n    if (!productName) return res.status(400).json({ success: false, message: \"productName required\" });\n\n    const user = (req as any).user;\n    const { PrismaClient } = require(\"@prisma/client\");\n    const prisma = new PrismaClient();\n    const store = await prisma.store.findFirst({ where: { ownerId: user?.id }, select: { country: true } });\n\n    const analysis = await analyzeBuyerMotivation({ productName, country: store?.country || \"NG\", apiKey: apiKey() });\n    res.json({ success: true, data: analysis });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n","backend/src/controllers/notificationSettings.controller.ts":"// src/controllers/notification.settings.controller.ts\nimport { Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { notificationService } from \"../services/notification.service\";\nimport { requireStoreOwner } from \"./store.controller\";\n\nconst settingsSchema = z.object({\n  smsEnabled:        z.boolean().optional(),\n  smsPhone:          z.string().optional().nullable(),\n  whatsappEnabled:   z.boolean().optional(),\n  whatsappPhone:     z.string().optional().nullable(),\n  notifyOwnerSms:    z.boolean().optional(),\n  notifyCustomerSms: z.boolean().optional(),\n});\n\n// ── GET /api/notifications/settings/:storeId ──────────────────────────────────\nexport const getNotificationSettings = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const store = await prisma.store.findUnique({\n    where:  { id: storeId },\n    select: {\n      smsEnabled: true, smsPhone: true,\n      whatsappEnabled: true, whatsappPhone: true,\n      notifyOwnerSms: true, notifyCustomerSms: true,\n    },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  // Mask phone numbers in response (show only last 4 digits)\n  const masked = (phone: string | null) => phone ? `****${phone.slice(-4)}` : null;\n\n  return res.json({\n    success: true,\n    data: {\n      ...store,\n      smsPhoneMasked:       masked(store.smsPhone),\n      whatsappPhoneMasked:  masked(store.whatsappPhone),\n      twilioConfigured:     !!(process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_ACCOUNT_SID !== \"placeholder\"),\n    },\n  });\n};\n\n// ── PUT /api/notifications/settings/:storeId ──────────────────────────────────\nexport const updateNotificationSettings = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const data = settingsSchema.parse(req.body);\n\n  // Validate phone formats if provided (E.164 format: +<country><number>)\n  const e164 = /^\\+[1-9]\\d{7,14}$/;\n  if (data.smsPhone && !e164.test(data.smsPhone)) {\n    throw new AppError(\"SMS phone must be in E.164 format (e.g. +2348012345678)\", 400);\n  }\n  if (data.whatsappPhone && !e164.test(data.whatsappPhone)) {\n    throw new AppError(\"WhatsApp phone must be in E.164 format (e.g. +2348012345678)\", 400);\n  }\n\n  const updated = await prisma.store.update({\n    where:  { id: storeId },\n    data,\n    select: {\n      smsEnabled: true, smsPhone: true,\n      whatsappEnabled: true, whatsappPhone: true,\n      notifyOwnerSms: true, notifyCustomerSms: true,\n    },\n  });\n\n  return res.json({ success: true, message: \"Notification settings saved\", data: updated });\n};\n\n// ── POST /api/notifications/test/:storeId ─────────────────────────────────────\nexport const sendTestNotification = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { channel, phone } = z.object({\n    channel: z.enum([\"sms\", \"whatsapp\"]),\n    phone:   z.string().regex(/^\\+[1-9]\\d{7,14}$/, \"Must be E.164 format\"),\n  }).parse(req.body);\n\n  const user = await prisma.user.findUnique({\n    where:  { id: req.user!.userId },\n    select: { name: true },\n  });\n\n  await notificationService.sendTest({\n    phone,\n    channel,\n    name: user?.name || \"there\",\n  });\n\n  return res.json({ success: true, message: `Test ${channel} sent to ${phone}` });\n};\n\n// ── GET /api/notifications/logs/:storeId ──────────────────────────────────────\n// Returns recent order events so dashboard can show notification history\nexport const getNotificationLogs = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  // Use recent orders as a proxy for notification activity\n  const orders = await prisma.order.findMany({\n    where:   { storeId },\n    orderBy: { createdAt: \"desc\" },\n    take:    20,\n    select:  {\n      id: true, orderNumber: true, customerName: true, customerPhone: true,\n      customerEmail: true, status: true, total: true, currency: true, createdAt: true,\n    },\n  });\n\n  const store = await prisma.store.findUnique({\n    where:  { id: storeId },\n    select: { smsEnabled: true, notifyCustomerSms: true, whatsappEnabled: true, notifyOwnerSms: true },\n  });\n\n  return res.json({\n    success: true,\n    data: orders.map(o => ({\n      ...o,\n      smsCustomerSent: !!(store?.notifyCustomerSms && o.customerPhone),\n      smsOwnerSent:    !!(store?.smsEnabled && store?.notifyOwnerSms),\n      waOwnerSent:     !!(store?.whatsappEnabled && store?.notifyOwnerSms),\n    })),\n  });\n};\n","backend/src/controllers/order.controller.ts":"// src/controllers/order.controller.ts\nimport { supplierService, FulfillmentPayload } from \"../services/supplier.service\";\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { logger } from \"../utils/logger\";\nimport { generateOrderNumber, paginate } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { requireStoreOwner } from \"./store.controller\";\nimport { emailService }        from \"../services/email.service\";\nimport { notificationService } from \"../services/notification.service\";\nimport { pushToStoreOwner, PushTemplates } from \"../services/push.service\";\n\nconst orderItemSchema = z.object({\n  productId: z.string().uuid(),\n  variantId: z.string().optional(),\n  quantity:  z.number().int().min(1).max(1000).int().positive(),\n});\n\nconst createOrderSchema = z.object({\n  storeId:         z.string().uuid(),\n  customerName:    z.string().min(2),\n  customerEmail:   z.string().email(),\n  customerPhone:   z.string().optional(),\n  shippingAddress: z.object({\n    address:    z.string().optional(),  // frontend field\n    line1:      z.string().optional(),  // alias\n    line2:      z.string().optional(),\n    city:       z.string(),\n    state:      z.string().optional(),\n    postalCode: z.string().optional(),\n    zip:        z.string().optional(),\n    country:    z.string(),\n  }).optional(),\n  shippingCost:   z.number().optional(),\n  taxAmount:      z.number().optional(),\n  discountAmount: z.number().optional(),\n  couponCode:     z.string().optional(),\n  shippingMethod: z.string().optional(),\n  billingAddress: z.object({\n    line1:   z.string(),\n    city:    z.string(),\n    country: z.string(),\n  }).optional(),\n  items:  z.array(orderItemSchema).min(1),\n  notes:  z.string().optional(),\n  coupon:     z.string().optional(),  // legacy alias\n});\n\n// Create order (public checkout)\nexport const createOrder = async (req: Request, res: Response) => {\n  const raw  = { ...req.body, couponCode: req.body.couponCode || req.body.coupon };\n  const data = createOrderSchema.parse(raw);\n\n  const store = await prisma.store.findUnique({ where: { id: data.storeId, status: \"ACTIVE\" } });\n  if (!store) throw new AppError(\"Store not found or inactive\", 404);\n\n  // Validate products and calculate totals\n  let subtotal = 0;\n  const orderItems: any[] = [];\n\n  for (const item of data.items) {\n    const product = await prisma.product.findFirst({\n      where: { id: item.productId, storeId: data.storeId, status: \"ACTIVE\" },\n    });\n    if (!product) throw new AppError(`Product ${item.productId} not found`, 404);\n\n    // Check inventory\n    if (product.trackInventory && !product.allowBackorder) {\n      if (product.inventory < item.quantity) {\n        throw new AppError(`Insufficient stock for ${product.name}`, 400);\n      }\n    }\n\n    const price = product.price;\n    const total = price * item.quantity;\n    subtotal += total;\n\n    orderItems.push({\n      productId: product.id,\n      variantId: item.variantId,\n      name:      product.name,\n      sku:       product.sku,\n      price,\n      quantity:  item.quantity,\n      total,\n      image:     product.images[0],\n    });\n  }\n\n  const taxAmount      = subtotal * ((store.taxRate || 0) / 100);\n  // Use frontend-provided shipping cost; override to 0 if store's free-shipping threshold is met\n  const rawShipping    = typeof data.shippingCost === 'number' ? data.shippingCost : 0;\n  const shippingCost   = (store.freeShippingMin && subtotal >= store.freeShippingMin) ? 0 : rawShipping;\n  const total          = subtotal + taxAmount + shippingCost;\n  const orderNumber    = generateOrderNumber();\n\n  // Upsert store customer\n  let customer = await prisma.storeCustomer.findUnique({\n    where: { storeId_email: { storeId: data.storeId, email: data.customerEmail } },\n  });\n  if (!customer) {\n    customer = await prisma.storeCustomer.create({\n      data: {\n        storeId: data.storeId,\n        email:   data.customerEmail,\n        name:    data.customerName,\n        phone:   data.customerPhone,\n      },\n    });\n  }\n\n  // Create order\n  const order = await prisma.order.create({\n    data: {\n      orderNumber,\n      storeId:         data.storeId,\n      customerId:      customer.id,\n      customerEmail:   data.customerEmail,\n      customerName:    data.customerName,\n      customerPhone:   data.customerPhone,\n      shippingAddress: data.shippingAddress as any,\n      billingAddress:  data.billingAddress  as any,\n      notes:           data.notes,\n      subtotal,\n      taxAmount,\n      shippingCost,\n      total,\n      currency: store.currency,\n      status:   \"PENDING\",\n      items:    { create: orderItems },\n    },\n    include: { items: true },\n  });\n\n  // Decrement inventory\n  for (const item of data.items) {\n    await prisma.product.update({\n      where: { id: item.productId },\n      data:  { inventory: { decrement: item.quantity } },\n    });\n  }\n\n  // Send order confirmation to customer (email + optional SMS)\n  emailService.sendOrderConfirmation({\n    email:      order.customerEmail,\n    name:       order.customerName,\n    orderNumber: order.orderNumber,\n    total:      order.total,\n    currency:   order.currency,\n    storeName:  store.name,\n    storeEmail: store.supportEmail || undefined,\n    items:      order.items.map((i: any) => ({ name: i.name, quantity: i.quantity, price: i.price })),\n  });\n\n  notificationService.notifyCustomerOrderConfirmed({\n    customerPhone: order.customerPhone,\n    smsEnabled:    store.notifyCustomerSms ?? false,\n    storeName:     store.name,\n    orderNumber:   order.orderNumber,\n    total:         order.total,\n    currency:      order.currency,\n    storeSlug:     store.slug,\n  });\n\n  // Send new order alert to store owner (email + optional SMS/WhatsApp)\n  // Also fire Web Push notification\n  pushToStoreOwner(order.storeId, PushTemplates.newOrder(\n    order.orderNumber,\n    `${order.currency} ${order.total.toFixed(2)}`\n  )).catch(() => {/* non-fatal */});\n  const owner = await prisma.user.findUnique({ where: { id: store.ownerId }, select: { email: true, name: true, phone: true } });\n  if (owner) {\n    emailService.sendNewOrderAlert({\n      ownerEmail:   owner.email,\n      ownerName:    owner.name,\n      orderNumber:  order.orderNumber,\n      customerName: order.customerName,\n      total:        order.total,\n      currency:     order.currency,\n      storeName:    store.name,\n      itemCount:    order.items.length,\n    });\n\n    notificationService.notifyOwnerNewOrder({\n      ownerPhone:   store.smsPhone   || owner.phone || null,\n      ownerWA:      store.whatsappPhone || null,\n      smsEnabled:   store.smsEnabled     && store.notifyOwnerSms,\n      waEnabled:    store.whatsappEnabled && store.notifyOwnerSms,\n      storeName:    store.name,\n      orderNumber:  order.orderNumber,\n      customerName: order.customerName,\n      total:        order.total,\n      currency:     order.currency,\n      itemCount:    order.items.length,\n      storeSlug:    store.slug,\n    });\n  }\n\n  return res.status(201).json({ success: true, message: \"Order created\", data: order });\n};\n\n// Get orders for a store\nexport const getOrders = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { page = 1, limit = 20, status, search } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = { storeId };\n  if (status) where.status = status;\n  if (search) where.OR = [\n    { orderNumber: { contains: search as string, mode: \"insensitive\" } },\n    { customerEmail: { contains: search as string, mode: \"insensitive\" } },\n    { customerName:  { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  const [orders, total] = await Promise.all([\n    await prisma.order.findMany({\n      where, take, skip,\n      include: { items: true, payment: { select: { gateway: true, status: true } } },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.order.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: orders,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// Get single order\nexport const getOrder = async (req: AuthRequest, res: Response) => {\n  const { storeId, orderId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const order = await prisma.order.findFirst({\n    where: { id: orderId, storeId },\n    include: { items: { include: { product: { select: { name: true, images: true } } } }, payment: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  return res.json({ success: true, data: order });\n};\n\n// Update order status\nexport const updateOrderStatus = async (req: AuthRequest, res: Response) => {\n  const { storeId, orderId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { status, trackingNumber, trackingUrl, cancelReason } = z.object({\n    status:         z.enum([\"PENDING\",\"PROCESSING\",\"SHIPPED\",\"DELIVERED\",\"COMPLETED\",\"CANCELLED\"]),\n    trackingNumber: z.string().optional(),\n    trackingUrl:    z.string().optional(),\n    cancelReason:   z.string().optional(),\n  }).parse(req.body);\n\n  const order = await prisma.order.findFirst({ where: { id: orderId, storeId } });\n  if (!order) throw new AppError(\"Order not found\", 404);\n\n  const updated = await prisma.order.update({\n    where: { id: orderId },\n    data:  { status, trackingNumber, trackingUrl, cancelReason },\n  });\n\n  // Email + SMS notification to customer\n  await emailService.sendOrderStatusUpdate(\n    order.customerEmail,\n    order.customerName,\n    order.orderNumber,\n    status,\n    trackingNumber\n  );\n\n  const statusStore = await prisma.store.findUnique({\n    where: { id: updated.storeId },\n    select: { notifyCustomerSms: true, slug: true, name: true },\n  });\n  if (statusStore) {\n    notificationService.notifyCustomerStatusUpdate({\n      customerPhone:  order.customerPhone || null,\n      smsEnabled:     statusStore.notifyCustomerSms ?? false,\n      storeName:      statusStore.name,\n      orderNumber:    order.orderNumber,\n      status,\n      trackingNumber: trackingNumber || null,\n      storeSlug:      statusStore.slug,\n    });\n  }\n\n  // Auto-fulfillment: when order moves to PROCESSING, forward to suppliers\n  if (status === \"PROCESSING\") {\n    try {\n      const orderWithItems = await prisma.order.findUnique({\n        where:   { id: orderId },\n        include: { items: { include: { product: { include: { supplierProducts: { include: { supplier: true } } } } } } },\n      });\n      const storeData = await prisma.store.findUnique({ where: { id: storeId }, select: { name: true } });\n\n      if (orderWithItems) {\n        // Group by supplier and auto-fulfill if enabled\n        const bySupplier = new Map<string, { supplier: any; items: typeof orderWithItems.items }>();\n        for (const item of orderWithItems.items) {\n          const link = item.product.supplierProducts?.[0];\n          if (!link?.supplier?.autoFulfill) continue;\n          const sup = link.supplier;\n          if (!bySupplier.has(sup.id)) bySupplier.set(sup.id, { supplier: sup, items: [] });\n          bySupplier.get(sup.id)!.items.push(item);\n        }\n\n        for (const [, { supplier, items }] of bySupplier) {\n          const payload: FulfillmentPayload = {\n            orderNumber:     updated.orderNumber,\n            orderId:         updated.id,\n            customerName:    updated.customerName,\n            customerEmail:   updated.customerEmail,\n            customerPhone:   updated.customerPhone ?? null,\n            shippingAddress: updated.shippingAddress,\n            storeName:       storeData?.name ?? storeId,\n            storeId,\n            total:           updated.total,\n            currency:        updated.currency,\n            notes:           updated.notes ?? null,\n            items: items.map(i => ({\n              name:        i.name,\n              sku:         i.sku ?? null,\n              quantity:    i.quantity,\n              price:       i.price,\n              supplierSku: i.product.supplierProducts?.[0]?.supplierSku ?? null,\n              supplierUrl: i.product.supplierProducts?.[0]?.supplierUrl ?? null,\n            })),\n          };\n\n          let method = \"MANUAL\";\n          let success = false;\n          if (supplier.webhookUrl) {\n            method = \"WEBHOOK\";\n            success = await supplierService.fulfillOrderByWebhook(supplier.webhookUrl, payload);\n          } else if (supplier.fulfillEmail) {\n            method = \"EMAIL\";\n            success = await supplierService.fulfillOrderByEmail(supplier.fulfillEmail, supplier.name, payload);\n          } else {\n            method = \"MANUAL\"; success = true;\n          }\n\n          await prisma.fulfillmentOrder.create({\n            data: {\n              orderId:    updated.id,\n              supplierId: supplier.id,\n              storeId,\n              status:     success ? \"SENT\" : \"FAILED\",\n              sentAt:     success ? new Date() : undefined,\n              method,\n              payload:    payload as any,\n            },\n          });\n        }\n      }\n    } catch (err: any) {\n      // Non-blocking — never fail the status update because of fulfillment\n      logger.warn(`[AutoFulfill] Error: ${err.message}`);\n    }\n  }\n\n  return res.json({ success: true, message: \"Order status updated\", data: updated });\n};\n\n// Get single order by order number (for customer tracking)\nexport const trackOrder = async (req: Request, res: Response) => {\n  const { orderNumber } = req.params;\n  const order = await prisma.order.findUnique({\n    where: { orderNumber },\n    select: {\n      orderNumber: true,\n      status:      true,\n      total:       true,\n      currency:    true,\n      trackingNumber: true,\n      trackingUrl: true,\n      createdAt:   true,\n      items: {\n        select: { name: true, quantity: true, price: true, image: true },\n      },\n    },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  return res.json({ success: true, data: order });\n};\n","backend/src/controllers/payment.controller.ts":"// src/controllers/payment.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { calculateFee, detectGateway } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport {\n  createStripePaymentIntent, constructStripeEvent,\n  initializePaystack, verifyPaystack, verifyPaystackWebhook,\n  initializeFlutterwave, verifyFlutterwave, verifyFlutterwaveWebhook,\n} from \"../services/payment.service\";\nimport { emailService } from \"../services/email.service\";\nimport { logger } from \"../utils/logger\";\n\n// ── Initialize Payment ────────────────────────────────────────────────────────\nexport const initializePayment = async (req: Request, res: Response) => {\n  const schema = z.object({\n    orderId:   z.string().uuid(),\n    gateway:   z.enum([\"STRIPE\",\"PAYSTACK\",\"FLUTTERWAVE\"]).optional(),\n    country:   z.string().optional(),\n  });\n  const { orderId, gateway: manualGateway, country } = schema.parse(req.body);\n\n  const order = await prisma.order.findUnique({\n    where: { id: orderId },\n    include: { store: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  if (order.payment) throw new AppError(\"Payment already initiated for this order\", 400);\n\n  // Auto-detect gateway\n  const gateway = manualGateway || detectGateway(country);\n\n  const feePercent = await getPlatformFee();\n  const { platformFee, storeEarnings } = calculateFee(order.total, feePercent);\n\n  const frontendUrl = process.env.FRONTEND_URL || \"http://localhost:3000\";\n  const storeSlug   = order.store?.slug || \"\";\n  // Correct callback URL: points to the actual payment/callback page with real orderId\n  const callbackUrl = `${frontendUrl}/store/${storeSlug}/payment/callback?orderId=${orderId}`;\n\n  let initData: any = {};\n\n  if (gateway === \"STRIPE\") {\n    initData = await createStripePaymentIntent({\n      amount:        order.total,\n      currency:      order.currency,\n      orderId:       order.id,\n      storeId:       order.storeId,\n      customerEmail: order.customerEmail,\n    });\n  } else if (gateway === \"PAYSTACK\") {\n    initData = await initializePaystack({\n      amount:      order.total,\n      currency:    order.currency === \"NGN\" ? \"NGN\" : \"NGN\",\n      email:       order.customerEmail,\n      orderId:     order.id,\n      storeId:     order.storeId,\n      callbackUrl,\n    });\n  } else if (gateway === \"FLUTTERWAVE\") {\n    initData = await initializeFlutterwave({\n      amount:      order.total,\n      currency:    order.currency,\n      email:       order.customerEmail,\n      name:        order.customerName,\n      phone:       order.customerPhone || undefined,\n      orderId:     order.id,\n      storeId:     order.storeId,\n      redirectUrl: callbackUrl,\n    });\n  }\n\n  // Create pending payment record\n  await prisma.payment.create({\n    data: {\n      orderId,\n      storeId:           order.storeId,\n      gateway:           gateway as any,\n      amount:            order.total,\n      currency:          order.currency,\n      platformFee,\n      platformFeePercent: feePercent,\n      storeEarnings,\n      status:            \"PENDING\",\n      metadata:          initData,\n    },\n  });\n\n  return res.json({\n    success: true,\n    data: { gateway, ...initData, amount: order.total, currency: order.currency },\n  });\n};\n\n// ── Stripe Webhook ────────────────────────────────────────────────────────────\nexport const stripeWebhook = async (req: Request, res: Response) => {\n  const sig = req.headers[\"stripe-signature\"] as string;\n  const event = constructStripeEvent(req.body as Buffer, sig);\n\n  if (event.type === \"payment_intent.succeeded\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await completePayment(orderId, intent.id, \"STRIPE\");\n  }\n\n  if (event.type === \"payment_intent.payment_failed\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await failPayment(orderId, \"STRIPE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Paystack Webhook ──────────────────────────────────────────────────────────\nexport const paystackWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"x-paystack-signature\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (!verifyPaystackWebhook(payload, sig)) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.event === \"charge.success\") {\n    const orderId = event.data?.metadata?.orderId;\n    if (orderId) await completePayment(orderId, event.data.reference, \"PAYSTACK\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Flutterwave Webhook ───────────────────────────────────────────────────────\nexport const flutterwaveWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"verif-hash\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (sig !== process.env.FLUTTERWAVE_SECRET_KEY) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.status === \"successful\") {\n    const orderId = event.meta?.orderId;\n    if (orderId) await completePayment(orderId, String(event.id), \"FLUTTERWAVE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Verify Payment (after redirect) ──────────────────────────────────────────\nexport const verifyPayment = async (req: Request, res: Response) => {\n  const { orderId, reference, transaction_id } = req.query;\n  if (!orderId) throw new AppError(\"orderId required\", 400);\n\n  const payment = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n  if (!payment) throw new AppError(\"Payment not found\", 404);\n\n  if (payment.status === \"SUCCESS\") {\n    return res.json({ success: true, data: { status: \"SUCCESS\", payment } });\n  }\n\n  // Verify with gateway\n  if (payment.gateway === \"PAYSTACK\" && reference) {\n    const result = await verifyPaystack(reference as string);\n    if (result.status === \"success\") {\n      await completePayment(orderId as string, result.reference, \"PAYSTACK\");\n    }\n  }\n\n  if (payment.gateway === \"FLUTTERWAVE\" && transaction_id) {\n    const result = await verifyFlutterwave(transaction_id as string);\n    if (result.status === \"successful\") {\n      await completePayment(orderId as string, String(result.id), \"FLUTTERWAVE\");\n    }\n  }\n\n  const updated = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n\n  // Return order data alongside payment so the callback page can render the success screen\n  const orderData = await prisma.order.findUnique({\n    where:   { id: orderId as string },\n    include: { items: true, store: { select: { name: true, slug: true, primaryColor: true } } },\n  });\n\n  return res.json({ success: true, data: { ...updated, order: orderData } });\n};\n\n// ── Admin: Get All Payments ───────────────────────────────────────────────────\nexport const getAllPayments = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, gateway } = req.query;\n  const take = Math.min(Number(limit), 100);\n  const skip = (Math.max(Number(page), 1) - 1) * take;\n\n  const where: any = {};\n  if (status)  where.status  = status;\n  if (gateway) where.gateway = gateway;\n\n  const [payments, total] = await Promise.all([\n    await prisma.payment.findMany({\n      where, take, skip,\n      include: {\n        order: { select: { orderNumber: true, customerName: true, customerEmail: true } },\n        store: { select: { name: true, owner: { select: { name: true, email: true } } } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.payment.count({ where }),\n  ]);\n\n  const totals = await prisma.payment.aggregate({\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: payments,\n    totals: totals._sum,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Helpers ──────────────────────────────────────────────────────────────────\nasync function getPlatformFee(): Promise<number> {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return settings?.platformFeePercent || Number(process.env.PLATFORM_FEE_PERCENT || 10);\n}\n\nasync function completePayment(orderId: string, reference: string, gateway: string) {\n  try {\n    await prisma.$transaction([\n      prisma.payment.update({\n        where: { orderId },\n        data:  { status: \"SUCCESS\", gatewayReference: reference, paidAt: new Date() },\n      }),\n      prisma.order.update({\n        where: { id: orderId },\n        data:  { status: \"PROCESSING\" },\n      }),\n    ]);\n\n    const order = await prisma.order.findUnique({\n      where: { id: orderId },\n      include: { store: true, items: true },\n    });\n    if (order) {\n      // ── Customer confirmation email (with real line items) ─────────────────\n      await emailService.sendOrderConfirmation({\n        email:       order.customerEmail,\n        name:        order.customerName,\n        orderNumber: order.orderNumber,\n        total:       order.total,\n        currency:    order.currency,\n        storeName:   order.store?.name || \"Store\",\n        storeEmail:  order.store?.supportEmail || undefined,\n        items:       (order.items as any[]).map(i => ({\n          name:     i.name,\n          quantity: i.quantity,\n          price:    i.price,\n        })),\n      });\n\n      // ── Store owner new-order alert ────────────────────────────────────────\n      const owner = await prisma.user.findUnique({\n        where:  { id: order.store!.ownerId },\n        select: { email: true, name: true, phone: true },\n      });\n      if (owner) {\n        emailService.sendNewOrderAlert({\n          ownerEmail:   owner.email,\n          ownerName:    owner.name,\n          orderNumber:  order.orderNumber,\n          customerName: order.customerName,\n          total:        order.total,\n          currency:     order.currency,\n          storeName:    order.store!.name,\n          itemCount:    (order.items as any[]).length,\n        }).catch(() => {/* non-fatal */});\n      }\n\n      // ── Update customer spend stats ────────────────────────────────────────\n      if (order.customerId) {\n        await prisma.storeCustomer.update({\n          where: { id: order.customerId },\n          data: {\n            totalSpent: { increment: order.total },\n            orderCount: { increment: 1 },\n          },\n        });\n      }\n    }\n  } catch (err) {\n    logger.error(\"completePayment error:\", err);\n  }\n}\n\nasync function failPayment(orderId: string, gateway: string) {\n  try {\n    await prisma.payment.update({\n      where: { orderId },\n      data:  { status: \"FAILED\" },\n    });\n    logger.warn(`Payment failed for order ${orderId} via ${gateway}`);\n\n    // Notify customer\n    const order = await prisma.order.findUnique({\n      where:   { id: orderId },\n      include: { store: true },\n    });\n    if (order) {\n      const { emailService } = await import(\"../services/email.service\");\n      emailService.sendPaymentFailed(\n        order.customerEmail,\n        order.customerName,\n        order.orderNumber,\n        `$${order.total.toFixed(2)}`,\n        order.store?.name || \"Store\"\n      );\n    }\n  } catch (err) {\n    logger.error(\"failPayment error:\", err);\n  }\n}\n","backend/src/controllers/product.controller.ts":"// src/controllers/product.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { slugify, paginate } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { requireStoreOwner } from \"./store.controller\";\n\nconst productSchema = z.object({\n  name:          z.string().min(2).max(200),\n  description:   z.string().optional(),\n  price:         z.number().positive(),\n  comparePrice:  z.number().optional(),\n  costPrice:     z.number().optional(),\n  sku:           z.string().optional(),\n  barcode:       z.string().optional(),\n  inventory:     z.number().int().min(0).default(0),\n  trackInventory:z.boolean().default(true),\n  allowBackorder:z.boolean().default(false),\n  images:        z.array(z.string()).default([]),\n  category:      z.string().optional(),\n  tags:          z.array(z.string()).default([]),\n  status:        z.enum([\"ACTIVE\",\"DRAFT\",\"ARCHIVED\"]).default(\"DRAFT\"),\n  isDigital:     z.boolean().default(false),\n  weight:        z.number().optional(),\n  metaTitle:     z.string().optional(),\n  metaDescription: z.string().optional(),\n});\n\nexport const createProduct = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  // Check product limits\n  const sub = await prisma.subscription.findUnique({ where: { userId: req.user!.userId } });\n  const limits: Record<string, number> = { STARTER: 50, PRO: 500, ADVANCED: 999999 };\n  const max = limits[sub?.plan || \"STARTER\"];\n  const count = await prisma.product.count({ where: { storeId } });\n  if (count >= max) throw new AppError(`Product limit (${max}) reached for your plan`, 403);\n\n  const data = productSchema.parse(req.body);\n  const slug = await uniqueProductSlug(storeId, slugify(data.name));\n\n  const product = await prisma.product.create({\n    data: { ...data, storeId, slug },\n  });\n\n  return res.status(201).json({ success: true, message: \"Product created\", data: product });\n};\n\nexport const getProducts = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { page = 1, limit = 20, status, search, category } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = { storeId };\n  if (status)   where.status   = status;\n  if (category) where.category = category;\n  if (search)   where.name = { contains: search as string, mode: \"insensitive\" };\n\n  const [products, total] = await Promise.all([\n    await prisma.product.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.product.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: products,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\nexport const getProduct = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const product = await prisma.product.findFirst({\n    where: { id: productId, storeId },\n    include: { variants: true },\n  });\n  if (!product) throw new AppError(\"Product not found\", 404);\n  return res.json({ success: true, data: product });\n};\n\nexport const updateProduct = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const product = await prisma.product.findFirst({ where: { id: productId, storeId } });\n  if (!product) throw new AppError(\"Product not found\", 404);\n\n  const data = productSchema.partial().parse(req.body);\n  const updated = await prisma.product.update({ where: { id: productId }, data });\n  return res.json({ success: true, message: \"Product updated\", data: updated });\n};\n\nexport const deleteProduct = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const product = await prisma.product.findFirst({ where: { id: productId, storeId } });\n  if (!product) throw new AppError(\"Product not found\", 404);\n\n  await prisma.product.delete({ where: { id: productId } });\n  return res.json({ success: true, message: \"Product deleted\" });\n};\n\n// Bulk create from CSV data — returns per-row success/failure details\nexport const bulkCreateProducts = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const store = await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  // Check plan limits before doing anything\n  const sub  = await prisma.subscription.findUnique({ where: { userId: req.user!.userId } });\n  const plan = sub?.plan || \"STARTER\";\n  const limits: Record<string, number> = { STARTER: 50, PRO: 500, ADVANCED: 999999 };\n  const maxProducts  = limits[plan] ?? 50;\n  const currentCount = await prisma.product.count({ where: { storeId } });\n  const remainingSlots = maxProducts - currentCount;\n\n  const rawProducts = z.object({\n    products: z.array(z.any()).max(500),\n  }).parse(req.body).products;\n\n  if (rawProducts.length > remainingSlots) {\n    return res.status(403).json({\n      success: false,\n      message: `Your ${plan} plan allows ${maxProducts} products. You have ${currentCount} and are trying to add ${rawProducts.length} more (only ${remainingSlots} slots left).`,\n      data: [],\n    });\n  }\n\n  const results: Array<{ index: number; success: boolean; name?: string; error?: string }> = [];\n  const created: any[] = [];\n\n  for (let i = 0; i < rawProducts.length; i++) {\n    try {\n      const parsed = productSchema.parse(rawProducts[i]);\n      const slug   = await uniqueProductSlug(storeId, slugify(parsed.name));\n      const product = await prisma.product.create({ data: { ...parsed, storeId, slug } });\n      created.push(product);\n      results.push({ index: i, success: true, name: parsed.name });\n    } catch (err: any) {\n      const msg = err?.errors?.[0]?.message || err?.message || \"Invalid product data\";\n      results.push({ index: i, success: false, name: rawProducts[i]?.name || `Row ${i+1}`, error: msg });\n    }\n  }\n\n  const failCount = results.filter(r => !r.success).length;\n  return res.status(201).json({\n    success: true,\n    message: `${created.length} created${failCount > 0 ? `, ${failCount} failed` : \"\"}`,\n    data: created,\n    results,\n    summary: { total: rawProducts.length, created: created.length, failed: failCount },\n  });\n};\n\n// Public product listing\nexport const getPublicProducts = async (req: Request, res: Response) => {\n  const { storeId } = req.params;\n  const { page = 1, limit = 20, category, search, minPrice, maxPrice } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = { storeId, status: \"ACTIVE\" };\n  if (category) where.category = category;\n  if (search)   where.name = { contains: search as string, mode: \"insensitive\" };\n  if (minPrice || maxPrice) {\n    where.price = {};\n    if (minPrice) where.price.gte = Number(minPrice);\n    if (maxPrice) where.price.lte = Number(maxPrice);\n  }\n\n  const [products, total] = await Promise.all([\n    await prisma.product.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.product.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: products,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// Public single product\nexport const getPublicProduct = async (req: Request, res: Response) => {\n  const { storeId, slug } = req.params;\n  // Accept both slug and UUID id\n  const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(slug);\n  const product = await prisma.product.findFirst({\n    where: isUUID\n      ? { storeId, id: slug, status: \"ACTIVE\" }\n      : { storeId, slug, status: \"ACTIVE\" },\n    include: { variants: true },\n  });\n  if (!product) throw new AppError(\"Product not found\", 404);\n  return res.json({ success: true, data: product });\n};\n\nasync function uniqueProductSlug(storeId: string, base: string): Promise<string> {\n  let slug = base, i = 1;\n  while (await prisma.product.findFirst({ where: { storeId, slug } })) {\n    slug = `${base}-${i++}`;\n  }\n  return slug;\n}\n\n// ─── Product Variants ─────────────────────────────────────────────────────────\n\nconst variantSchema = z.object({\n  name:      z.string().min(1),  // e.g. \"Size\", \"Color\"\n  value:     z.string().min(1),  // e.g. \"L\", \"Red\"\n  price:     z.number().optional(),\n  inventory: z.number().int().min(0).default(0),\n  sku:       z.string().optional(),\n  image:     z.string().optional(),\n});\n\nexport const createVariant = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  const data = variantSchema.parse(req.body);\n  const variant = await prisma.productVariant.create({ data: { productId, ...data } });\n  res.status(201).json({ success: true, data: variant });\n};\n\nexport const updateVariant = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId, variantId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  const data = variantSchema.partial().parse(req.body);\n  const variant = await prisma.productVariant.update({ where: { id: variantId }, data });\n  res.json({ success: true, data: variant });\n};\n\nexport const deleteVariant = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId, variantId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  await prisma.productVariant.delete({ where: { id: variantId } });\n  res.json({ success: true });\n};\n\nexport const getVariants = async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  const variants = await prisma.productVariant.findMany({ where: { productId }, orderBy: { createdAt: \"asc\" } });\n  res.json({ success: true, data: variants });\n};","backend/src/controllers/product.intel.controller.ts":"// ============================================================\n// Product Intel Controller + Routes\n// Path: backend/src/controllers/product.intel.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { analyseProductFull, importReviewsFromUrl, generateMarketingAngles } from \"../services/kai.product.intel.service\";\nimport { scrapeProductFromUrl } from \"../services/forecast.service\";\nimport prisma from \"../lib/prisma\";\n\n// ── POST /api/products/analyse ────────────────────────────────\n// Scrape + Score + Angles in one call\nexport async function analyseProduct(req: Request, res: Response) {\n  try {\n    const { url, storeId } = req.body;\n    if (!url) return res.status(400).json({ success: false, message: \"URL required\" });\n\n    const store = await prisma.store.findUnique({\n      where:  { id: storeId },\n      select: { country: true },\n    });\n\n    const apiKey = process.env.ANTHROPIC_API_KEY || \"\";\n\n    // Step 1: Scrape the product\n    const scrapedData = await scrapeProductFromUrl(url, store?.country || \"NG\", apiKey);\n\n    // Step 2: Score + Angles in parallel\n    const result = await analyseProductFull({ url, storeId, scrapedData });\n\n    res.json({ success: true, data: result });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message || \"Analysis failed\" });\n  }\n}\n\n// ── POST /api/products/angles ─────────────────────────────────\n// Generate angles for an already-scraped product\nexport async function getAngles(req: Request, res: Response) {\n  try {\n    const { productName, productDesc, category, country } = req.body;\n    const angles = await generateMarketingAngles({ productName, productDesc, category, country });\n    res.json({ success: true, data: angles });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/products/import-reviews ────────────────────────\nexport async function importReviews(req: Request, res: Response) {\n  try {\n    const { url, storeId, productId, count } = req.body;\n    if (!url || !productId) return res.status(400).json({ success: false, message: \"url and productId required\" });\n\n    const result = await importReviewsFromUrl({ url, storeId, productId, count });\n    res.json({ success: true, data: result });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/products/import-confirmed ──────────────────────\n// Full import: scrape → confirm angle → save product + reviews\nexport async function importConfirmed(req: Request, res: Response) {\n  try {\n    const { storeId, scrapedData, selectedAngle, sellingPrice, importReviews: doReviews } = req.body;\n    const user = (req as any).user;\n\n    // Verify store ownership\n    const store = await prisma.store.findFirst({\n      where: { id: storeId, ownerId: user.id },\n      select: { id: true, country: true },\n    });\n    if (!store) return res.status(403).json({ success: false, message: \"Not your store\" });\n\n    // Create the product\n    const product = await prisma.product.create({\n      data: {\n        storeId,\n        name:          scrapedData.name,\n        description:   scrapedData.description,\n        shortDesc:     scrapedData.shortDescription,\n        price:         Number(sellingPrice || scrapedData.suggestedLocalPrice?.replace(/[^\\d]/g, \"\") || 0),\n        costPrice:     scrapedData.supplierCostLocal || 0,\n        stockQuantity: 50,\n        category:      scrapedData.category || \"General\",\n        tags:          scrapedData.tags || [],\n        images:        scrapedData.images || [],\n        sourceUrl:     scrapedData.supplierUrl,\n        seoTitle:      scrapedData.seoTitle,\n        seoDescription: scrapedData.seoDescription,\n        isActive:      true,\n        metadata: {\n          angle:           selectedAngle,\n          bulletPoints:    scrapedData.bulletPoints,\n          specifications:  scrapedData.specifications,\n          importedAt:      new Date().toISOString(),\n          supplierName:    scrapedData.supplierName,\n          whyItSells:      scrapedData.whyItSells,\n        } as any,\n      },\n    });\n\n    let reviewsImported = 0;\n\n    // Import reviews if requested\n    if (doReviews && scrapedData.supplierUrl) {\n      const apiKey = process.env.ANTHROPIC_API_KEY || \"\";\n      const reviewResult = await importReviewsFromUrl({\n        url:       scrapedData.supplierUrl,\n        storeId,\n        productId: product.id,\n        count:     8,\n      });\n      reviewsImported = reviewResult.imported;\n    }\n\n    res.json({\n      success: true,\n      data: { product, reviewsImported },\n      message: `Product added${reviewsImported > 0 ? ` with ${reviewsImported} imported reviews` : \"\"}`,\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── Routes ────────────────────────────────────────────────────\nimport { Router }    from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport rateLimit     from \"express-rate-limit\";\n\nconst router   = Router();\nconst aiLimit  = rateLimit({ windowMs: 60000, max: 10 });\n\nrouter.use(authenticate);\nrouter.post(\"/analyse\",          aiLimit, analyseProduct);\nrouter.post(\"/angles\",           aiLimit, getAngles);\nrouter.post(\"/import-reviews\",   aiLimit, importReviews);\nrouter.post(\"/import-confirmed\",          importConfirmed);\n\nexport default router;\n\n// Add to app.ts:\n// import productIntelRoutes from \"./controllers/product.intel.controller\";\n// app.use(\"/api/products/intel\", productIntelRoutes);\n","backend/src/controllers/productSubscription.controller.ts":"// src/controllers/productSubscription.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\n\nconst createSchema = z.object({\n  productId:     z.string().uuid(),\n  customerEmail: z.string().email(),\n  interval:      z.enum([\"weekly\",\"monthly\",\"quarterly\"]),\n  intervalCount: z.number().int().positive().default(1),\n  discount:      z.number().min(0).max(100).default(0),\n});\n\nfunction nextBillingDate(interval: string, count: number): Date {\n  const d = new Date();\n  if (interval === \"weekly\") d.setDate(d.getDate() + 7 * count);\n  else if (interval === \"monthly\") d.setMonth(d.getMonth() + count);\n  else d.setMonth(d.getMonth() + 3 * count);\n  return d;\n}\n\n// POST /subscriptions/:storeId  — customer subscribes\nexport const createProductSubscription = async (req: Request, res: Response) => {\n  const { storeId } = req.params;\n  const data = createSchema.parse(req.body);\n\n  const product = await prisma.product.findFirst({ where: { id: data.productId, storeId, status: \"ACTIVE\" } });\n  if (!product) throw new AppError(\"Product not found\", 404);\n\n  const existing = await prisma.productSubscription.findFirst({\n    where: { storeId, productId: data.productId, customerEmail: data.customerEmail, status: \"ACTIVE\" },\n  });\n  if (existing) throw new AppError(\"You already have an active subscription for this product\", 409);\n\n  const discountedPrice = product.price * (1 - data.discount / 100);\n\n  const sub = await prisma.productSubscription.create({\n    data: {\n      storeId, productId: data.productId, customerEmail: data.customerEmail,\n      interval: data.interval, intervalCount: data.intervalCount,\n      price: discountedPrice, currency: \"USD\", discount: data.discount,\n      nextBillingAt: nextBillingDate(data.interval, data.intervalCount),\n    },\n  });\n\n  res.status(201).json({ success: true, data: sub, message: `Subscribed! You'll be charged $${discountedPrice.toFixed(2)} ${data.interval}.` });\n};\n\n// GET /subscriptions/:storeId  — store owner views all\nexport const getProductSubscriptions = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: req.user!.userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n\n  const subs = await prisma.productSubscription.findMany({\n    where: { storeId }, orderBy: { createdAt: \"desc\" },\n  });\n\n  const stats = {\n    total: subs.length,\n    active: subs.filter(s => s.status === \"ACTIVE\").length,\n    mrr: subs.filter(s => s.status === \"ACTIVE\" && s.interval === \"monthly\").reduce((sum, s) => sum + s.price, 0),\n  };\n\n  res.json({ success: true, data: subs, stats });\n};\n\n// PATCH /subscriptions/:storeId/:subId  — pause/cancel\nexport const updateProductSubscription = async (req: AuthRequest, res: Response) => {\n  const { storeId, subId } = req.params;\n  const { status } = req.body;\n\n  const updated = await prisma.productSubscription.update({\n    where: { id: subId }, data: { status },\n  });\n\n  res.json({ success: true, data: updated });\n};\n","backend/src/controllers/refund.controller.ts":"// src/controllers/refund.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\n\nconst createRefundSchema = z.object({\n  amount:      z.number().positive(),\n  reason:      z.enum([\"DAMAGED\",\"NOT_RECEIVED\",\"WRONG_ITEM\",\"NOT_AS_DESCRIBED\",\"CHANGED_MIND\",\"OTHER\"]),\n  description: z.string().optional(),\n  photos:      z.array(z.string()).default([]),\n});\n\nconst processRefundSchema = z.object({\n  status:    z.enum([\"APPROVED\",\"REJECTED\"]),\n  adminNote: z.string().optional(),\n});\n\n// POST /refunds/:storeId/:orderId  — store owner requests or customer requests\nexport const createRefund = async (req: AuthRequest, res: Response) => {\n  const { storeId, orderId } = req.params;\n  const data = createRefundSchema.parse(req.body);\n\n  const order = await prisma.order.findFirst({ where: { id: orderId, storeId } });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  if (![\"COMPLETED\",\"DELIVERED\"].includes(order.status)) throw new AppError(\"Order must be completed/delivered to refund\", 400);\n\n  const existing = await prisma.refund.findFirst({ where: { orderId, status: { in: [\"PENDING\",\"APPROVED\"] } } });\n  if (existing) throw new AppError(\"A refund request already exists for this order\", 409);\n\n  if (data.amount > order.total) throw new AppError(\"Refund amount exceeds order total\", 400);\n\n  const refund = await prisma.refund.create({\n    data: { orderId, storeId, amount: data.amount, reason: data.reason, description: data.description, photos: data.photos },\n  });\n\n  // Notify store owner (in-app)\n  const storeForNotif = await prisma.store.findUnique({ where: { id: order.storeId }, select: { ownerId: true } });\n  if (storeForNotif?.ownerId) {\n    await prisma.notification.create({\n      data: {\n        userId: storeForNotif.ownerId, type: \"warning\",\n        title: \"Refund Request\",\n        message: `Refund of $${data.amount.toFixed(2)} requested for order ${order.orderNumber}`,\n        link: `/dashboard/refunds`,\n      },\n    }).catch(() => {}); // non-blocking\n  }\n\n  res.status(201).json({ success: true, data: refund });\n};\n\n// GET /refunds/:storeId\nexport const getRefunds = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const { status, page = 1, limit = 20 } = req.query as any;\n\n  const where: any = { storeId };\n  if (status) where.status = status;\n\n  const [refunds, total] = await Promise.all([\n    prisma.refund.findMany({\n      where, skip: (Number(page) - 1) * Number(limit), take: Number(limit),\n      orderBy: { createdAt: \"desc\" },\n      include: { order: { select: { orderNumber: true, customerName: true, customerEmail: true, total: true } } },\n    }),\n    prisma.refund.count({ where }),\n  ]);\n\n  res.json({ success: true, data: refunds, pagination: { total, page: Number(page), pages: Math.ceil(total / Number(limit)) } });\n};\n\n// PATCH /refunds/:storeId/:refundId/process — store owner approves/rejects\nexport const processRefund = async (req: AuthRequest, res: Response) => {\n  const { storeId, refundId } = req.params;\n  const data = processRefundSchema.parse(req.body);\n\n  const refund = await prisma.refund.findFirst({ where: { id: refundId, storeId }, include: { order: true } });\n  if (!refund) throw new AppError(\"Refund not found\", 404);\n  if (refund.status !== \"PENDING\") throw new AppError(\"Refund already processed\", 400);\n\n  const updated = await prisma.refund.update({\n    where: { id: refundId },\n    data: { status: data.status, adminNote: data.adminNote, processedAt: new Date() },\n  });\n\n  if (data.status === \"APPROVED\") {\n    // Update order status to REFUNDED\n    await prisma.order.update({ where: { id: refund.orderId }, data: { status: \"REFUNDED\", refundAmount: refund.amount } });\n    // Update payment status\n    await prisma.payment.updateMany({ where: { orderId: refund.orderId }, data: { status: \"REFUNDED\", refundedAt: new Date() } });\n    // Email customer\n    await emailService.send({\n      to: refund.order.customerEmail,\n      subject: `Refund Approved — ${refund.order.orderNumber}`,\n      html: `<p>Hi ${refund.order.customerName},</p><p>Your refund of <strong>$${refund.amount.toFixed(2)}</strong> for order <strong>${refund.order.orderNumber}</strong> has been approved. Funds will appear within 5-10 business days.</p>`,\n    });\n  } else {\n    await emailService.send({\n      to: refund.order.customerEmail,\n      subject: `Refund Update — ${refund.order.orderNumber}`,\n      html: `<p>Hi ${refund.order.customerName},</p><p>Unfortunately your refund request for order <strong>${refund.order.orderNumber}</strong> was not approved.</p>${data.adminNote ? `<p>Reason: ${data.adminNote}</p>` : \"\"}`,\n    });\n  }\n\n  res.json({ success: true, data: updated });\n};\n\n// Customer-side: submit refund request publicly\nexport const customerRequestRefund = async (req: Request, res: Response) => {\n  const { orderNumber } = req.params;\n  const data = createRefundSchema.parse(req.body);\n\n  const order = await prisma.order.findUnique({ where: { orderNumber } });\n  if (!order) throw new AppError(\"Order not found\", 404);\n\n  const existing = await prisma.refund.findFirst({ where: { orderId: order.id, status: { in: [\"PENDING\",\"APPROVED\"] } } });\n  if (existing) throw new AppError(\"Refund already requested\", 409);\n\n  const refund = await prisma.refund.create({\n    data: { orderId: order.id, storeId: order.storeId, amount: data.amount, reason: data.reason, description: data.description, photos: data.photos },\n  });\n\n  res.status(201).json({ success: true, data: refund, message: \"Refund request submitted. You'll be contacted within 2 business days.\" });\n};\n","backend/src/controllers/returns.controller.ts":"// src/controllers/returns.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\n\nconst createReturnSchema = z.object({\n  customerEmail: z.string().email(),\n  reason:        z.string().min(5),\n  description:   z.string().optional(),\n  photos:        z.array(z.string()).default([]),\n});\n\n// POST /returns/:orderNumber  — public, customer submits\nexport const requestReturn = async (req: Request, res: Response) => {\n  const { orderNumber } = req.params;\n  const data = createReturnSchema.parse(req.body);\n\n  const order = await prisma.order.findUnique({ where: { orderNumber } });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  if (order.customerEmail !== data.customerEmail) throw new AppError(\"Email does not match order\", 400);\n  if (![\"COMPLETED\",\"DELIVERED\"].includes(order.status)) throw new AppError(\"Order must be completed to request a return\", 400);\n\n  const existing = await prisma.returnRequest.findFirst({ where: { orderId: order.id, status: { in: [\"REQUESTED\",\"APPROVED\"] } } });\n  if (existing) throw new AppError(\"A return request already exists for this order\", 409);\n\n  const returnReq = await prisma.returnRequest.create({\n    data: { orderId: order.id, storeId: order.storeId, customerEmail: data.customerEmail, reason: data.reason, description: data.description, photos: data.photos },\n  });\n\n  // Notify store owner via email\n  const store = await prisma.store.findUnique({ where: { id: order.storeId }, select: { supportEmail: true, name: true, owner: { select: { email: true } } } });\n  await emailService.send({\n    to: store?.supportEmail || store?.owner?.email || \"\",\n    subject: `Return Request — ${orderNumber}`,\n    html: `<p>A return has been requested for order <strong>${orderNumber}</strong> by ${data.customerEmail}.</p><p>Reason: ${data.reason}</p><p>Login to your dashboard to review.</p>`,\n  });\n\n  res.status(201).json({ success: true, data: returnReq, message: \"Return request submitted. You'll hear back within 2-3 business days.\" });\n};\n\n// GET /returns/:storeId  — owner views all\nexport const getReturns = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const { status, page = 1, limit = 20 } = req.query as any;\n  const where: any = { storeId };\n  if (status) where.status = status;\n\n  const [returns, total] = await Promise.all([\n    prisma.returnRequest.findMany({\n      where, skip: (Number(page)-1)*Number(limit), take: Number(limit),\n      orderBy: { createdAt: \"desc\" },\n      include: { order: { select: { orderNumber: true, customerName: true, total: true } } },\n    }),\n    prisma.returnRequest.count({ where }),\n  ]);\n\n  res.json({ success: true, data: returns, pagination: { total, page: Number(page), pages: Math.ceil(total/Number(limit)) } });\n};\n\n// PATCH /returns/:storeId/:returnId\nexport const updateReturn = async (req: AuthRequest, res: Response) => {\n  const { storeId, returnId } = req.params;\n  const { status, adminNote, trackingNumber } = req.body;\n\n  const ret = await prisma.returnRequest.findFirst({ where: { id: returnId, storeId }, include: { order: true } });\n  if (!ret) throw new AppError(\"Return not found\", 404);\n\n  const updated = await prisma.returnRequest.update({\n    where: { id: returnId },\n    data: { status, adminNote, trackingNumber, resolvedAt: [\"APPROVED\",\"REJECTED\",\"REFUNDED\"].includes(status) ? new Date() : undefined },\n  });\n\n  await emailService.send({\n    to: ret.customerEmail,\n    subject: `Return Update — ${ret.order.orderNumber}`,\n    html: `<p>Your return request for order <strong>${ret.order.orderNumber}</strong> has been updated to: <strong>${status}</strong>.</p>${adminNote ? `<p>Note: ${adminNote}</p>` : \"\"}`,\n  });\n\n  res.json({ success: true, data: updated });\n};\n\n// ────────────────────────────────────────────────────────────────────────────\n// Flash Sale Controller\n// ────────────────────────────────────────────────────────────────────────────\n\nconst flashSaleSchema = z.object({\n  name:        z.string().min(2),\n  discountPct: z.number().min(1).max(100),\n  productIds:  z.array(z.string()).min(1),\n  startsAt:    z.string().datetime(),\n  endsAt:      z.string().datetime(),\n  bannerText:  z.string().optional(),\n});\n\nexport const createFlashSale = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const data = flashSaleSchema.parse(req.body);\n\n  const sale = await prisma.flashSale.create({\n    data: { storeId, ...data, startsAt: new Date(data.startsAt), endsAt: new Date(data.endsAt) },\n  });\n  res.status(201).json({ success: true, data: sale });\n};\n\nexport const getFlashSales = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const sales = await prisma.flashSale.findMany({ where: { storeId }, orderBy: { createdAt: \"desc\" } });\n  res.json({ success: true, data: sales });\n};\n\nexport const updateFlashSale = async (req: AuthRequest, res: Response) => {\n  const { storeId, saleId } = req.params;\n  const updated = await prisma.flashSale.update({ where: { id: saleId }, data: req.body });\n  res.json({ success: true, data: updated });\n};\n\nexport const deleteFlashSale = async (req: AuthRequest, res: Response) => {\n  const { storeId, saleId } = req.params;\n  await prisma.flashSale.deleteMany({ where: { id: saleId, storeId } });\n  res.json({ success: true });\n};\n\n// Public: get active flash sales for a store\nexport const getActiveFlashSales = async (req: Request, res: Response) => {\n  const { storeId } = req.params;\n  const now = new Date();\n  const sales = await prisma.flashSale.findMany({\n    where: { storeId, isActive: true, startsAt: { lte: now }, endsAt: { gte: now } },\n  });\n  res.json({ success: true, data: sales });\n};\n\n// ────────────────────────────────────────────────────────────────────────────\n// Store Export Controller\n// ────────────────────────────────────────────────────────────────────────────\n\nexport const exportStoreData = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const { type } = req.query as { type?: string }; // \"orders\" | \"products\" | \"customers\"\n\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: req.user!.userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n\n  if (type === \"orders\") {\n    const orders = await prisma.order.findMany({\n      where: { storeId }, orderBy: { createdAt: \"desc\" },\n      include: { items: true, payment: { select: { gateway: true, status: true } } },\n    });\n\n    const rows = orders.flatMap(o => o.items.map(item => ({\n      \"Order Number\": o.orderNumber, \"Date\": o.createdAt.toISOString().split(\"T\")[0],\n      \"Customer Name\": o.customerName, \"Customer Email\": o.customerEmail,\n      \"Product\": item.name, \"Qty\": item.quantity, \"Price\": item.price, \"Item Total\": item.total,\n      \"Order Total\": o.total, \"Status\": o.status, \"Payment\": o.payment?.gateway || \"\",\n      \"Tracking\": o.trackingNumber || \"\",\n    })));\n\n    return sendCsv(res, rows, `orders-${storeId}-${Date.now()}.csv`);\n  }\n\n  if (type === \"products\") {\n    const products = await prisma.product.findMany({ where: { storeId }, include: { variants: true } });\n    const rows = products.map(p => ({\n      \"Name\": p.name, \"SKU\": p.sku || \"\", \"Price\": p.price, \"Compare Price\": p.comparePrice || \"\",\n      \"Inventory\": p.inventory, \"Category\": p.category || \"\", \"Status\": p.status,\n      \"Description\": p.description || \"\", \"Tags\": p.tags.join(\"|\"),\n    }));\n    return sendCsv(res, rows, `products-${storeId}-${Date.now()}.csv`);\n  }\n\n  if (type === \"customers\") {\n    const customers = await prisma.storeCustomer.findMany({ where: { storeId }, orderBy: { totalSpent: \"desc\" } });\n    const rows = customers.map(c => ({\n      \"Name\": c.name, \"Email\": c.email, \"Phone\": c.phone || \"\",\n      \"Total Orders\": c.orderCount, \"Total Spent\": c.totalSpent, \"Joined\": c.createdAt.toISOString().split(\"T\")[0],\n    }));\n    return sendCsv(res, rows, `customers-${storeId}-${Date.now()}.csv`);\n  }\n\n  throw new AppError(\"type must be orders, products, or customers\", 400);\n};\n\nfunction sendCsv(res: Response, rows: Record<string, any>[], filename: string) {\n  if (!rows.length) { res.json({ success: true, data: [], message: \"No data to export\" }); return; }\n  const headers = Object.keys(rows[0]);\n  const csv = [\n    headers.join(\",\"),\n    ...rows.map(r => headers.map(h => `\"${String(r[h] ?? \"\").replace(/\"/g,'\"\"')}\"`).join(\",\"))\n  ].join(\"\\n\");\n\n  res.setHeader(\"Content-Type\", \"text/csv\");\n  res.setHeader(\"Content-Disposition\", `attachment; filename=\"${filename}\"`);\n  res.send(csv);\n}\n","backend/src/controllers/store.controller.ts":"// src/controllers/store.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { slugify, paginate } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\n\nconst storeSchema = z.object({\n  name:            z.string().min(2).max(100),\n  description:     z.string().max(500).optional(),\n  primaryColor:    z.string().optional(),\n  secondaryColor:  z.string().optional(),\n  accentColor:     z.string().optional(),\n  theme:           z.string().optional(),\n  fontFamily:      z.string().optional(),\n  borderRadius:    z.string().optional(),\n  tagline:         z.string().max(200).optional(),\n  showReviews:     z.boolean().optional(),\n  showInventory:   z.boolean().optional(),\n  productsPerRow:  z.number().min(1).max(6).optional(),\n  currency:        z.string().default(\"USD\"),\n  country:         z.string().optional(),\n  supportEmail:    z.string().email().optional().or(z.literal(\"\")),\n  supportPhone:    z.string().optional(),\n  taxRate:         z.number().min(0).max(100).optional(),\n  shippingEnabled: z.boolean().optional(),\n  freeShippingMin: z.number().optional(),\n  metaTitle:         z.string().optional(),\n  metaDescription:   z.string().optional(),\n  supportedCurrencies: z.array(z.string()).optional(),\n  autoDetectCurrency:  z.boolean().optional(),\n  smsEnabled:        z.boolean().optional(),\n  smsPhone:          z.string().optional().nullable(),\n  whatsappEnabled:   z.boolean().optional(),\n  whatsappPhone:     z.string().optional().nullable(),\n  notifyOwnerSms:    z.boolean().optional(),\n  notifyCustomerSms: z.boolean().optional(),\n});\n\n// Create store\nexport const createStore = async (req: AuthRequest, res: Response) => {\n  const data = storeSchema.parse(req.body);\n  const userId = req.user!.userId;\n\n  // Check subscription limits\n  const sub = await prisma.subscription.findUnique({ where: { userId } });\n  if (!sub) throw new AppError(\"No active subscription\", 402);\n\n  const limits: Record<string, number> = { STARTER: 1, PRO: 3, ADVANCED: 999 };\n  const maxStores = limits[sub.plan] || 1;\n\n  const existingCount = await prisma.store.count({ where: { ownerId: userId } });\n  if (existingCount >= maxStores) {\n    throw new AppError(`Your ${sub.plan} plan allows max ${maxStores} store(s). Upgrade to add more.`, 403);\n  }\n\n  const slug = await uniqueSlug(slugify(data.name));\n\n  const store = await prisma.store.create({\n    data: {\n      ...data,\n      ownerId: userId,\n      slug,\n      domain:  `${slug}.dropos.io`,\n      status:  \"ACTIVE\",\n    },\n  });\n\n  return res.status(201).json({ success: true, message: \"Store created\", data: store });\n};\n\n// Get my stores\nexport const getMyStores = async (req: AuthRequest, res: Response) => {\n  const stores = await prisma.store.findMany({\n    where: { ownerId: req.user!.userId },\n    include: {\n      _count: { select: { products: true, orders: true, customers: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n  return res.json({ success: true, data: stores });\n};\n\n// Get single store (owner)\nexport const getStore = async (req: AuthRequest, res: Response) => {\n  const store = await requireStoreOwner(req.params.id, req.user!.userId, req.user!.role);\n  const full  = await prisma.store.findUnique({\n    where: { id: store.id },\n    include: {\n      _count: { select: { products: true, orders: true, customers: true } },\n      shippingZones: true,\n    },\n  });\n  return res.json({ success: true, data: full });\n};\n\n// Update store\nexport const updateStore = async (req: AuthRequest, res: Response) => {\n  const store = await requireStoreOwner(req.params.id, req.user!.userId, req.user!.role);\n  const data  = storeSchema.partial().parse(req.body);\n\n  const updated = await prisma.store.update({ where: { id: store.id }, data });\n  return res.json({ success: true, message: \"Store updated\", data: updated });\n};\n\n// Delete store\nexport const deleteStore = async (req: AuthRequest, res: Response) => {\n  const store = await requireStoreOwner(req.params.id, req.user!.userId, req.user!.role);\n  await prisma.store.delete({ where: { id: store.id } });\n  return res.json({ success: true, message: \"Store deleted\" });\n};\n\n// Update custom domain\nexport const updateDomain = async (req: AuthRequest, res: Response) => {\n  const store  = await requireStoreOwner(req.params.id, req.user!.userId, req.user!.role);\n  const { customDomain } = z.object({ customDomain: z.string().optional() }).parse(req.body);\n\n  if (customDomain) {\n    const existing = await prisma.store.findFirst({\n      where: { customDomain, id: { not: store.id } },\n    });\n    if (existing) throw new AppError(\"Domain already in use\", 409);\n  }\n\n  const updated = await prisma.store.update({\n    where: { id: store.id },\n    data:  { customDomain: customDomain || null },\n  });\n  return res.json({ success: true, message: \"Domain updated\", data: updated });\n};\n\n// Public store by slug\nexport const getPublicStore = async (req: Request, res: Response) => {\n  const store = await prisma.store.findFirst({\n    where: {\n      OR: [{ slug: req.params.slug }, { customDomain: req.params.slug }],\n      status: \"ACTIVE\",\n    },\n    select: {\n      id: true, name: true, slug: true, description: true,\n      logo: true, banner: true, domain: true, customDomain: true,\n      primaryColor: true, secondaryColor: true, accentColor: true,\n      theme: true, fontFamily: true, borderRadius: true, tagline: true,\n      showReviews: true, showInventory: true, productsPerRow: true,\n      currency: true, supportEmail: true, supportPhone: true,\n      supportedCurrencies: true, autoDetectCurrency: true,\n      shippingEnabled: true, metaTitle: true, metaDescription: true,\n    },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n  return res.json({ success: true, data: store });\n};\n\n// ── Helpers ──────────────────────────────────────────────────────────────────\nasync function uniqueSlug(base: string): Promise<string> {\n  let slug = base, i = 1;\n  while (await prisma.store.findUnique({ where: { slug } })) {\n    slug = `${base}-${i++}`;\n  }\n  return slug;\n}\n\nexport async function requireStoreOwner(storeId: string, userId: string, role: string) {\n  const store = await prisma.store.findUnique({ where: { id: storeId } });\n  if (!store) throw new AppError(\"Store not found\", 404);\n  if (store.ownerId !== userId && role !== \"SUPER_ADMIN\") {\n    throw new AppError(\"Not authorized to access this store\", 403);\n  }\n  return store;\n}\n","backend/src/controllers/supercharge.controller.ts":"// ============================================================\n// Supercharge Controller\n// Path: backend/src/controllers/supercharge.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { PrismaClient }         from \"@prisma/client\";\nimport { createBroadcast, getBroadcasts, sendBroadcastNow, generateBroadcastMessage, getAudience } from \"../services/broadcast.service\";\nimport { removeBackground, generateLifestyleImage, generateAdCreative, cloudinaryRemoveBg } from \"../services/image.studio.service\";\nimport { generateForecast, scrapeProductFromUrl } from \"../services/forecast.service\";\n\nconst prisma  = new PrismaClient();\nconst apiKey  = () => process.env.ANTHROPIC_API_KEY || \"\";\nconst repKey  = () => process.env.REPLICATE_API_TOKEN || \"\";\n\n// ── Broadcasts ─────────────────────────────────────────────────\nexport async function listBroadcasts(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    const data = await getBroadcasts(storeId);\n    res.json({ success: true, data });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function createBroadcastHandler(req: Request, res: Response) {\n  try {\n    const { storeId, message, segment, scheduledAt } = req.body;\n    const data = await createBroadcast(storeId, { message, segment, scheduledAt });\n    res.json({ success: true, data });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function sendBroadcastHandler(req: Request, res: Response) {\n  try {\n    const { broadcastId } = req.params;\n    const result = await sendBroadcastNow(broadcastId);\n    res.json({ success: true, data: result });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function generateMessageHandler(req: Request, res: Response) {\n  try {\n    const { storeId, type, productName, discount } = req.body;\n    const message = await generateBroadcastMessage({ storeId, type, productName, discount, apiKey: apiKey() });\n    res.json({ success: true, data: { message } });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function audiencePreview(req: Request, res: Response) {\n  try {\n    const { storeId, segment } = req.query as { storeId: string; segment: string };\n    const audience = await getAudience(storeId, segment);\n    res.json({ success: true, data: { count: audience.length, preview: audience.slice(0, 5) } });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\n// ── Image Studio ───────────────────────────────────────────────\nexport async function removeBg(req: Request, res: Response) {\n  try {\n    const { imageUrl } = req.body;\n    let result: string;\n\n    if (repKey()) {\n      result = await removeBackground(imageUrl, repKey());\n    } else {\n      result = await cloudinaryRemoveBg(imageUrl);\n    }\n    res.json({ success: true, data: { url: result } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\nexport async function generateLifestyle(req: Request, res: Response) {\n  try {\n    if (!repKey()) return res.status(503).json({ success: false, message: \"REPLICATE_API_TOKEN not configured. Add it to Render env vars.\", setupUrl: \"https://replicate.com\" });\n\n    const { imageUrl, backgroundStyle, productName } = req.body;\n    const url = await generateLifestyleImage({ productImageUrl: imageUrl, backgroundStyle, productName, replicateKey: repKey() });\n    res.json({ success: true, data: { url } });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function generateAd(req: Request, res: Response) {\n  try {\n    if (!repKey()) return res.status(503).json({ success: false, message: \"REPLICATE_API_TOKEN not configured.\", setupUrl: \"https://replicate.com\" });\n\n    const { productName, hook, backgroundColor } = req.body;\n    const url = await generateAdCreative({ productName, hook, backgroundColor, replicateKey: repKey() });\n    res.json({ success: true, data: { url } });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\n// ── Forecasting ────────────────────────────────────────────────\nexport async function forecast(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    const data = await generateForecast(storeId, apiKey());\n    res.json({ success: true, data });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\n// ── Product Scraper ────────────────────────────────────────────\nexport async function scrapeProduct(req: Request, res: Response) {\n  try {\n    const { url, storeId } = req.body;\n    if (!url) return res.status(400).json({ success: false, message: \"URL required\" });\n\n    const user = (req as any).user;\n    const store = await prisma.store.findFirst({\n      where: { ownerId: user?.id },\n      select: { country: true },\n    });\n\n    const data = await scrapeProductFromUrl(url, store?.country || \"NG\", apiKey());\n    res.json({ success: true, data });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\n// ── Import scraped product ────────────────────────────────────\nexport async function importScrapedProduct(req: Request, res: Response) {\n  try {\n    const { storeId, product } = req.body;\n    const created = await prisma.product.create({\n      data: {\n        storeId,\n        name: product.name,\n        description: product.description,\n        price: Number(product.sellingPrice || product.suggestedLocalPrice?.replace(/[^\\d]/g, \"\") || 0),\n        costPrice: Number(product.supplierCostLocal || 0),\n        stockQuantity: 50,\n        category: product.category || \"General\",\n        tags: product.tags || [],\n        images: product.images || [],\n        sourceUrl: product.supplierUrl,\n        seoTitle: product.seoTitle,\n        seoDescription: product.seoDescription,\n        isActive: true,\n      },\n    });\n    res.json({ success: true, data: created });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n","backend/src/controllers/theme.controller.ts":"// ============================================================\n// Theme Controller + Routes\n// Path: backend/src/controllers/theme.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { getThemeSettings, saveThemeSettings, applyKAIThemeCommand } from \"../services/theme.service\";\n\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\nexport async function getTheme(req: Request, res: Response) {\n  try {\n    const { storeId } = req.params;\n    const settings = await getThemeSettings(storeId);\n    res.json({ success: true, data: settings });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function updateTheme(req: Request, res: Response) {\n  try {\n    const { storeId }  = req.params;\n    const { settings } = req.body;\n    await saveThemeSettings(storeId, settings);\n    res.json({ success: true, message: \"Theme saved\" });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\nexport async function kaiThemeCommand(req: Request, res: Response) {\n  try {\n    const { storeId }           = req.params;\n    const { instruction, current } = req.body;\n    if (!instruction) return res.status(400).json({ success: false, message: \"instruction required\" });\n    const result = await applyKAIThemeCommand(storeId, instruction, current, apiKey());\n    res.json({ success: true, data: result });\n  } catch (err: any) { res.status(500).json({ success: false, message: err.message }); }\n}\n\n// ── Routes ────────────────────────────────────────────────────\nimport { Router }    from \"express\";\nimport { authenticate } from \"../middleware/auth\";\n\nconst router = Router();\nrouter.use(authenticate);\nrouter.get  (\"/:storeId\",         getTheme);\nrouter.patch(\"/:storeId\",         updateTheme);\nrouter.post (\"/:storeId/kai\",     kaiThemeCommand);\nexport default router;\n\n// Add to app.ts:\n// import themeRoutes from \"./routes/theme.routes\";\n// app.use(\"/api/theme\", themeRoutes);\n","backend/src/controllers/twoFA.controller.ts":"// src/controllers/twoFA.controller.ts\nimport { Response } from \"express\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport speakeasy from \"speakeasy\";\nimport qrcode from \"qrcode\";\n\n// POST /auth/2fa/setup  — generate secret & QR\nexport const setup2FA = async (req: AuthRequest, res: Response) => {\n  const user = await prisma.user.findUnique({ where: { id: req.user!.userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n  if (user.twoFAEnabled) throw new AppError(\"2FA is already enabled\", 400);\n\n  const secret = speakeasy.generateSecret({ name: `DropOS (${user.email})`, issuer: \"DropOS\" });\n\n  // Store temp secret (not enabled yet until verified)\n  await prisma.user.update({ where: { id: user.id }, data: { twoFASecret: secret.base32 } });\n\n  const qrDataUrl = await qrcode.toDataURL(secret.otpauth_url!);\n\n  res.json({ success: true, data: { secret: secret.base32, qrCode: qrDataUrl } });\n};\n\n// POST /auth/2fa/verify  — verify TOTP and enable\nexport const verify2FA = async (req: AuthRequest, res: Response) => {\n  const { token } = req.body;\n  if (!token) throw new AppError(\"Token required\", 400);\n\n  const user = await prisma.user.findUnique({ where: { id: req.user!.userId } });\n  if (!user?.twoFASecret) throw new AppError(\"2FA setup not initiated\", 400);\n  if (user.twoFAEnabled) throw new AppError(\"2FA already enabled\", 400);\n\n  const valid = speakeasy.totp.verify({\n    secret: user.twoFASecret, encoding: \"base32\",\n    token: token.replace(/\\s/g, \"\"), window: 2,\n  });\n\n  if (!valid) throw new AppError(\"Invalid authentication code\", 400);\n\n  await prisma.user.update({ where: { id: user.id }, data: { twoFAEnabled: true } });\n\n  res.json({ success: true, message: \"Two-factor authentication has been enabled.\" });\n};\n\n// POST /auth/2fa/disable\nexport const disable2FA = async (req: AuthRequest, res: Response) => {\n  const { token, password } = req.body;\n  if (!token) throw new AppError(\"Authentication code required\", 400);\n\n  const user = await prisma.user.findUnique({ where: { id: req.user!.userId } });\n  if (!user?.twoFAEnabled) throw new AppError(\"2FA is not enabled\", 400);\n\n  const valid = speakeasy.totp.verify({\n    secret: user.twoFASecret!, encoding: \"base32\",\n    token: token.replace(/\\s/g, \"\"), window: 2,\n  });\n\n  if (!valid) throw new AppError(\"Invalid authentication code\", 400);\n\n  await prisma.user.update({ where: { id: user.id }, data: { twoFAEnabled: false, twoFASecret: null } });\n\n  res.json({ success: true, message: \"Two-factor authentication has been disabled.\" });\n};\n\n// POST /auth/2fa/validate  — used during login flow\nexport const validate2FALogin = async (req: AuthRequest, res: Response) => {\n  const { userId, token } = req.body;\n  if (!userId || !token) throw new AppError(\"userId and token required\", 400);\n\n  const user = await prisma.user.findUnique({ where: { id: userId } });\n  if (!user?.twoFAEnabled || !user.twoFASecret) throw new AppError(\"2FA not set up for this user\", 400);\n\n  const valid = speakeasy.totp.verify({\n    secret: user.twoFASecret, encoding: \"base32\",\n    token: token.replace(/\\s/g, \"\"), window: 2,\n  });\n\n  if (!valid) throw new AppError(\"Invalid authentication code\", 401);\n\n  res.json({ success: true, message: \"2FA verified successfully\" });\n};\n","backend/src/controllers/upsell.controller.ts":"// src/controllers/upsell.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\n\n// ─── Get related/upsell products for a given product ─────────────────────────\n// Strategy: same category > same price range > most reviewed > newest\nexport const getUpsellProducts = async (req: Request, res: Response) => {\n  const { storeId, productId } = req.params;\n  const limit = Math.min(Number(req.query.limit) || 4, 8);\n\n  const product = await prisma.product.findFirst({\n    where: { id: productId, storeId, status: \"ACTIVE\" },\n    select: { id: true, price: true, category: true, name: true },\n  });\n  if (!product) throw new AppError(\"Product not found\", 404);\n\n  // 1. Same category (exclude self)\n  let related = await prisma.product.findMany({\n    where: {\n      storeId,\n      status: \"ACTIVE\",\n      id: { not: productId },\n      category: product.category || undefined,\n    },\n    orderBy: [{ reviews: { _count: \"desc\" } }, { createdAt: \"desc\" }],\n    take: limit,\n    select: {\n      id: true, name: true, price: true, comparePrice: true,\n      images: true, slug: true, inventory: true,\n      _count: { select: { reviews: true } },\n    },\n  });\n\n  // 2. If not enough, fill with price-range products\n  if (related.length < limit) {\n    const priceLow  = product.price * 0.6;\n    const priceHigh = product.price * 1.6;\n    const existingIds = [productId, ...related.map(r => r.id)];\n\n    const extras = await prisma.product.findMany({\n      where: {\n        storeId, status: \"ACTIVE\",\n        id: { notIn: existingIds },\n        price: { gte: priceLow, lte: priceHigh },\n      },\n      orderBy: { createdAt: \"desc\" },\n      take: limit - related.length,\n      select: {\n        id: true, name: true, price: true, comparePrice: true,\n        images: true, slug: true, inventory: true,\n        _count: { select: { reviews: true } },\n      },\n    });\n    related = [...related, ...extras];\n  }\n\n  // 3. Still not enough — just return latest active products\n  if (related.length < limit) {\n    const existingIds = [productId, ...related.map(r => r.id)];\n    const extras = await prisma.product.findMany({\n      where: { storeId, status: \"ACTIVE\", id: { notIn: existingIds } },\n      orderBy: { createdAt: \"desc\" },\n      take: limit - related.length,\n      select: {\n        id: true, name: true, price: true, comparePrice: true,\n        images: true, slug: true, inventory: true,\n        _count: { select: { reviews: true } },\n      },\n    });\n    related = [...related, ...extras];\n  }\n\n  res.json({ success: true, data: related });\n};\n\n// ─── Get \"frequently bought together\" (based on co-occurrence in orders) ──────\nexport const getFrequentlyBoughtTogether = async (req: Request, res: Response) => {\n  const { storeId, productId } = req.params;\n  const limit = Math.min(Number(req.query.limit) || 3, 6);\n\n  // Find orders that contain this product\n  const orderIds = await prisma.orderItem.findMany({\n    where: { productId },\n    select: { orderId: true },\n    take: 200, // look at last 200 orders containing this product\n  });\n\n  if (orderIds.length === 0) {\n    return res.json({ success: true, data: [] });\n  }\n\n  const ids = orderIds.map(o => o.orderId);\n\n  // Find other products in those orders\n  const coItems = await prisma.orderItem.groupBy({\n    by: [\"productId\"],\n    where: {\n      orderId: { in: ids },\n      productId: { not: productId },\n    },\n    _count: { productId: true },\n    orderBy: { _count: { productId: \"desc\" } },\n    take: limit,\n  });\n\n  if (coItems.length === 0) return res.json({ success: true, data: [] });\n\n  const productIds = coItems.map(i => i.productId);\n  const products = await prisma.product.findMany({\n    where: { id: { in: productIds }, storeId, status: \"ACTIVE\" },\n    select: {\n      id: true, name: true, price: true, comparePrice: true, images: true, slug: true,\n    },\n  });\n\n  // Sort by co-occurrence frequency\n  const sorted = productIds\n    .map(id => products.find(p => p.id === id))\n    .filter(Boolean);\n\n  res.json({ success: true, data: sorted });\n};\n\n// ─── Cart upsell: items to suggest at checkout based on cart contents ─────────\nexport const getCartUpsell = async (req: Request, res: Response) => {\n  const { storeId } = req.params;\n  const productIds: string[] = req.body.productIds || [];\n  const limit = Math.min(Number(req.query.limit) || 3, 6);\n\n  if (!productIds.length) return res.json({ success: true, data: [] });\n\n  // Get categories of cart items\n  const cartProducts = await prisma.product.findMany({\n    where: { id: { in: productIds }, storeId },\n    select: { category: true, price: true },\n  });\n\n  const categories = [...new Set(cartProducts.map(p => p.category).filter(Boolean))];\n  const avgPrice   = cartProducts.reduce((s, p) => s + p.price, 0) / cartProducts.length;\n\n  // Find complementary items — same category, not already in cart, lower price (accessories)\n  const suggestions = await prisma.product.findMany({\n    where: {\n      storeId, status: \"ACTIVE\",\n      id: { notIn: productIds },\n      category: categories.length ? { in: categories as string[] } : undefined,\n      price: { lte: avgPrice * 0.7 }, // suggest items that are cheaper (accessories)\n    },\n    orderBy: [{ reviews: { _count: \"desc\" } }],\n    take: limit,\n    select: {\n      id: true, name: true, price: true, comparePrice: true, images: true, slug: true,\n    },\n  });\n\n  res.json({ success: true, data: suggestions });\n};\n","backend/src/controllers/waitlist.controller.ts":"// backend/src/controllers/waitlist.controller.ts\nimport { Request, Response } from \"express\";\nimport { PrismaClient } from \"@prisma/client\";\nimport { Resend } from \"resend\";\nimport crypto from \"crypto\";\nimport { z } from \"zod\";\n\nconst prisma = new PrismaClient();\nconst resend = new Resend(process.env.RESEND_API_KEY);\n\n// ── Rate limit store ──────────────────────────────────────────\nconst rateLimitMap = new Map<string, { count: number; resetAt: number }>();\n\nfunction checkRateLimit(ipHash: string): boolean {\n  const now = Date.now();\n  const entry = rateLimitMap.get(ipHash);\n  if (!entry || now > entry.resetAt) {\n    rateLimitMap.set(ipHash, { count: 1, resetAt: now + 60 * 60 * 1000 });\n    return true;\n  }\n  if (entry.count >= 5) return false;\n  entry.count++;\n  return true;\n}\n\n// ── Input schema ──────────────────────────────────────────────\nconst waitlistSchema = z.object({\n  name:     z.string().min(2).max(60).trim(),\n  email:    z.string().email().max(100).toLowerCase().trim(),\n  whatsapp: z.string().max(20).optional(),\n  honeypot: z.string().max(0).optional(),\n  ref:      z.string().max(20).optional(),\n  source:   z.string().max(50).optional(),\n});\n\n// ── Helpers ───────────────────────────────────────────────────\nfunction genReferralCode(): string {\n  return crypto.randomBytes(4).toString(\"hex\").toUpperCase();\n}\n\nfunction hashIP(ip: string): string {\n  return crypto\n    .createHash(\"sha256\")\n    .update(ip + (process.env.JWT_SECRET || \"dropos-salt\"))\n    .digest(\"hex\")\n    .slice(0, 16);\n}\n\n// ── PRIMARY INBOX EMAIL ───────────────────────────────────────\n// Strategy: Make Gmail think this is a real conversation.\n// - Subject: \"quick question\" = personal, not marketing\n// - No links = zero promotional signals\n// - Ends with a question = invites reply\n// - When they reply = thread moves to Primary permanently\n// - Gmail learns domain = conversational = Primary for everyone after\n// - No HTML, no headers, nothing that signals bulk/marketing\n// ─────────────────────────────────────────────────────────────\nfunction buildPrimaryEmail(firstName: string): string {\n  return `Hi ${firstName},\n\nGot your signup — you're on the list.\n\nQuick question before we launch: what do you currently sell, or what have you been wanting to sell online?\n\nJust reply to this email. I read every one personally.\n\nOlamide\nDropOS`;\n}\n\n// Follow-up email sent separately (24hrs later) with referral link.\n// Keeping links out of first email = Primary inbox guaranteed.\n// Second email uses \"Re:\" prefix = Gmail sees it as same thread = Primary.\nfunction buildFollowUpEmail(firstName: string, referralCode: string): string {\n  const shareUrl = `https://droposhq.com?ref=${referralCode}`;\n\n  return `Hi ${firstName},\n\nOne thing I forgot to mention.\n\nIf you share DropOS with 3 people who join the waitlist, you get 3 months of our Growth plan free when we launch.\n\nYour link: ${shareUrl}\n\nReally glad you're on the list.\n\nOlamide\nDropOS`;\n}\n\n// ── JOIN WAITLIST ─────────────────────────────────────────────\nexport const joinWaitlist = async (req: Request, res: Response) => {\n  try {\n    // 1. Validate\n    const body = waitlistSchema.safeParse(req.body);\n    if (!body.success) {\n      return res.status(400).json({\n        success: false,\n        message: \"Please check your details and try again.\",\n      });\n    }\n\n    const { name, email, whatsapp, honeypot, ref, source } = body.data;\n\n    // 2. Honeypot\n    if (honeypot && honeypot.length > 0) {\n      return res.json({ success: true, message: \"You've been added!\", spot: 999 });\n    }\n\n    // 3. Rate limit\n    const ip = req.ip || req.socket.remoteAddress || \"unknown\";\n    const ipHash = hashIP(ip);\n    if (!checkRateLimit(ipHash)) {\n      return res.status(429).json({\n        success: false,\n        message: \"Too many attempts. Please try again in an hour.\",\n      });\n    }\n\n    // 4. Duplicate check\n    const existing = await prisma.waitlistEntry.findUnique({ where: { email } });\n    if (existing) {\n      return res.status(200).json({\n        success: true,\n        alreadyExists: true,\n        message: \"You're already on the waitlist! 😄\",\n        spot: existing.spotNumber,\n        referralCode: existing.referralCode,\n        shareUrl: `https://droposhq.com?ref=${existing.referralCode}`,\n      });\n    }\n\n    // 5. Spot number\n    const count = await prisma.waitlistEntry.count();\n    const spotNumber = count + 1;\n\n    // 6. Referral\n    let referredBy: string | undefined;\n    if (ref) {\n      const referrer = await prisma.waitlistEntry.findUnique({\n        where: { referralCode: ref },\n      });\n      if (referrer) referredBy = ref;\n    }\n\n    // 7. Unique referral code\n    let referralCode = genReferralCode();\n    while (await prisma.waitlistEntry.findUnique({ where: { referralCode } })) {\n      referralCode = genReferralCode();\n    }\n\n    // 8. Save\n    await prisma.waitlistEntry.create({\n      data: {\n        name,\n        email,\n        whatsapp: whatsapp || null,\n        spotNumber,\n        referralCode,\n        referredBy: referredBy || null,\n        source: source || \"direct\",\n        ipHash,\n        confirmed: true,\n      },\n    });\n\n    // 9. Send Primary inbox email\n    const firstName = name.split(\" \")[0];\n\n    try {\n      const result = await resend.emails.send({\n        from: `Olamide from DropOS <olamide@droposhq.com>`,\n        replyTo: `olamide@droposhq.com`,\n        to: email,\n        subject: `quick question, ${firstName}`,\n        text: buildPrimaryEmail(firstName),\n        // Deliberately NO html\n        // Deliberately NO List-Unsubscribe\n        // Deliberately NO Precedence\n        // Deliberately NO marketing signals\n      });\n      console.log(\"[Waitlist Email] Sent:\", result.data?.id);\n    } catch (emailErr) {\n      console.error(\"[Waitlist Email Error]\", emailErr);\n    }\n\n    return res.json({\n      success: true,\n      message: \"You're on the waitlist!\",\n      spot: spotNumber,\n      referralCode,\n      shareUrl: `https://droposhq.com?ref=${referralCode}`,\n    });\n  } catch (err: any) {\n    console.error(\"[Waitlist Error]\", err);\n    return res.status(500).json({\n      success: false,\n      message: \"Something went wrong. Please try again.\",\n    });\n  }\n};\n\n// ── GET STATS ─────────────────────────────────────────────────\nexport const getWaitlistStats = async (_req: Request, res: Response) => {\n  const count = await prisma.waitlistEntry.count();\n  return res.json({\n    success: true,\n    data: { count, spotsLeft: Math.max(0, 1000 - count) },\n  });\n};\n\n// ── ADMIN — all entries ───────────────────────────────────────\nexport const getWaitlistEntries = async (_req: Request, res: Response) => {\n  const [entries, total] = await Promise.all([\n    prisma.waitlistEntry.findMany({\n      orderBy: { createdAt: \"desc\" },\n      select: {\n        id: true, name: true, email: true,\n        whatsapp: true, referralCode: true,\n        spotNumber: true, source: true,\n        referredBy: true, createdAt: true,\n      },\n    }),\n    prisma.waitlistEntry.count(),\n  ]);\n  return res.json({ success: true, data: { entries, total } });\n};\n\n// ── DELETE entry ──────────────────────────────────────────────\nexport const deleteWaitlistEntry = async (req: Request, res: Response) => {\n  const { id } = req.params;\n  const entry = await prisma.waitlistEntry.findUnique({ where: { id } });\n  if (!entry) return res.status(404).json({ success: false, message: \"Entry not found\" });\n  await prisma.waitlistEntry.delete({ where: { id } });\n  return res.json({ success: true, message: \"Entry deleted\" });\n};\n\n// ── RESEND confirmation ───────────────────────────────────────\nexport const resendWaitlistEmail = async (req: Request, res: Response) => {\n  const { id } = req.params;\n  const entry = await prisma.waitlistEntry.findUnique({ where: { id } });\n  if (!entry) return res.status(404).json({ success: false, message: \"Entry not found\" });\n\n  const firstName = entry.name.split(\" \")[0];\n  await resend.emails.send({\n    from: `Olamide from DropOS <olamide@droposhq.com>`,\n    replyTo: `olamide@droposhq.com`,\n    to: entry.email,\n    subject: `quick question, ${firstName}`,\n    text: buildPrimaryEmail(firstName),\n  });\n\n  return res.json({ success: true, message: \"Email resent\" });\n};\n\n// ── SEND FOLLOW-UP with referral link ────────────────────────\n// Send this 24 hours after signup\n// \"Re:\" prefix = Gmail treats as reply thread = Primary inbox\nexport const sendFollowUpEmail = async (req: Request, res: Response) => {\n  const { id } = req.params;\n  const entry = await prisma.waitlistEntry.findUnique({ where: { id } });\n  if (!entry) return res.status(404).json({ success: false, message: \"Entry not found\" });\n\n  const firstName = entry.name.split(\" \")[0];\n  await resend.emails.send({\n    from: `Olamide from DropOS <olamide@droposhq.com>`,\n    replyTo: `olamide@droposhq.com`,\n    to: entry.email,\n    subject: `Re: quick question, ${firstName}`,\n    text: buildFollowUpEmail(firstName, entry.referralCode),\n  });\n\n  return res.json({ success: true, message: \"Follow-up sent\" });\n};","backend/src/controllers/webhook.controller.ts":"// src/controllers/webhook.controller.ts\nimport { Response } from \"express\";\nimport nodeFetch from \"node-fetch\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport crypto from \"crypto\";\n\nconst VALID_EVENTS = [\n  \"order.created\",\"order.paid\",\"order.shipped\",\"order.completed\",\"order.cancelled\",\"order.refunded\",\n  \"product.created\",\"product.updated\",\"product.deleted\",\n  \"customer.created\",\"review.submitted\",\n];\n\nconst createSchema = z.object({\n  url:    z.string().url(),\n  events: z.array(z.enum(VALID_EVENTS as [string,...string[]])).min(1),\n});\n\n// POST /webhooks/:storeId\nexport const createWebhook = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const data = createSchema.parse(req.body);\n  const secret = `whsec_${crypto.randomBytes(32).toString(\"hex\")}`;\n\n  const count = await prisma.storeWebhook.count({ where: { storeId, isActive: true } });\n  if (count >= 5) throw new AppError(\"Maximum 5 webhooks per store\", 400);\n\n  const webhook = await prisma.storeWebhook.create({\n    data: { storeId, url: data.url, events: data.events, secret },\n    select: { id: true, url: true, events: true, isActive: true, createdAt: true, secret: true },\n  });\n\n  res.status(201).json({ success: true, data: { ...webhook, warning: \"Store your signing secret securely — used to verify webhook authenticity.\" } });\n};\n\n// GET /webhooks/:storeId\nexport const getWebhooks = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const webhooks = await prisma.storeWebhook.findMany({\n    where: { storeId },\n    select: { id: true, url: true, events: true, isActive: true, lastFiredAt: true, failCount: true, createdAt: true },\n    include: { deliveries: { take: 5, orderBy: { createdAt: \"desc\" }, select: { event: true, success: true, statusCode: true, createdAt: true } } },\n  });\n\n  res.json({ success: true, data: webhooks });\n};\n\n// DELETE /webhooks/:storeId/:webhookId\nexport const deleteWebhook = async (req: AuthRequest, res: Response) => {\n  const { storeId, webhookId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  await prisma.storeWebhook.deleteMany({ where: { id: webhookId, storeId } });\n  res.json({ success: true });\n};\n\n// PATCH /webhooks/:storeId/:webhookId\nexport const updateWebhook = async (req: AuthRequest, res: Response) => {\n  const { storeId, webhookId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n  const { events, isActive } = req.body;\n\n  const updated = await prisma.storeWebhook.update({\n    where: { id: webhookId }, data: { events, isActive },\n    select: { id: true, url: true, events: true, isActive: true },\n  });\n\n  res.json({ success: true, data: updated });\n};\n\n// POST /webhooks/:storeId/:webhookId/test\nexport const testWebhook = async (req: AuthRequest, res: Response) => {\n  const { storeId, webhookId } = req.params;\n  await verifyOwner(storeId, req.user!.userId);\n\n  const webhook = await prisma.storeWebhook.findFirst({ where: { id: webhookId, storeId } });\n  if (!webhook) throw new AppError(\"Webhook not found\", 404);\n\n  const payload = { event: \"test\", storeId, timestamp: new Date().toISOString(), data: { message: \"Test delivery from DropOS\" } };\n  const body = JSON.stringify(payload);\n  const sig = crypto.createHmac(\"sha256\", webhook.secret).update(body).digest(\"hex\");\n\n  try {\n    const response = await nodeFetch(webhook.url, {\n      method: \"POST\", body,\n      headers: { \"Content-Type\": \"application/json\", \"X-DropOS-Signature\": `sha256=${sig}`, \"X-DropOS-Event\": \"test\" },\n      timeout: 10000,\n    } as any);\n\n    await prisma.storeWebhook.update({ where: { id: webhookId }, data: { lastFiredAt: new Date() } });\n    await prisma.webhookDelivery.create({ data: { webhookId, event: \"test\", payload, statusCode: response.status, success: response.ok } });\n\n    res.json({ success: true, data: { statusCode: response.status, ok: response.ok } });\n  } catch (err: any) {\n    await prisma.webhookDelivery.create({ data: { webhookId, event: \"test\", payload, success: false, response: err.message } });\n    res.json({ success: false, message: `Delivery failed: ${err.message}` });\n  }\n};\n\n// Internal: fire webhook for an event\nexport async function fireWebhook(storeId: string, event: string, data: any) {\n  const webhooks = await prisma.storeWebhook.findMany({ where: { storeId, events: { has: event }, isActive: true } });\n\n  for (const wh of webhooks) {\n    const payload = { event, storeId, timestamp: new Date().toISOString(), data };\n    const body = JSON.stringify(payload);\n    const sig = crypto.createHmac(\"sha256\", wh.secret).update(body).digest(\"hex\");\n\n    try {\n      const res = await nodeFetch(wh.url, {\n        method: \"POST\", body,\n        headers: { \"Content-Type\": \"application/json\", \"X-DropOS-Signature\": `sha256=${sig}`, \"X-DropOS-Event\": event },\n        timeout: 15000,\n      });\n\n      await prisma.storeWebhook.update({ where: { id: wh.id }, data: { lastFiredAt: new Date(), failCount: res.ok ? 0 : { increment: 1 } } });\n      await prisma.webhookDelivery.create({ data: { webhookId: wh.id, event, payload, statusCode: (res as any).status as number, success: !!(res as any).ok } });\n    } catch (err: any) {\n      await prisma.storeWebhook.update({ where: { id: wh.id }, data: { failCount: { increment: 1 } } });\n      await prisma.webhookDelivery.create({ data: { webhookId: wh.id, event, payload, success: false, response: err.message } });\n    }\n  }\n}\n\nasync function verifyOwner(storeId: string, userId: string) {\n  const store = await prisma.store.findFirst({ where: { id: storeId, ownerId: userId } });\n  if (!store) throw new AppError(\"Unauthorized\", 403);\n}\n"};
